namespace core3d::scene {

struct SceneCopyStorage final {
    std::size_t numeric = 0;
    std::size_t encoded = 0;
    std::size_t privateBytes = 0;
};

bool DeepStringStorageBytes(const std::string& value,
                            std::size_t& total) noexcept
{
    if (value.capacity() == 0) return true;
    const std::uintptr_t data = reinterpret_cast<std::uintptr_t>(value.data());
    const std::uintptr_t first = reinterpret_cast<std::uintptr_t>(&value);
    if (data >= first && data < first + sizeof(value)) return true;
    if (value.capacity() == std::numeric_limits<std::size_t>::max()
        || value.capacity() + 1U
            > std::numeric_limits<std::size_t>::max() - total)
        return false;
    total += value.capacity() + 1U;
    return true;
}

bool DeepVectorStorageBytes(std::size_t& total,
                            std::size_t capacity,
                            std::size_t element) noexcept
{
    if (capacity != 0
        && element > std::numeric_limits<std::size_t>::max() / capacity)
        return false;
    const std::size_t bytes = capacity * element;
    if (bytes > std::numeric_limits<std::size_t>::max() - total) return false;
    total += bytes;
    return true;
}

template <typename Primitive, typename = void>
struct HasAnalyticSourceFace final : std::false_type {};

template <typename Primitive>
struct HasAnalyticSourceFace<Primitive, std::void_t<decltype(
    std::declval<const Primitive&>().analyticSourceFace)>> final
    : std::true_type {};

template <typename Primitive>
bool DeepPrimitiveStorageBytes(const Primitive& primitive,
                               SceneCopyStorage& total) noexcept
{
    if constexpr (HasAnalyticSourceFace<Primitive>::value) {
        return DeepVectorStorageBytes(total.numeric,
                primitive.analyticSourceFace.params.capacity(),
                sizeof(double))
            && DeepStringStorageBytes(primitive.analyticSourceFace.digest,
                total.privateBytes);
    }
    return true;
}

template <typename Primitive>
bool SamePrimitive(const Primitive& left, const Primitive& right) noexcept
{
    if (left.firstIndex != right.firstIndex
        || left.indexCount != right.indexCount
        || left.faceIndex != right.faceIndex
        || left.hasTextureCoordinates != right.hasTextureCoordinates)
        return false;
    if constexpr (HasAnalyticSourceFace<Primitive>::value) {
        const auto& leftWitness = left.analyticSourceFace;
        const auto& rightWitness = right.analyticSourceFace;
        return leftWitness.available == rightWitness.available
            && leftWitness.surfaceType == rightWitness.surfaceType
            && leftWitness.reversed == rightWitness.reversed
            && leftWitness.params == rightWitness.params
            && leftWitness.digest == rightWitness.digest;
    }
    return true;
}

bool SamePrimitives(const std::vector<MeshPrimitive>& left,
                    const std::vector<MeshPrimitive>& right) noexcept
{
    if (left.size() != right.size()) return false;
    for (std::size_t index = 0; index < left.size(); ++index)
        if (!SamePrimitive(left[index], right[index])) return false;
    return true;
}

bool DeepMeshStorageBytes(const MeshSnapshot& mesh,
                          SceneCopyStorage& total) noexcept
{
    if (!DeepStringStorageBytes(mesh.definitionIdentifier, total.privateBytes)
        || !DeepStringStorageBytes(
            mesh.paintedAtlasMasterDefinitionIdentifier, total.privateBytes)
        || !DeepStringStorageBytes(mesh.paintedAtlasBakeProof,
            total.privateBytes)
        || !DeepVectorStorageBytes(total.numeric, mesh.vertices.capacity(),
            sizeof(Vertex))
        || !DeepVectorStorageBytes(total.numeric, mesh.indices.capacity(),
            sizeof(std::uint32_t))
        || !DeepVectorStorageBytes(total.numeric, mesh.primitives.capacity(),
            sizeof(MeshPrimitive))
        || !DeepVectorStorageBytes(total.numeric,
            mesh.cornerTangents.capacity(), sizeof(Float4)))
        return false;
    for (const auto& primitive : mesh.primitives)
        if (!DeepPrimitiveStorageBytes(primitive, total)) return false;
    return !mesh.nativeC1Wire
        || (DeepVectorStorageBytes(total.privateBytes,
                mesh.nativeC1Wire->canonicalDefinitionBytes.capacity(), 1U)
            && DeepVectorStorageBytes(total.privateBytes,
                mesh.nativeC1Wire->canonicalOwnerBytes.capacity(), 1U));
}

bool DeepInstanceStorageBytes(const InstanceSnapshot& instance,
                              SceneCopyStorage& total) noexcept
{
    if (!DeepStringStorageBytes(instance.entityIdentifier, total.privateBytes)
        || !DeepStringStorageBytes(instance.name, total.privateBytes)
        || !DeepStringStorageBytes(instance.groupIdentifier, total.privateBytes)
        || !DeepStringStorageBytes(instance.groupName, total.privateBytes)
        || !DeepVectorStorageBytes(total.numeric,
            instance.primitiveBindings.capacity(), sizeof(PrimitiveBinding))
        || !DeepVectorStorageBytes(total.numeric,
            instance.faceImageBindings.capacity(),
            sizeof(FaceImageBindingSnapshot))
        || !DeepVectorStorageBytes(total.numeric,
            instance.decalDerivedAppearances.capacity(),
            sizeof(DecalDerivedAppearanceSnapshot)))
        return false;
    if (instance.nativeWirePresentation
        && !DeepStringStorageBytes(
            instance.nativeWirePresentation->identifier, total.privateBytes))
        return false;
    for (const auto& binding : instance.faceImageBindings)
        if (!DeepStringStorageBytes(binding.bindingIdentifier,
                total.privateBytes)
            || !DeepStringStorageBytes(binding.faceIdentifier,
                total.privateBytes)
            || !DeepStringStorageBytes(binding.resourceIdentifier,
                total.privateBytes))
            return false;
    for (const auto& appearance : instance.decalDerivedAppearances)
        if (!DeepStringStorageBytes(appearance.ownerDefinitionIdentifier,
                total.privateBytes)
            || !DeepStringStorageBytes(appearance.bakeProof,
                total.privateBytes))
            return false;
    return true;
}

bool DeepSceneStorageBytes(const SceneSnapshot& scene,
                           SceneCopyStorage& total) noexcept
{
    total = {};
    if (!DeepStringStorageBytes(
            scene.publicationSourceIdentifier, total.privateBytes)
        || !DeepVectorStorageBytes(total.numeric, scene.meshes.capacity(),
            sizeof(MeshSnapshot))
        || !DeepVectorStorageBytes(total.numeric, scene.instances.capacity(),
            sizeof(InstanceSnapshot))
        || !DeepVectorStorageBytes(total.numeric, scene.materials.capacity(),
            sizeof(MaterialSnapshot))
        || !DeepVectorStorageBytes(total.numeric, scene.textures.capacity(),
            sizeof(TextureResourceSnapshot))
        || !DeepVectorStorageBytes(total.numeric, scene.pickTable.capacity(),
            sizeof(ElementIdentifier))
        || !DeepVectorStorageBytes(total.numeric,
            scene.selection.selected.capacity(),
            sizeof(ElementIdentifier))) return false;
    for (const auto& mesh : scene.meshes)
        if (!DeepMeshStorageBytes(mesh, total)) return false;
    for (const auto& instance : scene.instances)
        if (!DeepInstanceStorageBytes(instance, total)) return false;
    for (const auto& material : scene.materials)
        if (!DeepStringStorageBytes(material.identifier, total.privateBytes))
            return false;
    for (const auto& texture : scene.textures)
        if (!DeepStringStorageBytes(texture.identifier, total.privateBytes)
            || !DeepVectorStorageBytes(total.encoded,
                texture.encodedBytes.capacity(), 1U))
            return false;
    for (const auto& value : scene.pickTable)
        if (!DeepStringStorageBytes(value.entityIdentifier,
                total.privateBytes)) return false;
    for (const auto& value : scene.selection.selected)
        if (!DeepStringStorageBytes(value.entityIdentifier,
                total.privateBytes)) return false;
    if (scene.selection.hovered
        && !DeepStringStorageBytes(scene.selection.hovered->entityIdentifier,
            total.privateBytes)) return false;
    return true;
}

// The figure below is deliberately an observable-representation census, not
// an allocator/RSS estimate.  O1--O33 name the ratified opaque remainder; a
// value omitted behind one of those boundaries is reported as unmeasured and
// is never represented by an exact zero.
struct BRepRepresentationCensus final {
    std::size_t total = 0;
    std::size_t tShapes = 0;
    std::size_t listNodes = 0;
    std::size_t locations = 0;
    std::size_t locationNodes = 0;
    std::size_t locationDatums = 0;
    std::size_t representations = 0;
    std::size_t geometry = 0;
    std::size_t meshLogical = 0;
    std::size_t meshPhysical = 0;
    std::size_t meshNodes = 0;
    std::size_t meshTriangles = 0;
    std::size_t meshUVNodes = 0;
    std::size_t meshNormals = 0;
    std::size_t polygonStorage = 0;
    std::size_t harrayStorage = 0;
    std::size_t observableMapScratch = 0;
    std::size_t visibleDownstreamScratch = 0;
    std::size_t topologyCount = 0;
    std::size_t faceCount = 0;
    std::size_t targetCopyEntries = 0;
    bool measuredEquality = false;
    bool opaqueRemainderNotMeasured = true;
    bool actualMeshNodesAreDouble = true;
    bool actualMeshUVNodesAreDouble = true;
};

class BRepCensusShapeMap final : public TopTools_IndexedMapOfShape {
public:
    static constexpr std::size_t EntrySize() noexcept {
        return sizeof(IndexedMapNode);
    }
};

bool BRepCensusAdd(std::size_t& value, std::size_t increment) noexcept {
    if (increment > std::numeric_limits<std::size_t>::max() - value)
        return false;
    value += increment;
    return true;
}

bool BRepCensusProduct(std::size_t first, std::size_t second,
                       std::size_t& value) noexcept {
    value = 0;
    if (first != 0
        && second > std::numeric_limits<std::size_t>::max() / first)
        return false;
    value = first * second;
    return true;
}

enum class BRepCensusPCurveLookupKind : std::uint8_t {
    Stored,
    NativeNull,
    NeedsPlanarProjection,
    Failure,
};

struct BRepCensusPCurveLookup final {
    BRepCensusPCurveLookupKind kind = BRepCensusPCurveLookupKind::NativeNull;
    Handle(Geom2d_Curve) stored;
    const BRep_CurveRepresentation* representation = nullptr;
    const char* reason = nullptr;
};

constexpr const char* kBRepCensusUnstoredPlanarReason =
    "planar pcurve not stored, generation not admitted (D778)";

Handle(Geom_Curve) BRepCensusFirstCurve3D(
    const Handle(BRep_TEdge)& edge,
    const TopLoc_Location** location = nullptr) noexcept {
    if (location) *location = nullptr;
    if (edge.IsNull()) return {};
    for (const auto& candidate : edge->Curves()) {
        const auto stored = Handle(BRep_Curve3D)::DownCast(candidate);
        if (!stored.IsNull()) {
            if (location) *location = &stored->Location();
            return stored->Curve3D();
        }
    }
    return {};
}

Handle(Poly_Polygon3D) BRepCensusFirstPolygon3D(
    const Handle(BRep_TEdge)& edge,
    const TopLoc_Location** location = nullptr) noexcept {
    if (location) *location = nullptr;
    if (edge.IsNull()) return {};
    for (const auto& candidate : edge->Curves()) {
        const auto stored = Handle(BRep_Polygon3D)::DownCast(candidate);
        if (!stored.IsNull()) {
            if (location) *location = &stored->Location();
            return stored->Polygon3D();
        }
    }
    return {};
}

bool BRepCensusMapCapacity(std::size_t count,
                           std::size_t& capacity) noexcept {
    capacity = 0;
    if (count == 0) return true;
    if (count > std::size_t(std::numeric_limits<Standard_Integer>::max()))
        return false;
    try {
        Standard_Integer next = TCollection::NextPrimeForMap(0);
        while (count > std::size_t(next) + 1) {
            if (next == std::numeric_limits<Standard_Integer>::max())
                return false;
            next = TCollection::NextPrimeForMap(next + 1);
        }
        capacity = std::size_t(next);
        return true;
    } catch (...) {
        return false;
    }
}

bool BRepCensusCountOccurrences(const TopoDS_Shape& shape,
                                std::size_t& count,
                                std::size_t depth = 0) noexcept {
    if (depth >= retained_topology_budget::MaximumTopologyVisits
        || !BRepCensusAdd(count, 1)
        || count > retained_topology_budget::MaximumTopologyVisits)
        return false;
    for (TopoDS_Iterator child(shape, Standard_False, Standard_False);
         child.More(); child.Next())
        if (!BRepCensusCountOccurrences(child.Value(), count, depth + 1))
            return false;
    return true;
}

bool BRepCensusTerm(BRepRepresentationCensus& census, std::size_t& term,
                    std::size_t bytes) noexcept {
    return BRepCensusAdd(term, bytes) && BRepCensusAdd(census.total, bytes);
}

bool BRepCensusAccumulate(BRepRepresentationCensus& target,
                          const BRepRepresentationCensus& value) noexcept {
    return BRepCensusAdd(target.total, value.total)
        && BRepCensusAdd(target.locations, value.locations)
        && BRepCensusAdd(target.locationNodes, value.locationNodes)
        && BRepCensusAdd(target.locationDatums, value.locationDatums)
        && BRepCensusAdd(target.representations, value.representations)
        && BRepCensusAdd(target.geometry, value.geometry)
        && BRepCensusAdd(target.meshLogical, value.meshLogical)
        && BRepCensusAdd(target.meshPhysical, value.meshPhysical)
        && BRepCensusAdd(target.meshNodes, value.meshNodes)
        && BRepCensusAdd(target.meshTriangles, value.meshTriangles)
        && BRepCensusAdd(target.meshUVNodes, value.meshUVNodes)
        && BRepCensusAdd(target.meshNormals, value.meshNormals)
        && BRepCensusAdd(target.polygonStorage, value.polygonStorage)
        && BRepCensusAdd(target.harrayStorage, value.harrayStorage)
        && BRepCensusAdd(target.observableMapScratch,
            value.observableMapScratch);
}

bool BRepCensusApplyBundleDelta(
    BRepRepresentationCensus& prediction,
    const BRepRepresentationCensus& copiedBundles,
    const BRepRepresentationCensus& sourceBundles) noexcept {
    const auto addDelta = [](std::size_t& target, std::size_t copied,
                             std::size_t source) noexcept {
        return copied >= source && BRepCensusAdd(target, copied - source);
    };
    return addDelta(prediction.total, copiedBundles.total, sourceBundles.total)
        && addDelta(prediction.representations,
            copiedBundles.representations, sourceBundles.representations)
        && addDelta(prediction.geometry,
            copiedBundles.geometry, sourceBundles.geometry)
        && addDelta(prediction.meshLogical,
            copiedBundles.meshLogical, sourceBundles.meshLogical)
        && addDelta(prediction.meshPhysical,
            copiedBundles.meshPhysical, sourceBundles.meshPhysical)
        && addDelta(prediction.meshNodes,
            copiedBundles.meshNodes, sourceBundles.meshNodes)
        && addDelta(prediction.meshTriangles,
            copiedBundles.meshTriangles, sourceBundles.meshTriangles)
        && addDelta(prediction.meshUVNodes,
            copiedBundles.meshUVNodes, sourceBundles.meshUVNodes)
        && addDelta(prediction.meshNormals,
            copiedBundles.meshNormals, sourceBundles.meshNormals)
        && addDelta(prediction.polygonStorage,
            copiedBundles.polygonStorage, sourceBundles.polygonStorage)
        && addDelta(prediction.harrayStorage,
            copiedBundles.harrayStorage, sourceBundles.harrayStorage)
        && addDelta(prediction.observableMapScratch,
            copiedBundles.observableMapScratch,
            sourceBundles.observableMapScratch);
}

enum class BRepCensusLocationNodeKind : std::uint8_t {
    None,
    Concrete,
    Event,
};

enum class BRepCensusLocationOperation : std::uint8_t {
    Product,
    Inverse,
    Merge,
};

struct BRepCensusLocationEvent final {
    std::uint16_t phase = 0;
    std::uint16_t site = 0;
    std::size_t owner = 0;
    std::size_t use = 0;
    std::size_t invocation = 0;
};

struct BRepCensusLocationNodeIdentity final {
    BRepCensusLocationNodeKind kind = BRepCensusLocationNodeKind::None;
    const void* concrete = nullptr;
    BRepCensusLocationEvent event;
    BRepCensusLocationOperation operation =
        BRepCensusLocationOperation::Product;
    std::size_t item = 0;

    bool operator==(const BRepCensusLocationNodeIdentity& other) const noexcept {
        if (kind != other.kind) return false;
        if (kind == BRepCensusLocationNodeKind::Concrete)
            return concrete == other.concrete;
        if (kind != BRepCensusLocationNodeKind::Event) return false;
        return event.phase == other.event.phase
            && event.site == other.event.site
            && event.owner == other.event.owner
            && event.use == other.event.use
            && event.invocation == other.event.invocation
            && operation == other.operation && item == other.item;
    }
};

struct BRepCensusReducedWordItem final {
    const TopLoc_Datum3D* datum = nullptr;
    Standard_Integer power = 0;
    BRepCensusLocationNodeIdentity node;
};

class BRepCensusLocationWord final {
public:
    explicit BRepCensusLocationWord(const TopLoc_Location& location) noexcept
        : location_(&location) {}

    bool Count(std::size_t& count) const noexcept {
        count = 0;
        for (const TopLoc_Location* item = location_;
             item && !item->IsIdentity(); item = &item->NextLocation()) {
            if (!BRepCensusAdd(count, 1)) return false;
        }
        return true;
    }

    bool Read(std::size_t ordinal,
              BRepCensusReducedWordItem& output) const noexcept {
        const TopLoc_Location* item = location_;
        while (item && !item->IsIdentity() && ordinal != 0) {
            item = &item->NextLocation();
            --ordinal;
        }
        if (!item || item->IsIdentity()) return false;
        output = {item->FirstDatum().get(), item->FirstPower(),
            {BRepCensusLocationNodeKind::Concrete,
                &item->FirstDatum(), {},
                BRepCensusLocationOperation::Product, 0}};
        return output.datum && output.power != 0;
    }

private:
    const TopLoc_Location* location_ = nullptr;
};

bool BRepCensusCheckedNegate(Standard_Integer value,
                             Standard_Integer& output) noexcept {
    if (value == std::numeric_limits<Standard_Integer>::min()) return false;
    output = -value;
    return true;
}

bool BRepCensusCheckedPowerAdd(Standard_Integer left, Standard_Integer right,
                               Standard_Integer& output) noexcept {
    if ((right > 0
            && left > std::numeric_limits<Standard_Integer>::max() - right)
        || (right < 0
            && left < std::numeric_limits<Standard_Integer>::min() - right))
        return false;
    output = left + right;
    return true;
}

// The one reduced-word boundary implementation serves both multiplication and
// predivision. It borrows and rescans its operands and never materializes a
// TopLoc product. Valid identity and failure remain separate states.
template <typename LeftWord, typename RightWord, bool Predivide>
class BRepCensusReducedBinaryCursor final {
public:
    enum class OutputOrigin : std::uint8_t { Left, Merge, Right };
    BRepCensusReducedBinaryCursor(
        const LeftWord& left, const RightWord& right) noexcept
        : left_(left), right_(right) { Prepare(); }

    bool Next(BRepCensusReducedWordItem& output) noexcept {
        output = {};
        if (failed_ || emitted_ >= outputCount_) return false;
        if (emitted_ < leftDirectCount_) {
            if (!left_.Read(emitted_, output)) return Fail();
        } else if (hasMerge_ && emitted_ == leftDirectCount_) {
            output = merged_;
        } else {
            const std::size_t offset = emitted_ - leftDirectCount_
                - (hasMerge_ ? 1U : 0U);
            if (offset >= rightDirectCount_) return Fail();
            const std::size_t rightOrdinal = Predivide
                ? rightDirectCount_ - offset - 1
                : cancelledCount_ + (hasMerge_ ? 1U : 0U) + offset;
            if (!right_.Read(rightOrdinal, output)
                || (Predivide
                    && !BRepCensusCheckedNegate(output.power, output.power)))
                return Fail();
        }
        if (!output.datum || output.power == 0) return Fail();
        ++emitted_;
        return true;
    }

    bool Failed() const noexcept { return failed_; }
    std::size_t OutputCount() const noexcept { return outputCount_; }
    std::size_t LeftCount() const noexcept { return leftCount_; }
    std::size_t RightCount() const noexcept { return rightCount_; }
    bool Origin(std::size_t ordinal, OutputOrigin& origin,
                std::size_t& sourceOrdinal) const noexcept {
        sourceOrdinal = 0;
        if (failed_ || ordinal >= outputCount_) return false;
        if (ordinal < leftDirectCount_) {
            origin = OutputOrigin::Left;
            sourceOrdinal = ordinal;
            return true;
        }
        if (hasMerge_ && ordinal == leftDirectCount_) {
            origin = OutputOrigin::Merge;
            sourceOrdinal = cancelledCount_;
            return true;
        }
        const std::size_t offset = ordinal - leftDirectCount_
            - (hasMerge_ ? 1U : 0U);
        if (offset >= rightDirectCount_) return false;
        origin = OutputOrigin::Right;
        sourceOrdinal = Predivide
            ? rightDirectCount_ - offset - 1
            : cancelledCount_ + (hasMerge_ ? 1U : 0U) + offset;
        return true;
    }

private:
    bool Fail() noexcept {
        failed_ = true;
        outputCount_ = 0;
        return false;
    }

    void Prepare() noexcept {
        std::size_t total = 0;
        if (!left_.Count(leftCount_) || !right_.Count(rightCount_)
            || !BRepCensusAdd(total, leftCount_)
            || !BRepCensusAdd(total, rightCount_)) {
            Fail();
            return;
        }
        BRepCensusReducedWordItem item;
        for (std::size_t index = 0; index < leftCount_; ++index) {
            if (!left_.Read(index, item) || !item.datum || item.power == 0) {
                Fail();
                return;
            }
        }
        for (std::size_t index = 0; index < rightCount_; ++index) {
            if (!right_.Read(index, item) || !item.datum || item.power == 0
                || (Predivide
                    && !BRepCensusCheckedNegate(item.power, item.power))) {
                Fail();
                return;
            }
        }

        std::size_t cancelled = 0;
        while (cancelled < leftCount_ && cancelled < rightCount_) {
            BRepCensusReducedWordItem leftItem, rightItem;
            const std::size_t rightOrdinal = Predivide
                ? rightCount_ - cancelled - 1 : cancelled;
            if (!left_.Read(leftCount_ - cancelled - 1, leftItem)
                || !right_.Read(rightOrdinal, rightItem)) {
                Fail();
                return;
            }
            if (leftItem.datum != rightItem.datum) break;
            Standard_Integer rightPower = rightItem.power;
            Standard_Integer mergedPower = 0;
            if ((Predivide
                    && !BRepCensusCheckedNegate(rightPower, rightPower))
                || !BRepCensusCheckedPowerAdd(
                    leftItem.power, rightPower, mergedPower)) {
                Fail();
                return;
            }
            if (mergedPower != 0) {
                hasMerge_ = true;
                merged_ = {leftItem.datum, mergedPower};
                break;
            }
            ++cancelled;
        }

        cancelledCount_ = cancelled;
        const std::size_t mergedItems = hasMerge_ ? 1U : 0U;
        leftDirectCount_ = leftCount_ - cancelled - mergedItems;
        rightDirectCount_ = rightCount_ - cancelled - mergedItems;
        outputCount_ = leftDirectCount_ + rightDirectCount_ + mergedItems;
        if (outputCount_ > total) Fail();
    }

    const LeftWord& left_;
    const RightWord& right_;
    std::size_t leftCount_ = 0;
    std::size_t rightCount_ = 0;
    std::size_t leftDirectCount_ = 0;
    std::size_t rightDirectCount_ = 0;
    std::size_t cancelledCount_ = 0;
    std::size_t outputCount_ = 0;
    std::size_t emitted_ = 0;
    BRepCensusReducedWordItem merged_;
    bool hasMerge_ = false;
    bool failed_ = false;
};

template <typename LeftWord, typename RightWord>
using BRepCensusReducedPredivisionCursor =
    BRepCensusReducedBinaryCursor<LeftWord, RightWord, true>;

template <typename LeftWord, typename RightWord>
class BRepCensusReducedProductWord final {
public:
    BRepCensusReducedProductWord(
        const LeftWord& left, const RightWord& right) noexcept
        : left_(left), right_(right) {}
    bool Count(std::size_t& count) const noexcept {
        BRepCensusReducedBinaryCursor<RightWord, LeftWord, false> cursor(
            right_, left_);
        if (cursor.Failed()) return false;
        count = cursor.OutputCount();
        return true;
    }
    bool Read(std::size_t ordinal,
              BRepCensusReducedWordItem& output) const noexcept {
        BRepCensusReducedBinaryCursor<RightWord, LeftWord, false> cursor(
            right_, left_);
        if (cursor.Failed() || ordinal >= cursor.OutputCount()) return false;
        for (std::size_t index = 0; index <= ordinal; ++index)
            if (!cursor.Next(output)) return false;
        return !cursor.Failed();
    }
private:
    const LeftWord& left_;
    const RightWord& right_;
};

BRepCensusLocationNodeIdentity BRepCensusEventNode(
    const BRepCensusLocationEvent& event,
    BRepCensusLocationOperation operation,
    std::size_t item) noexcept {
    BRepCensusLocationNodeIdentity identity;
    identity.kind = BRepCensusLocationNodeKind::Event;
    identity.event = event;
    identity.operation = operation;
    identity.item = item;
    return identity;
}

// These two views add node provenance to the same checked reducer used by
// effective-word lookup. They mirror TopLoc's allocation semantics without
// constructing a native location: product constructs surviving right-operand
// heads and forwards the left tail; predivision constructs inverse nodes and,
// when both operands are nonidentity, the surviving value heads.
template <typename LeftWord, typename RightWord>
class BRepCensusNativeProductWord final {
public:
    BRepCensusNativeProductWord(
        const LeftWord& left, const RightWord& right,
        BRepCensusLocationEvent event) noexcept
        : left_(left), right_(right), event_(event) {}

    bool Count(std::size_t& count) const noexcept {
        BRepCensusReducedBinaryCursor<RightWord, LeftWord, false> cursor(
            right_, left_);
        if (cursor.Failed()) return false;
        count = cursor.OutputCount();
        return true;
    }

    bool Read(std::size_t ordinal,
              BRepCensusReducedWordItem& output) const noexcept {
        BRepCensusReducedBinaryCursor<RightWord, LeftWord, false> cursor(
            right_, left_);
        if (cursor.Failed() || ordinal >= cursor.OutputCount()) return false;
        for (std::size_t index = 0; index <= ordinal; ++index)
            if (!cursor.Next(output)) return false;
        if (cursor.Failed()) return false;
        if (cursor.LeftCount() == 0) return left_.Read(ordinal, output);
        if (cursor.RightCount() == 0) return right_.Read(ordinal, output);
        using Cursor = BRepCensusReducedBinaryCursor<
            RightWord, LeftWord, false>;
        typename Cursor::OutputOrigin origin;
        std::size_t sourceOrdinal = 0;
        if (!cursor.Origin(ordinal, origin, sourceOrdinal)) return false;
        if (origin == Cursor::OutputOrigin::Right) {
            BRepCensusReducedWordItem forwarded;
            if (!left_.Read(sourceOrdinal, forwarded)
                || forwarded.datum != output.datum
                || forwarded.power != output.power) return false;
            output.node = forwarded.node;
        } else {
            output.node = BRepCensusEventNode(event_,
                origin == Cursor::OutputOrigin::Merge
                    ? BRepCensusLocationOperation::Merge
                    : BRepCensusLocationOperation::Product,
                sourceOrdinal);
        }
        return output.node.kind != BRepCensusLocationNodeKind::None;
    }

private:
    const LeftWord& left_;
    const RightWord& right_;
    BRepCensusLocationEvent event_;
};

template <typename ValueWord, typename DivisorWord>
class BRepCensusNativePredivisionWord final {
public:
    BRepCensusNativePredivisionWord(
        const ValueWord& value, const DivisorWord& divisor,
        BRepCensusLocationEvent event) noexcept
        : value_(value), divisor_(divisor), event_(event) {}

    bool Count(std::size_t& count) const noexcept {
        BRepCensusReducedBinaryCursor<ValueWord, DivisorWord, true> cursor(
            value_, divisor_);
        if (cursor.Failed()) return false;
        count = cursor.OutputCount();
        return true;
    }

    bool Read(std::size_t ordinal,
              BRepCensusReducedWordItem& output) const noexcept {
        BRepCensusReducedBinaryCursor<ValueWord, DivisorWord, true> cursor(
            value_, divisor_);
        if (cursor.Failed() || ordinal >= cursor.OutputCount()) return false;
        for (std::size_t index = 0; index <= ordinal; ++index)
            if (!cursor.Next(output)) return false;
        if (cursor.Failed()) return false;
        if (cursor.RightCount() == 0) return value_.Read(ordinal, output);
        using Cursor = BRepCensusReducedBinaryCursor<
            ValueWord, DivisorWord, true>;
        typename Cursor::OutputOrigin origin;
        std::size_t sourceOrdinal = 0;
        if (!cursor.Origin(ordinal, origin, sourceOrdinal)) return false;
        if (cursor.LeftCount() == 0
            || origin == Cursor::OutputOrigin::Right) {
            output.node = BRepCensusEventNode(event_,
                BRepCensusLocationOperation::Inverse, sourceOrdinal);
        } else {
            output.node = BRepCensusEventNode(event_,
                origin == Cursor::OutputOrigin::Merge
                    ? BRepCensusLocationOperation::Merge
                    : BRepCensusLocationOperation::Product,
                sourceOrdinal);
        }
        return output.node.kind != BRepCensusLocationNodeKind::None;
    }

private:
    const ValueWord& value_;
    const DivisorWord& divisor_;
    BRepCensusLocationEvent event_;
};

template <typename Word>
class BRepCensusInverseWord final {
public:
    explicit BRepCensusInverseWord(const Word& word) noexcept : word_(word) {}
    bool Count(std::size_t& count) const noexcept { return word_.Count(count); }
    bool Read(std::size_t ordinal,
              BRepCensusReducedWordItem& output) const noexcept {
        std::size_t count = 0;
        return word_.Count(count) && ordinal < count
            && word_.Read(count - ordinal - 1, output)
            && BRepCensusCheckedNegate(output.power, output.power);
    }
private:
    const Word& word_;
};

template <typename FirstWord, typename SecondWord>
bool BRepCensusSameReducedWord(const FirstWord& first,
                              const SecondWord& second,
                              bool& same) noexcept {
    same = false;
    std::size_t firstCount = 0, secondCount = 0;
    if (!first.Count(firstCount) || !second.Count(secondCount)) return false;
    if (firstCount != secondCount) return true;
    for (std::size_t index = 0; index < firstCount; ++index) {
        BRepCensusReducedWordItem left, right;
        if (!first.Read(index, left) || !second.Read(index, right)) return false;
        if (left.datum != right.datum || left.power != right.power) return true;
    }
    same = true;
    return true;
}

struct BRepCensusReducedWordEvaluation final {
    std::size_t nodeCount = 0;
    std::size_t byteCount = 0;
    bool failed = false;
};

template <typename LeftWord, typename RightWord>
BRepCensusReducedWordEvaluation BRepCensusEvaluateReducedPredivision(
    const LeftWord& left, const RightWord& right,
    std::size_t nodeBytes) noexcept {
    BRepCensusReducedPredivisionCursor<LeftWord, RightWord> cursor(left, right);
    if (cursor.Failed()) return {0, 0, true};
    std::size_t observedCount = 0;
    BRepCensusReducedWordItem item;
    while (cursor.Next(item)) {
        if (!BRepCensusAdd(observedCount, 1)) return {0, 0, true};
    }
    std::size_t bytes = 0;
    if (cursor.Failed() || observedCount != cursor.OutputCount()
        || !BRepCensusProduct(observedCount, nodeBytes, bytes))
        return {0, 0, true};
    return {observedCount, bytes, false};
}

BRepCensusReducedWordEvaluation BRepCensusPredividedNodeEvaluation(
    const TopLoc_Location& left, const TopLoc_Location& right) noexcept {
    const BRepCensusLocationWord leftWord(left), rightWord(right);
    return BRepCensusEvaluateReducedPredivision(leftWord, rightWord,
        sizeof(TopLoc_SListNodeOfItemLocation));
}

struct BRepCensusOccurrence final {
    TopoDS_Shape shape;
    std::size_t ordinal = 0;
    std::size_t parentOrdinal = std::numeric_limits<std::size_t>::max();
};

bool BRepCensusReplayOccurrenceWalk(
    const TopoDS_Shape& rawShape, TopAbs_Orientation effectiveOrientation,
    std::size_t parentOrdinal, std::size_t targetOrdinal,
    std::size_t& nextOrdinal, BRepCensusOccurrence& output,
    std::size_t depth) noexcept {
    if (depth >= retained_topology_budget::MaximumTopologyVisits) return false;
    const std::size_t ordinal = nextOrdinal;
    if (!BRepCensusAdd(nextOrdinal, 1)) return false;
    if (ordinal == targetOrdinal) {
        output.shape = rawShape;
        output.shape.Orientation(effectiveOrientation);
        output.ordinal = ordinal;
        output.parentOrdinal = parentOrdinal;
        return true;
    }
    for (TopoDS_Iterator child(rawShape, Standard_False, Standard_False);
         child.More(); child.Next()) {
        const TopoDS_Shape& childShape = child.Value();
        if (BRepCensusReplayOccurrenceWalk(childShape,
                TopAbs::Compose(effectiveOrientation, childShape.Orientation()),
                ordinal, targetOrdinal, nextOrdinal, output, depth + 1))
            return true;
    }
    return false;
}

bool BRepCensusReplayOccurrence(const TopoDS_Shape& root,
                                std::size_t ordinal,
                                BRepCensusOccurrence& output) noexcept {
    std::size_t next = 0;
    return BRepCensusReplayOccurrenceWalk(root, root.Orientation(),
        std::numeric_limits<std::size_t>::max(), ordinal, next, output, 0);
}

class BRepCensusOccurrenceWord final {
public:
    BRepCensusOccurrenceWord(const TopoDS_Shape& root,
                             std::size_t ordinal,
                             std::size_t depth = 0) noexcept
        : root_(&root), ordinal_(ordinal), depth_(depth) {}

    bool Count(std::size_t& count) const noexcept {
        BRepCensusOccurrence occurrence;
        if (!root_ || depth_ >= retained_topology_budget::MaximumTopologyVisits
            || !BRepCensusReplayOccurrence(
                *root_, ordinal_, occurrence)) return false;
        const BRepCensusLocationWord local(occurrence.shape.Location());
        if (occurrence.parentOrdinal
            == std::numeric_limits<std::size_t>::max()) return local.Count(count);
        const BRepCensusOccurrenceWord parent(
            *root_, occurrence.parentOrdinal, depth_ + 1);
        const BRepCensusReducedProductWord product(parent, local);
        return product.Count(count);
    }

    bool Read(std::size_t ordinal,
              BRepCensusReducedWordItem& output) const noexcept {
        BRepCensusOccurrence occurrence;
        if (!root_ || depth_ >= retained_topology_budget::MaximumTopologyVisits
            || !BRepCensusReplayOccurrence(
                *root_, ordinal_, occurrence)) return false;
        const BRepCensusLocationWord local(occurrence.shape.Location());
        if (occurrence.parentOrdinal
            == std::numeric_limits<std::size_t>::max())
            return local.Read(ordinal, output);
        const BRepCensusOccurrenceWord parent(
            *root_, occurrence.parentOrdinal, depth_ + 1);
        const BRepCensusReducedProductWord product(parent, local);
        return product.Read(ordinal, output);
    }

private:
    const TopoDS_Shape* root_ = nullptr;
    std::size_t ordinal_ = 0;
    std::size_t depth_ = 0;
};

bool BRepCensusReplayIsDescendant(const TopoDS_Shape& root,
                                  std::size_t candidate,
                                  std::size_t ancestor,
                                  bool& descendant) noexcept {
    descendant = false;
    BRepCensusOccurrence occurrence;
    if (!BRepCensusReplayOccurrence(root, candidate, occurrence)) return false;
    std::size_t depth = 0;
    while (occurrence.parentOrdinal
        != std::numeric_limits<std::size_t>::max()) {
        if (occurrence.parentOrdinal == ancestor) {
            descendant = true;
            return true;
        }
        if (++depth >= retained_topology_budget::MaximumTopologyVisits
            || !BRepCensusReplayOccurrence(
                root, occurrence.parentOrdinal, occurrence)) return false;
    }
    return true;
}

bool BRepCensusReplaySameKey(const TopoDS_Shape& root,
                            std::size_t firstOrdinal,
                            std::size_t secondOrdinal,
                            bool& same) noexcept {
    same = false;
    BRepCensusOccurrence first, second;
    if (!BRepCensusReplayOccurrence(root, firstOrdinal, first)
        || !BRepCensusReplayOccurrence(root, secondOrdinal, second))
        return false;
    if (first.shape.TShape().get() != second.shape.TShape().get()) return true;
    const BRepCensusOccurrenceWord left(root, firstOrdinal);
    const BRepCensusOccurrenceWord right(root, secondOrdinal);
    return BRepCensusSameReducedWord(left, right, same);
}

class BRepCensusOccurrenceMap final {
public:
    struct Entry final {
        TopoDS_Shape shape;
        std::size_t ordinal = 0;
        std::size_t parentOrdinal = std::numeric_limits<std::size_t>::max();
        bool representative = false;
    };

    static constexpr std::size_t EntrySize() noexcept { return sizeof(Entry); }
    bool Initialize(const TopoDS_Shape& root, std::size_t count) noexcept {
        root_ = &root;
        entries_.reset(new (std::nothrow) Entry[count]);
        if (count != 0 && !entries_) return false;
        extent_ = count;
        for (std::size_t ordinal = 0; ordinal < count; ++ordinal) {
            BRepCensusOccurrence occurrence;
            if (!BRepCensusReplayOccurrence(root, ordinal, occurrence))
                return false;
            Entry& entry = entries_[ordinal];
            entry.shape = occurrence.shape;
            entry.ordinal = ordinal;
            entry.parentOrdinal = occurrence.parentOrdinal;
            entry.representative = true;
            for (std::size_t prior = 0; prior < ordinal; ++prior) {
                if (!entries_[prior].representative
                    || entries_[prior].shape.TShape().get()
                        != entry.shape.TShape().get()) continue;
                bool same = false;
                if (!SameKeyOrdinals(prior, ordinal, same)) return false;
                if (same) {
                    entry.representative = false;
                    break;
                }
            }
            if (entry.representative
                && !BRepCensusAdd(representativeCount_, 1)) return false;
        }
        return true;
    }

    bool IsEmpty() const noexcept { return extent_ == 0; }
    Standard_Integer Extent() const noexcept {
        return static_cast<Standard_Integer>(extent_);
    }
    std::size_t RepresentativeCount() const noexcept {
        return representativeCount_;
    }
    const TopoDS_Shape& FindKey(Standard_Integer index) const noexcept {
        return entries_[std::size_t(index - 1)].shape;
    }
    std::size_t Ordinal(Standard_Integer index) const noexcept {
        return entries_[std::size_t(index - 1)].ordinal;
    }
    std::size_t ParentOrdinal(Standard_Integer index) const noexcept {
        return entries_[std::size_t(index - 1)].parentOrdinal;
    }
    bool IsRepresentative(Standard_Integer index) const noexcept {
        return entries_[std::size_t(index - 1)].representative;
    }
    bool SameKey(Standard_Integer first, Standard_Integer second,
                 bool& same) const noexcept {
        return SameKeyOrdinals(Ordinal(first), Ordinal(second), same);
    }
    bool IsDescendant(Standard_Integer candidate, Standard_Integer ancestor,
                      bool& descendant) const noexcept {
        descendant = false;
        std::size_t parent = entries_[std::size_t(candidate - 1)].parentOrdinal;
        std::size_t depth = 0;
        const std::size_t ancestorOrdinal = Ordinal(ancestor);
        while (parent != std::numeric_limits<std::size_t>::max()) {
            if (parent == ancestorOrdinal) {
                descendant = true;
                return true;
            }
            if (++depth >= retained_topology_budget::MaximumTopologyVisits
                || parent >= extent_) return false;
            parent = entries_[parent].parentOrdinal;
        }
        return true;
    }
    const TopoDS_Shape& Root() const noexcept { return *root_; }

private:
    bool SameKeyOrdinals(std::size_t first, std::size_t second,
                         bool& same) const noexcept {
        same = false;
        if (first >= extent_ || second >= extent_) return false;
        if (entries_[first].shape.TShape().get()
            != entries_[second].shape.TShape().get()) return true;
        const BRepCensusOccurrenceWord left(*root_, first);
        const BRepCensusOccurrenceWord right(*root_, second);
        return BRepCensusSameReducedWord(left, right, same);
    }
    const TopoDS_Shape* root_ = nullptr;
    std::unique_ptr<Entry[]> entries_;
    std::size_t extent_ = 0;
    std::size_t representativeCount_ = 0;
};

// Replays the cumulative TopoDS_Iterator location at one source occurrence.
// A nonidentity parent and child-local word are a distinct iterator product
// event; identity operands forward the concrete/event tail exactly.
class BRepCensusPredictedOccurrenceWord final {
public:
    BRepCensusPredictedOccurrenceWord(
        const TopoDS_Shape& root, std::size_t ordinal,
        std::size_t depth = 0) noexcept
        : root_(&root), ordinal_(ordinal), depth_(depth) {}

    bool Count(std::size_t& count) const noexcept {
        BRepCensusOccurrence occurrence;
        if (!Load(occurrence)) return false;
        const BRepCensusLocationWord local(occurrence.shape.Location());
        if (occurrence.parentOrdinal
            == std::numeric_limits<std::size_t>::max())
            return local.Count(count);
        const BRepCensusPredictedOccurrenceWord parent(
            *root_, occurrence.parentOrdinal, depth_ + 1);
        const BRepCensusNativeProductWord product(parent, local,
            {1, 1, ordinal_, occurrence.parentOrdinal, 0});
        return product.Count(count);
    }

    bool Read(std::size_t ordinal,
              BRepCensusReducedWordItem& output) const noexcept {
        BRepCensusOccurrence occurrence;
        if (!Load(occurrence)) return false;
        const BRepCensusLocationWord local(occurrence.shape.Location());
        if (occurrence.parentOrdinal
            == std::numeric_limits<std::size_t>::max())
            return local.Read(ordinal, output);
        const BRepCensusPredictedOccurrenceWord parent(
            *root_, occurrence.parentOrdinal, depth_ + 1);
        const BRepCensusNativeProductWord product(parent, local,
            {1, 1, ordinal_, occurrence.parentOrdinal, 0});
        return product.Read(ordinal, output);
    }

private:
    bool Load(BRepCensusOccurrence& occurrence) const noexcept {
        return root_
            && depth_ < retained_topology_budget::MaximumTopologyVisits
            && BRepCensusReplayOccurrence(*root_, ordinal_, occurrence);
    }

    const TopoDS_Shape* root_ = nullptr;
    std::size_t ordinal_ = 0;
    std::size_t depth_ = 0;
};

template <typename EdgeWord, typename FaceWord>
BRepCensusPCurveLookup BRepCensusLookupStoredPCurve(
    const Handle(BRep_TEdge)& edge, const Handle(BRep_TFace)& face,
    const EdgeWord& edgeEffective, const FaceWord& faceEffective,
    TopAbs_Orientation edgeOrientation) noexcept {
    BRepCensusPCurveLookup result;
    if (edge.IsNull() || face.IsNull() || face->Surface().IsNull()) {
        result.kind = BRepCensusPCurveLookupKind::Failure;
        return result;
    }
    const BRepCensusLocationWord faceLocal(face->Location());
    const BRepCensusReducedProductWord surfaceEffective(
        faceEffective, faceLocal);
    const BRepCensusInverseWord inverseEdge(edgeEffective);
    const BRepCensusReducedProductWord relative(
        inverseEdge, surfaceEffective);
    for (const auto& candidate : edge->Curves()) {
        if (candidate.IsNull()) {
            result.kind = BRepCensusPCurveLookupKind::Failure;
            return result;
        }
        const auto stored = Handle(BRep_CurveOnSurface)::DownCast(candidate);
        if (stored.IsNull() || stored->Surface().get() != face->Surface().get())
            continue;
        const BRepCensusLocationWord storedWord(stored->Location());
        bool same = false;
        if (!BRepCensusSameReducedWord(storedWord, relative, same)) {
            result.kind = BRepCensusPCurveLookupKind::Failure;
            return result;
        }
        if (!same) continue;
        result.kind = BRepCensusPCurveLookupKind::Stored;
        result.representation = candidate.get();
        result.stored = !stored->IsCurveOnClosedSurface()
                || edgeOrientation != TopAbs_REVERSED
            ? stored->PCurve() : stored->PCurve2();
        return result;
    }
    Handle(Geom_Plane) plane = Handle(Geom_Plane)::DownCast(face->Surface());
    if (plane.IsNull()) {
        const auto trimmed = Handle(Geom_RectangularTrimmedSurface)::DownCast(
            face->Surface());
        if (!trimmed.IsNull())
            plane = Handle(Geom_Plane)::DownCast(trimmed->BasisSurface());
    }
    if (plane.IsNull()) return result;
    for (const auto& candidate : edge->Curves()) {
        const auto curve = Handle(BRep_Curve3D)::DownCast(candidate);
        if (curve.IsNull()) continue;
        if (curve->Curve3D().IsNull()) return result;
        result.kind = BRepCensusPCurveLookupKind::NeedsPlanarProjection;
        result.reason = kBRepCensusUnstoredPlanarReason;
        return result;
    }
    return result;
}

struct BRepCensusPolygonLookup final {
    Handle(Poly_PolygonOnTriangulation) stored;
    const BRep_CurveRepresentation* representation = nullptr;
    bool failed = false;
};

template <typename EdgeWord, typename FaceWord>
BRepCensusPolygonLookup BRepCensusLookupStoredPolygon(
    const Handle(BRep_TEdge)& edge,
    const Handle(Poly_Triangulation)& mesh,
    const EdgeWord& edgeEffective, const FaceWord& faceEffective,
    TopAbs_Orientation edgeOrientation) noexcept {
    BRepCensusPolygonLookup result;
    if (edge.IsNull() || mesh.IsNull()) return result;
    const BRepCensusInverseWord inverseEdge(edgeEffective);
    const BRepCensusReducedProductWord relative(inverseEdge, faceEffective);
    for (const auto& candidate : edge->Curves()) {
        if (candidate.IsNull()) {
            result.failed = true;
            return result;
        }
        const auto stored =
            Handle(BRep_PolygonOnTriangulation)::DownCast(candidate);
        if (stored.IsNull()
            || stored->Triangulation().get() != mesh.get()) continue;
        const BRepCensusLocationWord storedWord(stored->Location());
        bool same = false;
        if (!BRepCensusSameReducedWord(storedWord, relative, same)) {
            result.failed = true;
            return result;
        }
        if (!same) continue;
        result.representation = candidate.get();
        if (stored->IsPolygonOnClosedTriangulation()
            && edgeOrientation == TopAbs_REVERSED) {
            const auto closed =
                Handle(BRep_PolygonOnClosedTriangulation)::DownCast(stored);
            if (closed.IsNull()) result.failed = true;
            else result.stored = closed->PolygonOnTriangulation2();
        } else {
            result.stored = stored->PolygonOnTriangulation();
        }
        return result;
    }
    return result;
}

bool BRepCensusEffectiveSeam(
    const BRepCensusOccurrenceMap& topology, Standard_Integer edgeIndex,
    Standard_Integer faceIndex, const Handle(BRep_TFace)& face,
    const Handle(Poly_Triangulation)& activeMesh, bool& seam) noexcept {
    seam = false;
    if (face.IsNull()) return false;
    const auto edge = Handle(BRep_TEdge)::DownCast(
        topology.FindKey(edgeIndex).TShape());
    if (edge.IsNull()) return false;
    const BRepCensusOccurrenceWord edgeWord(
        topology.Root(), topology.Ordinal(edgeIndex));
    const BRepCensusOccurrenceWord faceWord(
        topology.Root(), topology.Ordinal(faceIndex));
    const BRepCensusLocationWord faceLocal(face->Location());
    const BRepCensusReducedProductWord surfaceWord(faceWord, faceLocal);
    const BRepCensusInverseWord inverseEdge(edgeWord);
    const BRepCensusReducedProductWord surfaceRelative(
        inverseEdge, surfaceWord);
    const BRepCensusReducedProductWord meshRelative(inverseEdge, faceWord);
    bool hasClosedRepresentation = false;
    for (const auto& candidate : edge->Curves()) {
        if (candidate.IsNull()) return false;
        if (const auto closed =
                Handle(BRep_CurveOnClosedSurface)::DownCast(candidate);
            !closed.IsNull()
            && closed->Surface().get() == face->Surface().get()) {
            const BRepCensusLocationWord stored(closed->Location());
            bool same = false;
            if (!BRepCensusSameReducedWord(
                    stored, surfaceRelative, same)) return false;
            if (same) { hasClosedRepresentation = true; break; }
        }
        if (const auto closed =
                Handle(BRep_PolygonOnClosedTriangulation)::DownCast(candidate);
            !closed.IsNull() && !activeMesh.IsNull()
            && closed->Triangulation().get() == activeMesh.get()) {
            const BRepCensusLocationWord stored(closed->Location());
            bool same = false;
            if (!BRepCensusSameReducedWord(
                    stored, meshRelative, same)) return false;
            if (same) { hasClosedRepresentation = true; break; }
        }
    }
    if (!hasClosedRepresentation) return true;
    std::size_t occurrences = 0;
    for (Standard_Integer candidate = faceIndex + 1;
         candidate <= topology.Extent(); ++candidate) {
        bool descendant = false;
        if (!topology.IsDescendant(candidate, faceIndex, descendant)) return false;
        if (!descendant) break;
        if (topology.FindKey(candidate).ShapeType() != TopAbs_EDGE) continue;
        bool same = false;
        if (!topology.SameKey(candidate, edgeIndex, same)) return false;
        if (same && !BRepCensusAdd(occurrences, 1)) return false;
    }
    seam = occurrences == 2;
    return true;
}

bool BRepCensusPCurveIdentityIsCopied(
    const BRepCensusOccurrenceMap& topology, Standard_Integer sourceEdgeIndex,
    const void* identity, bool& copied) noexcept {
    copied = identity == nullptr;
    if (copied) return true;
    const auto sourceEdge = Handle(BRep_TEdge)::DownCast(
        topology.FindKey(sourceEdgeIndex).TShape());
    if (sourceEdge.IsNull()) return false;
    for (Standard_Integer faceIndex = 1; faceIndex <= topology.Extent();
         ++faceIndex) {
        if (!topology.IsRepresentative(faceIndex)
            || topology.FindKey(faceIndex).ShapeType() != TopAbs_FACE) continue;
        const auto face = Handle(BRep_TFace)::DownCast(
            topology.FindKey(faceIndex).TShape());
        if (face.IsNull()) return false;
        const BRepCensusOccurrenceWord faceWord(
            topology.Root(), topology.Ordinal(faceIndex));
        const Handle(Poly_Triangulation) active = face->ActiveTriangulation();
        bool processed = false;
        for (Standard_Integer edgeIndex = faceIndex + 1;
             edgeIndex <= topology.Extent(); ++edgeIndex) {
            bool descendant = false;
            if (!topology.IsDescendant(
                    edgeIndex, faceIndex, descendant)) return false;
            if (!descendant) break;
            if (processed
                || topology.FindKey(edgeIndex).ShapeType() != TopAbs_EDGE)
                continue;
            bool same = false;
            if (!topology.SameKey(edgeIndex, sourceEdgeIndex, same)) return false;
            if (!same) continue;
            processed = true;
            bool seam = false;
            if (!BRepCensusEffectiveSeam(topology, edgeIndex, faceIndex,
                    face, active, seam)) return false;
            for (int member = 0; member < (seam ? 2 : 1); ++member) {
                TopAbs_Orientation orientation =
                    topology.FindKey(edgeIndex).Orientation();
                if (member == 1) orientation = TopAbs::Reverse(orientation);
                if (topology.FindKey(faceIndex).Orientation() == TopAbs_REVERSED)
                    orientation = TopAbs::Reverse(orientation);
                const BRepCensusOccurrenceWord edgeWord(
                    topology.Root(), topology.Ordinal(edgeIndex));
                const auto lookup = BRepCensusLookupStoredPCurve(
                    sourceEdge, face, edgeWord, faceWord, orientation);
                if (lookup.kind == BRepCensusPCurveLookupKind::Failure)
                    return false;
                if (lookup.kind == BRepCensusPCurveLookupKind::Stored
                    && lookup.stored.get() == identity) {
                    copied = true;
                    return true;
                }
            }
        }
    }
    return true;
}

bool BRepCensusPolygonIdentityIsCopied(
    const BRepCensusOccurrenceMap& topology, Standard_Integer sourceEdgeIndex,
    const void* identity, bool& copied) noexcept {
    copied = identity == nullptr;
    if (copied) return true;
    const auto sourceEdge = Handle(BRep_TEdge)::DownCast(
        topology.FindKey(sourceEdgeIndex).TShape());
    if (sourceEdge.IsNull()) return false;
    for (Standard_Integer faceIndex = 1; faceIndex <= topology.Extent();
         ++faceIndex) {
        if (!topology.IsRepresentative(faceIndex)
            || topology.FindKey(faceIndex).ShapeType() != TopAbs_FACE) continue;
        const auto face = Handle(BRep_TFace)::DownCast(
            topology.FindKey(faceIndex).TShape());
        if (face.IsNull()) return false;
        const Handle(Poly_Triangulation) active = face->ActiveTriangulation();
        if (active.IsNull()) continue;
        const BRepCensusOccurrenceWord faceWord(
            topology.Root(), topology.Ordinal(faceIndex));
        bool processed = false;
        for (Standard_Integer edgeIndex = faceIndex + 1;
             edgeIndex <= topology.Extent(); ++edgeIndex) {
            bool descendant = false;
            if (!topology.IsDescendant(
                    edgeIndex, faceIndex, descendant)) return false;
            if (!descendant) break;
            if (processed
                || topology.FindKey(edgeIndex).ShapeType() != TopAbs_EDGE)
                continue;
            bool same = false;
            if (!topology.SameKey(edgeIndex, sourceEdgeIndex, same)) return false;
            if (!same) continue;
            processed = true;
            bool seam = false;
            if (!BRepCensusEffectiveSeam(topology, edgeIndex, faceIndex,
                    face, active, seam)) return false;
            for (int member = 0; member < (seam ? 2 : 1); ++member) {
                TopAbs_Orientation orientation =
                    topology.FindKey(edgeIndex).Orientation();
                if (member == 1) orientation = TopAbs::Reverse(orientation);
                const BRepCensusOccurrenceWord edgeWord(
                    topology.Root(), topology.Ordinal(edgeIndex));
                const auto lookup = BRepCensusLookupStoredPolygon(
                    sourceEdge, active, edgeWord, faceWord, orientation);
                if (lookup.failed) return false;
                if (lookup.stored.get() == identity) {
                    copied = true;
                    return true;
                }
            }
        }
    }
    return true;
}

template <typename Word, typename Visitor>
bool BRepCensusVisitLocationWord(
    const Word& word, Visitor&& visitor) noexcept {
    std::size_t count = 0;
    if (!word.Count(count)) return false;
    for (std::size_t ordinal = 0; ordinal < count; ++ordinal) {
        BRepCensusReducedWordItem item;
        if (!word.Read(ordinal, item) || !item.datum || item.power == 0
            || item.node.kind == BRepCensusLocationNodeKind::None
            || !visitor(item)) return false;
    }
    return true;
}

// Enumerate only location fields reachable from the final copied graph. Every
// expression reuses the checked reducer above and carries either a concrete
// source-node address or a stable native-event key. Replaying this function is
// the allocation-free identity set: replaced wrappers and transient inverse
// products are never roots, while Add (including vertex children), final seam
// replacement generations and the polygon-forwarding override are roots.
template <typename Visitor>
bool BRepCensusVisitPredictedFinalLocationItems(
    const BRepCensusOccurrenceMap& topology, Visitor&& visitor) noexcept {
    if (topology.IsEmpty()) return false;
    const auto emit = [&](const auto& word) {
        return BRepCensusVisitLocationWord(word, visitor);
    };

    const BRepCensusPredictedOccurrenceWord root(
        topology.Root(), topology.Ordinal(1));
    if (!emit(root)) return false;

    // TopoDS_Builder::Add stores one independently constructed relative word
    // for every raw child use. Duplicate seam uses deliberately remain
    // distinct events even when they share an effective key.
    for (Standard_Integer index = 2; index <= topology.Extent(); ++index) {
        const std::size_t parentOrdinal = topology.ParentOrdinal(index);
        if (parentOrdinal == std::numeric_limits<std::size_t>::max())
            return false;
        const BRepCensusPredictedOccurrenceWord child(
            topology.Root(), topology.Ordinal(index));
        const BRepCensusPredictedOccurrenceWord parent(
            topology.Root(), parentOrdinal);
        const BRepCensusNativePredivisionWord relative(child, parent,
            {5, 14, parentOrdinal, topology.Ordinal(index), 0});
        if (!emit(relative)) return false;
    }

    for (Standard_Integer index = 1; index <= topology.Extent(); ++index) {
        if (!topology.IsRepresentative(index)) continue;
        const TopoDS_Shape& shape = topology.FindKey(index);
        const std::size_t owner = topology.Ordinal(index);
        const BRepCensusPredictedOccurrenceWord effective(
            topology.Root(), owner);
        if (shape.ShapeType() == TopAbs_FACE) {
            const auto face = Handle(BRep_TFace)::DownCast(shape.TShape());
            if (face.IsNull()) return false;
            if (!face->Surface().IsNull()) {
                const BRepCensusLocationWord local(face->Location());
                const BRepCensusNativeProductWord descriptor(effective, local,
                    {2, 1, owner, 0, 0});
                const BRepCensusNativePredivisionWord finalLocal(
                    descriptor, effective, {3, 1, owner, 0, 0});
                if (!emit(finalLocal)) return false;
            }
        } else if (shape.ShapeType() == TopAbs_EDGE) {
            const auto edge = Handle(BRep_TEdge)::DownCast(shape.TShape());
            if (edge.IsNull()) return false;
            const TopLoc_Location* curveLocal = nullptr;
            const Handle(Geom_Curve) curve =
                BRepCensusFirstCurve3D(edge, &curveLocal);
            if (!curve.IsNull()) {
                if (!curveLocal) return false;
                const BRepCensusLocationWord local(*curveLocal);
                const BRepCensusNativeProductWord descriptor(effective, local,
                    {2, 2, owner, 0, 0});
                const BRepCensusNativePredivisionWord modifierLocal(
                    descriptor, effective, {3, 3, owner, 0, 0});
                // Builder:626 predivides by its fresh identity edge and
                // forwards the Modifier result, so row 8 has no new node.
                if (!emit(modifierLocal)) return false;
            }

            const TopLoc_Location* polygonLocal = nullptr;
            const Handle(Poly_Polygon3D) polygon =
                BRepCensusFirstPolygon3D(edge, &polygonLocal);
            if (!polygon.IsNull()) {
                if (!polygonLocal) return false;
                // Repair override: the final wrapper receives this exact
                // concrete list handle after native row 11 has completed.
                const BRepCensusLocationWord forwarded(*polygonLocal);
                if (!emit(forwarded)) return false;
            }
        }
    }

    // Final pcurve and polygon-on-triangulation wrappers are selected by the
    // same effective incidence rules as source admission. A closed seam owns
    // two members but only the last surviving wrapper location field.
    for (Standard_Integer faceIndex = 1;
         faceIndex <= topology.Extent(); ++faceIndex) {
        if (!topology.IsRepresentative(faceIndex)
            || topology.FindKey(faceIndex).ShapeType() != TopAbs_FACE)
            continue;
        const auto face = Handle(BRep_TFace)::DownCast(
            topology.FindKey(faceIndex).TShape());
        if (face.IsNull()) return false;
        const std::size_t faceOwner = topology.Ordinal(faceIndex);
        const BRepCensusOccurrenceWord sourceFace(
            topology.Root(), faceOwner);
        const BRepCensusPredictedOccurrenceWord copiedFace(
            topology.Root(), faceOwner);
        const Handle(Poly_Triangulation) active = face->ActiveTriangulation();
        for (Standard_Integer edgeIndex = faceIndex + 1;
             edgeIndex <= topology.Extent(); ++edgeIndex) {
            bool descendant = false;
            if (!topology.IsDescendant(
                    edgeIndex, faceIndex, descendant)) return false;
            if (!descendant) break;
            if (topology.FindKey(edgeIndex).ShapeType() != TopAbs_EDGE)
                continue;
            bool alreadyVisited = false;
            for (Standard_Integer prior = faceIndex + 1;
                 prior < edgeIndex; ++prior) {
                bool priorDescendant = false;
                if (!topology.IsDescendant(
                        prior, faceIndex, priorDescendant)) return false;
                if (!priorDescendant) break;
                if (topology.FindKey(prior).ShapeType() != TopAbs_EDGE)
                    continue;
                bool same = false;
                if (!topology.SameKey(edgeIndex, prior, same)) return false;
                if (same) { alreadyVisited = true; break; }
            }
            if (alreadyVisited) continue;
            const auto edge = Handle(BRep_TEdge)::DownCast(
                topology.FindKey(edgeIndex).TShape());
            if (edge.IsNull()) return false;
            const std::size_t edgeOwner = topology.Ordinal(edgeIndex);
            const BRepCensusOccurrenceWord sourceEdge(
                topology.Root(), edgeOwner);
            const BRepCensusPredictedOccurrenceWord copiedEdge(
                topology.Root(), edgeOwner);
            bool seam = false;
            if (!BRepCensusEffectiveSeam(topology, edgeIndex, faceIndex,
                    face, active, seam)) return false;
            bool hasPCurve = false, hasPolygon = false;
            for (int member = 0; member < (seam ? 2 : 1); ++member) {
                TopAbs_Orientation orientation =
                    topology.FindKey(edgeIndex).Orientation();
                if (member == 1) orientation = TopAbs::Reverse(orientation);
                if (topology.FindKey(faceIndex).Orientation()
                    == TopAbs_REVERSED)
                    orientation = TopAbs::Reverse(orientation);
                const auto pcurve = BRepCensusLookupStoredPCurve(
                    edge, face, sourceEdge, sourceFace, orientation);
                if (pcurve.kind == BRepCensusPCurveLookupKind::Failure
                    || pcurve.kind
                        == BRepCensusPCurveLookupKind::NeedsPlanarProjection)
                    return false;
                hasPCurve = hasPCurve || !pcurve.stored.IsNull();
                if (!active.IsNull()) {
                    const auto polygon = BRepCensusLookupStoredPolygon(
                        edge, active, sourceEdge, sourceFace,
                        member == 1
                            ? TopAbs::Reverse(
                                topology.FindKey(edgeIndex).Orientation())
                            : topology.FindKey(edgeIndex).Orientation());
                    if (polygon.failed) return false;
                    hasPolygon = hasPolygon || !polygon.stored.IsNull();
                }
            }
            if (hasPCurve) {
                if (face->Surface().IsNull()) return false;
                const BRepCensusLocationWord sourceFaceLocal(face->Location());
                const BRepCensusNativeProductWord sourceDescriptor(
                    copiedFace, sourceFaceLocal,
                    {2, 1, faceOwner, 0, 0});
                const BRepCensusNativePredivisionWord copiedFaceLocal(
                    sourceDescriptor, copiedFace,
                    {3, 1, faceOwner, 0, 0});
                const BRepCensusNativeProductWord copiedSurface(
                    copiedFace, copiedFaceLocal,
                    {2, 3, faceOwner, edgeOwner, seam ? 1U : 0U});
                const BRepCensusNativePredivisionWord finalPCurve(
                    copiedSurface, copiedEdge,
                    {4, std::uint16_t(seam ? 10 : 9), edgeOwner,
                        faceOwner, seam ? 1U : 0U});
                if (!emit(finalPCurve)) return false;
            }
            if (hasPolygon) {
                const BRepCensusNativePredivisionWord finalPolygon(
                    copiedFace, copiedEdge,
                    {4, std::uint16_t(seam ? 13 : 12), edgeOwner,
                        faceOwner, seam ? 1U : 0U});
                if (!emit(finalPolygon)) return false;
            }
        }
    }
    return true;
}

bool BRepCensusPredictedFinalLocationCounts(
    const BRepCensusOccurrenceMap& topology,
    std::size_t& nodeCount, std::size_t& datumCount) noexcept {
    nodeCount = 0;
    datumCount = 0;
    std::size_t serial = 0;
    return BRepCensusVisitPredictedFinalLocationItems(topology,
        [&](const BRepCensusReducedWordItem& item) {
            bool nodeSeen = false, datumSeen = false;
            std::size_t priorSerial = 0;
            const bool rescanned =
                BRepCensusVisitPredictedFinalLocationItems(topology,
                    [&](const BRepCensusReducedWordItem& prior) {
                        if (priorSerial < serial) {
                            nodeSeen = nodeSeen || prior.node == item.node;
                            datumSeen = datumSeen || prior.datum == item.datum;
                        }
                        ++priorSerial;
                        return true;
                    });
            if (!rescanned || priorSerial <= serial
                || (!nodeSeen && !BRepCensusAdd(nodeCount, 1))
                || (!datumSeen && !BRepCensusAdd(datumCount, 1)))
                return false;
            ++serial;
            return true;
        });
}

bool BRepCensusFindPlanarMiss(const TopoDS_Shape& root,
                              std::size_t occurrenceCount,
                              BRepCensusPCurveLookup& refusal) noexcept {
    refusal = {};
    refusal.kind = BRepCensusPCurveLookupKind::Failure;
    for (std::size_t faceOrdinal = 0; faceOrdinal < occurrenceCount;
         ++faceOrdinal) {
        BRepCensusOccurrence faceOccurrence;
        if (!BRepCensusReplayOccurrence(
                root, faceOrdinal, faceOccurrence)) return false;
        if (faceOccurrence.shape.ShapeType() != TopAbs_FACE) continue;
        bool firstFace = true;
        for (std::size_t prior = 0; prior < faceOrdinal; ++prior) {
            bool same = false;
            if (!BRepCensusReplaySameKey(root, prior, faceOrdinal, same))
                return false;
            if (same) { firstFace = false; break; }
        }
        if (!firstFace) continue;
        const auto face = Handle(BRep_TFace)::DownCast(
            faceOccurrence.shape.TShape());
        if (face.IsNull()) return false;
        const BRepCensusOccurrenceWord faceWord(root, faceOrdinal);
        for (std::size_t edgeOrdinal = faceOrdinal + 1;
             edgeOrdinal < occurrenceCount; ++edgeOrdinal) {
            BRepCensusOccurrence edgeOccurrence;
            if (!BRepCensusReplayOccurrence(
                    root, edgeOrdinal, edgeOccurrence)) return false;
            bool descendant = false;
            if (!BRepCensusReplayIsDescendant(
                    root, edgeOrdinal, faceOrdinal, descendant)) return false;
            if (!descendant) break;
            if (edgeOccurrence.shape.ShapeType() != TopAbs_EDGE) continue;
            const auto edge = Handle(BRep_TEdge)::DownCast(
                edgeOccurrence.shape.TShape());
            const BRepCensusOccurrenceWord edgeWord(root, edgeOrdinal);
            const auto lookup = BRepCensusLookupStoredPCurve(
                edge, face, edgeWord, faceWord,
                edgeOccurrence.shape.Orientation());
            if (lookup.kind == BRepCensusPCurveLookupKind::Failure) return false;
            if (lookup.kind
                    == BRepCensusPCurveLookupKind::NeedsPlanarProjection) {
                refusal = lookup;
                return true;
            }
        }
    }
    refusal = {};
    return false;
}

class BRepCensusIdentitySet final {
    using FailureSite = decal_layer::bake::accounting::FailureSite;
    using Retention = decal_layer::bake::accounting::Retention;
    using StorageDimension = decal_layer::bake::accounting::StorageDimension;

    struct Node final {
        const void* identity = nullptr;
        decal_layer::bake::accounting::Ticket ticket;
        Node* next = nullptr;
    };

public:
    static constexpr std::size_t EntrySize() noexcept { return sizeof(Node); }
    explicit BRepCensusIdentitySet(
        const decal_layer::bake::accounting::View& accounting) noexcept
        : accounting_(accounting) {}
    BRepCensusIdentitySet(const BRepCensusIdentitySet&) = delete;
    BRepCensusIdentitySet& operator=(const BRepCensusIdentitySet&) = delete;
    ~BRepCensusIdentitySet() {
        while (head_) {
            Node* next = head_->next;
            delete head_;
            head_ = next;
        }
    }

    bool insert(const void* identity, BRepRepresentationCensus& census,
                bool& inserted) noexcept {
        inserted = false;
        if (!identity) return true;
        for (Node* node = head_; node; node = node->next) {
            if (node->identity == identity) return true;
        }
        std::size_t admitted = census.observableMapScratch;
        if (!BRepCensusAdd(admitted, sizeof(Node))) return false;
        decal_layer::bake::accounting::Ticket ticket;
        if (!ticket.acquire(accounting_, StorageDimension::PrivateStorage,
                sizeof(Node), Retention::Scratch,
                FailureSite::BRepCensusMapScratch)) return false;
        Node* node = new (std::nothrow) Node{
            identity, std::move(ticket), head_};
        if (!node) {
            accounting_.AllocationFailed(FailureSite::BRepCensusMapScratch);
            return false;
        }
        head_ = node;
        census.observableMapScratch = admitted;
        inserted = true;
        return true;
    }

private:
    decal_layer::bake::accounting::View accounting_;
    Node* head_ = nullptr;
};

template <typename T>
bool BRepCensusArray1(BRepRepresentationCensus& census,
                      const void* identity, std::size_t count,
                      BRepCensusIdentitySet& seen) noexcept {
    bool inserted = false;
    if (!seen.insert(identity, census, inserted)) return false;
    if (!inserted) return true;
    std::size_t elements = 0;
    return BRepCensusProduct(count, sizeof(T), elements)
        && BRepCensusTerm(census, census.harrayStorage,
            sizeof(TColStd_HArray1OfReal) + elements);
}

template <typename HArray, typename T>
bool BRepCensusHArray(BRepRepresentationCensus& census,
                      const void* identity, std::size_t count,
                      BRepCensusIdentitySet& seen) noexcept {
    bool inserted = false;
    if (!seen.insert(identity, census, inserted)) return false;
    if (!inserted) return true;
    std::size_t elements = 0;
    return BRepCensusProduct(count, sizeof(T), elements)
        && BRepCensusTerm(census, census.harrayStorage,
            sizeof(HArray) + elements);
}

bool MeasureBRepRepresentation(
    const TopoDS_Shape& shape,
    retained_edge_treatment::ReplayBudget& budget,
    const decal_layer::bake::accounting::View& accounting,
    BRepRepresentationCensus& census,
    decal_layer::bake::accounting::Ticket& scratchTicket,
    BRepRepresentationCensus* copyPrediction = nullptr,
    BRepCensusPCurveLookup* rejectedLookup = nullptr) noexcept {
    using FailureSite = decal_layer::bake::accounting::FailureSite;
    using Retention = decal_layer::bake::accounting::Retention;
    using StorageDimension = decal_layer::bake::accounting::StorageDimension;
    census = {};
    if (rejectedLookup) *rejectedLookup = {};
    if (shape.IsNull() || !accounting.valid()) return false;
    try {
        // Count occurrences without materialising the census map, then admit
        // the stable-ordinal entry/index storage before allocating it.
        std::size_t occurrences = 0;
        if (!BRepCensusCountOccurrences(shape, occurrences)
            || !budget.visit(occurrences,
                retained_topology_budget::Site::C11GeometryCensus))
            return false;
        // D778 uses the same effective words as the admitted map, but replays
        // preorder ordinals so typed refusal still precedes every census ticket.
        if (copyPrediction) {
            BRepCensusPCurveLookup refusal;
            if (BRepCensusFindPlanarMiss(shape, occurrences, refusal)) {
                if (rejectedLookup) *rejectedLookup = refusal;
                return false;
            }
            if (refusal.kind == BRepCensusPCurveLookupKind::Failure)
                return false;
        }
        std::size_t mapEntries = 0, mapIndex = 0, mapCapacity = 0;
        if (!BRepCensusProduct(occurrences,
                BRepCensusOccurrenceMap::EntrySize(), mapEntries)
            || !BRepCensusMapCapacity(occurrences, mapCapacity)
            || !BRepCensusProduct(mapCapacity + 1,
                sizeof(NCollection_ListNode*), mapIndex)
            || !BRepCensusAdd(census.observableMapScratch,
                sizeof(BRepCensusOccurrenceMap))
            || !BRepCensusAdd(census.observableMapScratch, mapEntries)
            || !BRepCensusAdd(census.observableMapScratch, mapIndex)
            || !scratchTicket.acquire(accounting,
                StorageDimension::PrivateStorage,
                census.observableMapScratch, Retention::Scratch,
                FailureSite::BRepCensusMapScratch))
            return false;

        BRepCensusOccurrenceMap topology;
        if (!topology.Initialize(shape, occurrences)) return false;
        census.topologyCount = topology.RepresentativeCount();
        if (topology.IsEmpty() || census.topologyCount > occurrences)
            return false;
        BRepCensusIdentitySet sourceSeen(accounting);
        BRepRepresentationCensus* sourceCensusTarget = &census;
        BRepRepresentationCensus* graphCensus = sourceCensusTarget;
        BRepCensusIdentitySet* graphSeen = &sourceSeen;
#define census (*graphCensus)
#define seen (*graphSeen)
        const auto first = [&](const void* identity) {
            bool inserted = false;
            return seen.insert(identity, census, inserted) && inserted;
        };

        bool includeTriangulationParameters = true;

        const auto location = [&](const TopLoc_Location& value) {
            for (TopLoc_Location current = value; !current.IsIdentity();
                 current = current.NextLocation()) {
                const void* node = &current.FirstDatum();
                if (first(node)) {
                    if (!BRepCensusTerm(census, census.locations,
                            sizeof(TopLoc_SListNodeOfItemLocation))
                        || !BRepCensusAdd(census.locationNodes,
                            sizeof(TopLoc_SListNodeOfItemLocation)))
                        return false;
                }
                const Handle(TopLoc_Datum3D)& datum = current.FirstDatum();
                if (!datum.IsNull() && first(datum.get())) {
                    if (!BRepCensusTerm(census, census.locations,
                            sizeof(TopLoc_Datum3D))
                        || !BRepCensusAdd(census.locationDatums,
                            sizeof(TopLoc_Datum3D))) return false;
                }
            }
            return true;
        };

        const auto addCurveArrays = [&](auto handle, auto twoDimensional) {
            const auto& poles = handle->Poles();
            const auto* weights = handle->Weights();
            using Pole = std::conditional_t<decltype(twoDimensional)::value,
                gp_Pnt2d, gp_Pnt>;
            using PoleHArray = std::conditional_t<decltype(twoDimensional)::value,
                TColgp_HArray1OfPnt2d, TColgp_HArray1OfPnt>;
            return BRepCensusHArray<PoleHArray, Pole>(census, &poles,
                    std::size_t(poles.Length()), seen)
                && (!weights || BRepCensusHArray<TColStd_HArray1OfReal,
                    Standard_Real>(census, weights,
                        std::size_t(weights->Length()), seen));
        };

        const auto curve3d = [&](auto&& recurse,
                                 const Handle(Geom_Curve)& value) -> bool {
            if (value.IsNull() || !first(value.get())) return true;
#define CENSUS_CURVE3D(Type) \
            if (!Handle(Type)::DownCast(value).IsNull()) \
                return BRepCensusTerm(census, census.geometry, sizeof(Type))
            CENSUS_CURVE3D(Geom_Line);
            CENSUS_CURVE3D(Geom_Circle);
            CENSUS_CURVE3D(Geom_Ellipse);
            CENSUS_CURVE3D(Geom_Hyperbola);
            CENSUS_CURVE3D(Geom_Parabola);
#undef CENSUS_CURVE3D
            if (const auto typed = Handle(Geom_BezierCurve)::DownCast(value);
                !typed.IsNull())
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom_BezierCurve))
                    && addCurveArrays(typed, std::false_type{});
            if (const auto typed = Handle(Geom_BSplineCurve)::DownCast(value);
                !typed.IsNull()) {
                const auto& knots = typed->Knots();
                const auto& mults = typed->Multiplicities();
                const auto& flat = typed->KnotSequence();
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom_BSplineCurve))
                    && addCurveArrays(typed, std::false_type{})
                    && BRepCensusHArray<TColStd_HArray1OfReal, Standard_Real>(
                        census, &knots, std::size_t(knots.Length()), seen)
                    && BRepCensusHArray<TColStd_HArray1OfInteger,
                        Standard_Integer>(census, &mults,
                            std::size_t(mults.Length()), seen)
                    && BRepCensusHArray<TColStd_HArray1OfReal, Standard_Real>(
                        census, &flat, std::size_t(flat.Length()), seen);
            }
            if (const auto typed = Handle(Geom_TrimmedCurve)::DownCast(value);
                !typed.IsNull())
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom_TrimmedCurve))
                    && recurse(recurse, typed->BasisCurve());
            if (const auto typed = Handle(Geom_OffsetCurve)::DownCast(value);
                !typed.IsNull())
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom_OffsetCurve))
                    && recurse(recurse, typed->BasisCurve());
            return false;
        };

        const auto curve2d = [&](auto&& recurse,
                                 const Handle(Geom2d_Curve)& value) -> bool {
            if (value.IsNull() || !first(value.get())) return true;
#define CENSUS_CURVE2D(Type) \
            if (!Handle(Type)::DownCast(value).IsNull()) \
                return BRepCensusTerm(census, census.geometry, sizeof(Type))
            CENSUS_CURVE2D(Geom2d_Line);
            CENSUS_CURVE2D(Geom2d_Circle);
            CENSUS_CURVE2D(Geom2d_Ellipse);
            CENSUS_CURVE2D(Geom2d_Hyperbola);
            CENSUS_CURVE2D(Geom2d_Parabola);
#undef CENSUS_CURVE2D
            if (const auto typed = Handle(Geom2d_BezierCurve)::DownCast(value);
                !typed.IsNull())
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom2d_BezierCurve))
                    && addCurveArrays(typed, std::true_type{});
            if (const auto typed = Handle(Geom2d_BSplineCurve)::DownCast(value);
                !typed.IsNull()) {
                const auto& knots = typed->Knots();
                const auto& mults = typed->Multiplicities();
                const auto& flat = typed->KnotSequence();
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom2d_BSplineCurve))
                    && addCurveArrays(typed, std::true_type{})
                    && BRepCensusHArray<TColStd_HArray1OfReal, Standard_Real>(
                        census, &knots, std::size_t(knots.Length()), seen)
                    && BRepCensusHArray<TColStd_HArray1OfInteger,
                        Standard_Integer>(census, &mults,
                            std::size_t(mults.Length()), seen)
                    && BRepCensusHArray<TColStd_HArray1OfReal, Standard_Real>(
                        census, &flat, std::size_t(flat.Length()), seen);
            }
            if (const auto typed = Handle(Geom2d_TrimmedCurve)::DownCast(value);
                !typed.IsNull())
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom2d_TrimmedCurve))
                    && recurse(recurse, typed->BasisCurve());
            if (const auto typed = Handle(Geom2d_OffsetCurve)::DownCast(value);
                !typed.IsNull())
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom2d_OffsetCurve))
                    && recurse(recurse, typed->BasisCurve());
            if (const auto typed = Handle(Bisector_BisecAna)::DownCast(value);
                !typed.IsNull())
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Bisector_BisecAna))
                    && recurse(recurse, typed->Geom2dCurve());
            if (const auto typed = Handle(Bisector_BisecCC)::DownCast(value);
                !typed.IsNull())
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Bisector_BisecCC))
                    && recurse(recurse, typed->Curve(1))
                    && recurse(recurse, typed->Curve(2));
            if (!Handle(Bisector_BisecPC)::DownCast(value).IsNull())
                return BRepCensusTerm(census, census.geometry,
                    sizeof(Bisector_BisecPC));
            return false;
        };

        const auto surfaceArrays = [&](auto typed, bool spline) {
            const auto& poles = typed->Poles();
            const auto* weights = typed->Weights();
            std::size_t poleCount = 0;
            if (!BRepCensusProduct(std::size_t(poles.NbRows()),
                    std::size_t(poles.NbColumns()), poleCount)
                || !BRepCensusHArray<TColgp_HArray2OfPnt, gp_Pnt>(
                    census, &poles, poleCount, seen)
                || (weights && !BRepCensusHArray<TColStd_HArray2OfReal,
                    Standard_Real>(census, weights, poleCount, seen)))
                return false;
            (void)spline;
            return true;
        };

        const auto surface = [&](auto&& recurse,
                                 const Handle(Geom_Surface)& value) -> bool {
            if (value.IsNull() || !first(value.get())) return true;
#define CENSUS_SURFACE(Type) \
            if (!Handle(Type)::DownCast(value).IsNull()) \
                return BRepCensusTerm(census, census.geometry, sizeof(Type))
            CENSUS_SURFACE(Geom_Plane);
            CENSUS_SURFACE(Geom_ConicalSurface);
            CENSUS_SURFACE(Geom_CylindricalSurface);
            CENSUS_SURFACE(Geom_SphericalSurface);
            CENSUS_SURFACE(Geom_ToroidalSurface);
#undef CENSUS_SURFACE
            if (const auto typed = Handle(Geom_BezierSurface)::DownCast(value);
                !typed.IsNull())
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom_BezierSurface))
                    && surfaceArrays(typed, false);
            if (const auto typed = Handle(Geom_BSplineSurface)::DownCast(value);
                !typed.IsNull()) {
                if (!BRepCensusTerm(census, census.geometry,
                        sizeof(Geom_BSplineSurface))
                    || !surfaceArrays(typed, true)) return false;
                const auto& uk = typed->UKnots();
                const auto& vk = typed->VKnots();
                const auto& um = typed->UMultiplicities();
                const auto& vm = typed->VMultiplicities();
                const auto& uf = typed->UKnotSequence();
                const auto& vf = typed->VKnotSequence();
                return BRepCensusHArray<TColStd_HArray1OfReal, Standard_Real>(
                        census, &uk, std::size_t(uk.Length()), seen)
                    && BRepCensusHArray<TColStd_HArray1OfReal, Standard_Real>(
                        census, &vk, std::size_t(vk.Length()), seen)
                    && BRepCensusHArray<TColStd_HArray1OfInteger,
                        Standard_Integer>(census, &um,
                            std::size_t(um.Length()), seen)
                    && BRepCensusHArray<TColStd_HArray1OfInteger,
                        Standard_Integer>(census, &vm,
                            std::size_t(vm.Length()), seen)
                    && BRepCensusHArray<TColStd_HArray1OfReal, Standard_Real>(
                        census, &uf, std::size_t(uf.Length()), seen)
                    && BRepCensusHArray<TColStd_HArray1OfReal, Standard_Real>(
                        census, &vf, std::size_t(vf.Length()), seen);
            }
            if (const auto typed =
                    Handle(Geom_RectangularTrimmedSurface)::DownCast(value);
                !typed.IsNull())
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom_RectangularTrimmedSurface))
                    && recurse(recurse, typed->BasisSurface());
            if (const auto typed = Handle(Geom_OffsetSurface)::DownCast(value);
                !typed.IsNull()) {
                if (!BRepCensusTerm(census, census.geometry,
                        sizeof(Geom_OffsetSurface))
                    || !recurse(recurse, typed->BasisSurface())) return false;
                const Handle(Geom_OsculatingSurface)& osculating =
                    typed->OsculatingSurface();
                if (osculating.IsNull() || !first(osculating.get()))
                    return true;
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom_OsculatingSurface))
                    && recurse(recurse, osculating->BasisSurface());
            }
            if (const auto typed =
                    Handle(Geom_SurfaceOfLinearExtrusion)::DownCast(value);
                !typed.IsNull())
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom_SurfaceOfLinearExtrusion))
                    && curve3d(curve3d, typed->BasisCurve());
            if (const auto typed =
                    Handle(Geom_SurfaceOfRevolution)::DownCast(value);
                !typed.IsNull())
                return BRepCensusTerm(census, census.geometry,
                        sizeof(Geom_SurfaceOfRevolution))
                    && curve3d(curve3d, typed->BasisCurve());
            if (!Handle(GeomPlate_Surface)::DownCast(value).IsNull())
                return BRepCensusTerm(census, census.geometry,
                    sizeof(GeomPlate_Surface));
            if (const auto typed =
                    Handle(ShapeExtend_CompositeSurface)::DownCast(value);
                !typed.IsNull()) {
                if (!BRepCensusTerm(census, census.geometry,
                        sizeof(ShapeExtend_CompositeSurface))) return false;
                const auto patches = typed->Patches();
                if (!patches.IsNull()) {
                    std::size_t count = 0;
                    if (!BRepCensusProduct(std::size_t(patches->NbRows()),
                            std::size_t(patches->NbColumns()), count)
                        || !BRepCensusHArray<TColGeom_HArray2OfSurface,
                            Handle(Geom_Surface)>(census, patches.get(), count,
                                seen)) return false;
                    for (Standard_Integer u = patches->LowerRow();
                         u <= patches->UpperRow(); ++u)
                        for (Standard_Integer v = patches->LowerCol();
                             v <= patches->UpperCol(); ++v)
                            if (!recurse(recurse, patches->Value(u, v)))
                                return false;
                }
                const auto uj = typed->UJointValues();
                const auto vj = typed->VJointValues();
                return (uj.IsNull()
                        || BRepCensusHArray<TColStd_HArray1OfReal,
                            Standard_Real>(census, uj.get(),
                                std::size_t(uj->Length()), seen))
                    && (vj.IsNull()
                        || BRepCensusHArray<TColStd_HArray1OfReal,
                            Standard_Real>(census, vj.get(),
                                std::size_t(vj->Length()), seen));
            }
            return false;
        };

        const auto triangulation = [&](
            const Handle(Poly_Triangulation)& value) {
            if (value.IsNull() || !first(value.get())) return true;
            if (typeid(*value.get()) != typeid(Poly_Triangulation))
                return false; // O1: a new observed subtype is a STOP.
            if (!BRepCensusTerm(census, census.representations,
                    sizeof(Poly_Triangulation))) return false;
            std::size_t nodes = 0, triangles = 0, uvs = 0, normals = 0;
            if (!BRepCensusProduct(std::size_t(value->NbNodes()),
                    sizeof(gp_Pnt), nodes)
                || !BRepCensusProduct(std::size_t(value->NbTriangles()),
                    sizeof(Poly_Triangle), triangles)
                || !BRepCensusProduct(std::size_t(value->HasUVNodes()
                        ? value->NbNodes() : 0), sizeof(gp_Pnt2d), uvs)
                || !BRepCensusProduct(std::size_t(value->HasNormals()
                        ? value->NbNodes() : 0), sizeof(gp_Vec3f), normals))
                return false;
            if (!BRepCensusAdd(census.meshNodes, nodes)
                || !BRepCensusAdd(census.meshTriangles, triangles)
                || !BRepCensusAdd(census.meshUVNodes, uvs)
                || !BRepCensusAdd(census.meshNormals, normals)) return false;
            const auto& actualNodes = value->InternalNodes();
            const auto& actualUVs = value->InternalUVNodes();
            census.actualMeshNodesAreDouble =
                census.actualMeshNodesAreDouble && actualNodes.IsDoublePrecision();
            census.actualMeshUVNodesAreDouble = census.actualMeshUVNodesAreDouble
                && (!value->HasUVNodes() || actualUVs.IsDoublePrecision());
            std::size_t physicalNodes = 0, physicalUVs = 0;
            if (!BRepCensusProduct(std::size_t(actualNodes.Length()),
                    actualNodes.IsDoublePrecision() ? sizeof(gp_Pnt)
                                                    : sizeof(gp_Vec3f),
                    physicalNodes)
                || !BRepCensusProduct(std::size_t(actualUVs.Length()),
                    actualUVs.IsDoublePrecision() ? sizeof(gp_Pnt2d)
                                                  : sizeof(gp_Vec2f),
                    physicalUVs)) return false;
            std::size_t physical = physicalNodes;
            std::size_t logical = nodes;
            if (!BRepCensusAdd(physical, physicalUVs)
                || !BRepCensusAdd(physical, triangles)
                || !BRepCensusAdd(physical, normals)
                || !BRepCensusAdd(census.meshPhysical, physical)
                || !BRepCensusAdd(logical, triangles)
                || !BRepCensusAdd(logical, uvs)
                || !BRepCensusAdd(logical, normals)) return false;
            if (!BRepCensusTerm(census, census.meshLogical, logical))
                return false;
            if (value->HasCachedMinMax() && first(&value->CachedMinMax())
                && !BRepCensusTerm(census, census.representations,
                    sizeof(Bnd_Box))) return false;
            const auto& parameters = value->Parameters();
            return !includeTriangulationParameters || parameters.IsNull()
                || !first(parameters.get())
                || BRepCensusTerm(census, census.representations,
                    sizeof(Poly_TriangulationParameters));
        };

        const auto polygon3d = [&](const Handle(Poly_Polygon3D)& value) {
            if (value.IsNull() || !first(value.get())) return true;
            std::size_t elements = 0;
            if (!BRepCensusProduct(std::size_t(value->NbNodes()),
                    sizeof(gp_Pnt), elements)
                || !BRepCensusTerm(census, census.polygonStorage,
                    sizeof(Poly_Polygon3D) + elements)) return false;
            if (value->HasParameters()) {
                const auto& values = value->Parameters();
                if (!BRepCensusHArray<TColStd_HArray1OfReal, Standard_Real>(
                    census, &values, std::size_t(values.Length()), seen))
                    return false;
            }
            return true;
        };
        const auto polygon2d = [&](const Handle(Poly_Polygon2D)& value) {
            if (value.IsNull() || !first(value.get())) return true;
            std::size_t elements = 0;
            return BRepCensusProduct(std::size_t(value->NbNodes()),
                    sizeof(gp_Pnt2d), elements)
                && BRepCensusTerm(census, census.polygonStorage,
                    sizeof(Poly_Polygon2D) + elements);
        };
        const auto polygonOnTriangulation = [&] (
            const Handle(Poly_PolygonOnTriangulation)& value) {
            if (value.IsNull() || !first(value.get())) return true;
            std::size_t elements = 0;
            if (!BRepCensusProduct(std::size_t(value->NbNodes()),
                    sizeof(Standard_Integer), elements)
                || !BRepCensusTerm(census, census.polygonStorage,
                    sizeof(Poly_PolygonOnTriangulation) + elements))
                return false;
            const auto& parameters = value->Parameters();
            return parameters.IsNull()
                || BRepCensusHArray<TColStd_HArray1OfReal, Standard_Real>(
                    census, parameters.get(),
                    std::size_t(parameters->Length()), seen);
        };

        BRepRepresentationCensus sourceBundles, copiedBundles;
        BRepCensusIdentitySet sourceBundleSeen(accounting);
        const auto measureBundle = [&](auto&& visitor) {
            graphCensus = &sourceBundles;
            graphSeen = &sourceBundleSeen;
            if (!visitor()) {
                graphCensus = sourceCensusTarget;
                graphSeen = &sourceSeen;
                return false;
            }
            BRepRepresentationCensus copiedBundle;
            BRepCensusIdentitySet copiedBundleSeen(accounting);
            graphCensus = &copiedBundle;
            graphSeen = &copiedBundleSeen;
            const bool measured = visitor();
            graphCensus = sourceCensusTarget;
            graphSeen = &sourceSeen;
            return measured
                && BRepCensusAccumulate(copiedBundles, copiedBundle);
        };
        // Raw source storage is independent of effective-key deduplication.
        // Census every concrete occurrence-local chain before visiting only
        // the first semantic representative for topology/copy multiplicity.
        for (Standard_Integer index = 1; index <= topology.Extent(); ++index)
            if (!location(topology.FindKey(index).Location())) return false;

        for (Standard_Integer index = 1; index <= topology.Extent(); ++index) {
            const TopoDS_Shape& item = topology.FindKey(index);
            if (!topology.IsRepresentative(index)) continue;
            const auto& tshape = item.TShape();
            if (tshape.IsNull()) return false;
            if (first(tshape.get())) {
                std::size_t inlineBytes = 0;
                if (!Handle(BRep_TVertex)::DownCast(tshape).IsNull())
                    inlineBytes = sizeof(BRep_TVertex);
                else if (!Handle(BRep_TEdge)::DownCast(tshape).IsNull())
                    inlineBytes = sizeof(BRep_TEdge);
                else if (!Handle(BRep_TFace)::DownCast(tshape).IsNull())
                    inlineBytes = sizeof(BRep_TFace);
                else if (!Handle(TopoDS_TWire)::DownCast(tshape).IsNull())
                    inlineBytes = sizeof(TopoDS_TWire);
                else if (!Handle(TopoDS_TShell)::DownCast(tshape).IsNull())
                    inlineBytes = sizeof(TopoDS_TShell);
                else if (!Handle(TopoDS_TSolid)::DownCast(tshape).IsNull())
                    inlineBytes = sizeof(TopoDS_TSolid);
                else if (!Handle(TopoDS_TCompSolid)::DownCast(tshape).IsNull())
                    inlineBytes = sizeof(TopoDS_TCompSolid);
                else if (!Handle(TopoDS_TCompound)::DownCast(tshape).IsNull())
                    inlineBytes = sizeof(TopoDS_TCompound);
                else return false;
                std::size_t childNodes = 0;
                if (!BRepCensusTerm(census, census.tShapes, inlineBytes)
                    || !BRepCensusProduct(std::size_t(tshape->NbChildren()),
                        sizeof(NCollection_TListNode<TopoDS_Shape>), childNodes)
                    || !BRepCensusTerm(census, census.listNodes, childNodes))
                    return false;
            }
            if (const auto vertex = Handle(BRep_TVertex)::DownCast(tshape);
                !vertex.IsNull()) {
                std::size_t listBytes = 0;
                if (!BRepCensusProduct(std::size_t(vertex->Points().Size()),
                        sizeof(NCollection_TListNode<
                            Handle(BRep_PointRepresentation)>), listBytes)
                    || !BRepCensusTerm(census, census.listNodes, listBytes))
                    return false;
                for (const auto& representation : vertex->Points()) {
                    if (representation.IsNull()
                        || !first(representation.get())) continue;
                    if (!location(representation->Location())) return false;
                    if (const auto typed =
                            Handle(BRep_PointOnCurve)::DownCast(representation);
                        !typed.IsNull()) {
                        if (!BRepCensusTerm(census, census.representations,
                                sizeof(BRep_PointOnCurve))
                            || !curve3d(curve3d, typed->Curve())) return false;
                    } else if (const auto typed =
                            Handle(BRep_PointOnCurveOnSurface)::DownCast(
                                representation); !typed.IsNull()) {
                        if (!BRepCensusTerm(census, census.representations,
                                sizeof(BRep_PointOnCurveOnSurface))
                            || !curve2d(curve2d, typed->PCurve())
                            || !surface(surface, typed->Surface())) return false;
                    } else if (const auto typed =
                            Handle(BRep_PointOnSurface)::DownCast(representation);
                        !typed.IsNull()) {
                        if (!BRepCensusTerm(census, census.representations,
                                sizeof(BRep_PointOnSurface))
                            || !surface(surface, typed->Surface())) return false;
                    } else return false;
                }
            }
            if (const auto edge = Handle(BRep_TEdge)::DownCast(tshape);
                !edge.IsNull()) {
                std::size_t listBytes = 0;
                if (!BRepCensusProduct(std::size_t(edge->Curves().Size()),
                        sizeof(NCollection_TListNode<
                            Handle(BRep_CurveRepresentation)>), listBytes)
                    || !BRepCensusTerm(census, census.listNodes, listBytes))
                    return false;
                for (const auto& representation : edge->Curves()) {
                    if (representation.IsNull()
                        || !first(representation.get())) continue;
                    if (!location(representation->Location())) return false;
                    if (const auto closed =
                            Handle(BRep_CurveOnClosedSurface)::DownCast(
                                representation); !closed.IsNull()) {
                        if (!BRepCensusTerm(census, census.representations,
                                sizeof(BRep_CurveOnClosedSurface))
                            || !curve2d(curve2d, closed->PCurve())
                            || !curve2d(curve2d, closed->PCurve2())
                            || !surface(surface, closed->Surface())) return false;
                    } else if (const auto typed =
                            Handle(BRep_CurveOnSurface)::DownCast(representation);
                        !typed.IsNull()) {
                        if (!BRepCensusTerm(census, census.representations,
                                sizeof(BRep_CurveOnSurface))
                            || !curve2d(curve2d, typed->PCurve())
                            || !surface(surface, typed->Surface())) return false;
                    } else if (const auto typed =
                            Handle(BRep_Curve3D)::DownCast(representation);
                        !typed.IsNull()) {
                        if (!BRepCensusTerm(census, census.representations,
                                sizeof(BRep_Curve3D))
                            || !curve3d(curve3d, typed->Curve3D())) return false;
                    } else if (const auto typed =
                            Handle(BRep_CurveOn2Surfaces)::DownCast(
                                representation); !typed.IsNull()) {
                        if (!BRepCensusTerm(census, census.representations,
                                sizeof(BRep_CurveOn2Surfaces))
                            || !surface(surface, typed->Surface())
                            || !surface(surface, typed->Surface2())
                            || !location(typed->Location2())) return false;
                    } else if (const auto closed =
                            Handle(BRep_PolygonOnClosedTriangulation)::DownCast(
                                representation); !closed.IsNull()) {
                        if (!BRepCensusTerm(census, census.representations,
                                sizeof(BRep_PolygonOnClosedTriangulation))
                            || !polygonOnTriangulation(
                                closed->PolygonOnTriangulation())
                            || !polygonOnTriangulation(
                                closed->PolygonOnTriangulation2())
                            || !triangulation(closed->Triangulation()))
                            return false;
                    } else if (const auto typed =
                            Handle(BRep_PolygonOnTriangulation)::DownCast(
                                representation); !typed.IsNull()) {
                        if (!BRepCensusTerm(census, census.representations,
                                sizeof(BRep_PolygonOnTriangulation))
                            || !polygonOnTriangulation(
                                typed->PolygonOnTriangulation())
                            || !triangulation(typed->Triangulation()))
                            return false;
                    } else if (const auto closed =
                            Handle(BRep_PolygonOnClosedSurface)::DownCast(
                                representation); !closed.IsNull()) {
                        if (!BRepCensusTerm(census, census.representations,
                                sizeof(BRep_PolygonOnClosedSurface))
                            || !polygon2d(closed->Polygon())
                            || !polygon2d(closed->Polygon2())
                            || !surface(surface, closed->Surface())) return false;
                    } else if (const auto typed =
                            Handle(BRep_PolygonOnSurface)::DownCast(
                                representation); !typed.IsNull()) {
                        if (!BRepCensusTerm(census, census.representations,
                                sizeof(BRep_PolygonOnSurface))
                            || !polygon2d(typed->Polygon())
                            || !surface(surface, typed->Surface())) return false;
                    } else if (const auto typed =
                            Handle(BRep_Polygon3D)::DownCast(representation);
                        !typed.IsNull()) {
                        if (!BRepCensusTerm(census, census.representations,
                                sizeof(BRep_Polygon3D))
                            || !polygon3d(typed->Polygon3D())) return false;
                    } else return false;
                }
                if (copyPrediction) {
                    const BRepCensusOccurrenceWord edgeEffective(
                        topology.Root(), topology.Ordinal(index));
                    const TopLoc_Location* edgeCurveLocal = nullptr;
                    const Handle(Geom_Curve) edgeCurve =
                        BRepCensusFirstCurve3D(edge, &edgeCurveLocal);
                    std::size_t curveRepresentations = 0;
                    for (const auto& representation : edge->Curves()) {
                        const auto curveRepresentation =
                            Handle(BRep_Curve3D)::DownCast(representation);
                        if (curveRepresentation.IsNull()) continue;
                        if (!BRepCensusAdd(curveRepresentations, 1)
                            || curveRepresentation->Curve3D().get()
                                != edgeCurve.get()) return false;
                    }
                    if (curveRepresentations
                        != (edgeCurve.IsNull() ? 0U : 1U)) return false;
                    if (!edgeCurve.IsNull()
                        && !measureBundle([&] {
                            return curve3d(curve3d, edgeCurve);
                        }))
                        return false;
                    if (edgeCurveLocal) {
                        const BRepCensusLocationWord local(*edgeCurveLocal);
                        const BRepCensusReducedProductWord descriptor(
                            edgeEffective, local);
                        std::size_t descriptorCount = 0;
                        if (!descriptor.Count(descriptorCount)) return false;
                    }

                    const TopLoc_Location* edgePolygonLocal = nullptr;
                    const Handle(Poly_Polygon3D) edgePolygon =
                        BRepCensusFirstPolygon3D(edge, &edgePolygonLocal);
                    std::size_t polygonRepresentations = 0;
                    for (const auto& representation : edge->Curves()) {
                        const auto polygonRepresentation =
                            Handle(BRep_Polygon3D)::DownCast(representation);
                        if (polygonRepresentation.IsNull()) continue;
                        if (!BRepCensusAdd(polygonRepresentations, 1)
                            || polygonRepresentation->Polygon3D().get()
                                != edgePolygon.get()) return false;
                    }
                    if (polygonRepresentations
                        != (edgePolygon.IsNull() ? 0U : 1U)) return false;
                    if (!edgePolygon.IsNull()
                        && !measureBundle(
                            [&] { return polygon3d(edgePolygon); }))
                        return false;
                    if (edgePolygonLocal) {
                        const BRepCensusLocationWord local(*edgePolygonLocal);
                        const BRepCensusReducedProductWord descriptor(
                            edgeEffective, local);
                        std::size_t descriptorCount = 0;
                        if (!descriptor.Count(descriptorCount)) return false;
                    }

                    const auto pcurveIsCopied = [&](const void* identity) {
                        bool copied = false;
                        return BRepCensusPCurveIdentityIsCopied(
                            topology, index, identity, copied) && copied;
                    };
                    const auto polygonOnMeshIsCopied =
                        [&](const void* identity) {
                            bool copied = false;
                            return BRepCensusPolygonIdentityIsCopied(
                                topology, index, identity, copied) && copied;
                        };
                    for (const auto& representation : edge->Curves()) {
                        if (const auto closed =
                                Handle(BRep_CurveOnClosedSurface)::DownCast(
                                    representation); !closed.IsNull()) {
                            if (!pcurveIsCopied(closed->PCurve().get())
                                || !pcurveIsCopied(
                                    closed->PCurve2().get())) return false;
                        } else if (const auto pcurve =
                                Handle(BRep_CurveOnSurface)::DownCast(
                                    representation); !pcurve.IsNull()) {
                            if (!pcurveIsCopied(pcurve->PCurve().get()))
                                return false;
                        } else if (const auto closed = Handle(
                                BRep_PolygonOnClosedTriangulation)::DownCast(
                                    representation); !closed.IsNull()) {
                            if (!polygonOnMeshIsCopied(closed->
                                    PolygonOnTriangulation().get())
                                || !polygonOnMeshIsCopied(closed->
                                    PolygonOnTriangulation2().get()))
                                return false;
                        } else if (const auto polygon = Handle(
                                BRep_PolygonOnTriangulation)::DownCast(
                                    representation); !polygon.IsNull()) {
                            if (!polygonOnMeshIsCopied(polygon->
                                    PolygonOnTriangulation().get()))
                                return false;
                        } else if (!Handle(BRep_PolygonOnSurface)::DownCast(
                                representation).IsNull()) {
                            return false;
                        }
                    }

                }
            }
            if (const auto face = Handle(BRep_TFace)::DownCast(tshape);
                !face.IsNull()) {
                if (!BRepCensusAdd(census.faceCount, 1)) return false;
                if (!surface(surface, face->Surface())
                    || !location(face->Location()))
                    return false;
                std::size_t listBytes = 0;
                if (!BRepCensusProduct(
                        std::size_t(face->Triangulations().Size()),
                        sizeof(NCollection_TListNode<
                            Handle(Poly_Triangulation)>), listBytes)
                    || !BRepCensusTerm(census, census.listNodes, listBytes))
                    return false;
                for (const auto& mesh : face->Triangulations())
                    if (!triangulation(mesh)) return false;
                if (copyPrediction) {
                    const Handle(Geom_Surface) faceSurface = face->Surface();
                    if (!faceSurface.IsNull()
                        && !measureBundle(
                            [&] {
                                return surface(surface, faceSurface);
                            })) return false;

                    const Handle(Poly_Triangulation) activeMesh =
                        face->ActiveTriangulation();
                    if (std::size_t(face->Triangulations().Size())
                            != (activeMesh.IsNull() ? 0U : 1U)) return false;
                    for (const auto& listedMesh : face->Triangulations())
                        if (listedMesh.get() != activeMesh.get()) return false;
                    if (!activeMesh.IsNull()) {
                        includeTriangulationParameters = false;
                        const bool measured = measureBundle(
                            [&] { return triangulation(activeMesh); });
                        includeTriangulationParameters = true;
                        if (!measured) return false;
                    }

                    const BRepCensusOccurrenceWord faceEffective(
                        topology.Root(), topology.Ordinal(index));
                    for (Standard_Integer edgeIndex = index + 1;
                         edgeIndex <= topology.Extent(); ++edgeIndex) {
                        bool descendant = false;
                        if (!topology.IsDescendant(
                                edgeIndex, index, descendant)) return false;
                        if (!descendant) break;
                        if (topology.FindKey(edgeIndex).ShapeType()
                            != TopAbs_EDGE) continue;
                        bool alreadyVisited = false;
                        for (Standard_Integer prior = index + 1;
                             prior < edgeIndex; ++prior) {
                            bool priorDescendant = false;
                            if (!topology.IsDescendant(
                                    prior, index, priorDescendant)) return false;
                            if (!priorDescendant) break;
                            if (topology.FindKey(prior).ShapeType()
                                != TopAbs_EDGE) continue;
                            bool same = false;
                            if (!topology.SameKey(
                                    edgeIndex, prior, same)) return false;
                            if (same) {
                                alreadyVisited = true;
                                break;
                            }
                        }
                        if (alreadyVisited) continue;
                        const TopoDS_Shape& edgeKey =
                            topology.FindKey(edgeIndex);
                        const auto edgeTShape = Handle(BRep_TEdge)::DownCast(
                            edgeKey.TShape());
                        if (edgeTShape.IsNull()) return false;
                        bool seam = false;
                        if (!BRepCensusEffectiveSeam(topology, edgeIndex,
                                index, face, activeMesh, seam)) return false;
                        const BRepCensusOccurrenceWord edgeEffective(
                            topology.Root(), topology.Ordinal(edgeIndex));
                        for (int member = 0; member < (seam ? 2 : 1);
                             ++member) {
                            TopAbs_Orientation selectedOrientation =
                                edgeKey.Orientation();
                            if (member == 1) selectedOrientation =
                                TopAbs::Reverse(selectedOrientation);
                            if (item.Orientation() == TopAbs_REVERSED)
                                selectedOrientation =
                                    TopAbs::Reverse(selectedOrientation);
                            const auto lookup = BRepCensusLookupStoredPCurve(
                                edgeTShape, face, edgeEffective,
                                faceEffective, selectedOrientation);
                            if (lookup.kind
                                    == BRepCensusPCurveLookupKind::Failure
                                || lookup.kind
                                    == BRepCensusPCurveLookupKind::
                                        NeedsPlanarProjection)
                                return false;
                            const Handle(Geom2d_Curve) pcurve = lookup.stored;
                            if (!pcurve.IsNull()
                                && !measureBundle(
                                    [&] {
                                        return curve2d(curve2d, pcurve);
                                    }))
                                return false;

                            BRepCensusPolygonLookup polygon;
                            if (!activeMesh.IsNull())
                                polygon = BRepCensusLookupStoredPolygon(
                                    edgeTShape, activeMesh, edgeEffective,
                                    faceEffective,
                                    member == 1
                                        ? TopAbs::Reverse(edgeKey.Orientation())
                                        : edgeKey.Orientation());
                            if (polygon.failed) return false;
                            if (!polygon.stored.IsNull()
                                && !measureBundle([&] {
                                    return polygonOnTriangulation(polygon.stored);
                                })) return false;
                        }
                    }

                }
            }
        }
        // Concrete copier inline state is observable; O23--O31 backing and
        // native call scratch remain explicitly unmeasured.
        if (!BRepCensusTerm(census, census.representations,
                sizeof(BRepBuilderAPI_Copy))) return false;
        std::size_t faceMapEntries = 0, faceMapIndex = 0;
        std::size_t faceMapCapacity = 0, twoFaceMaps = 0;
        if (!BRepCensusProduct(census.faceCount,
                BRepCensusShapeMap::EntrySize(), faceMapEntries)
            || !BRepCensusMapCapacity(census.faceCount, faceMapCapacity)
            || !BRepCensusProduct(faceMapCapacity + 1,
                sizeof(NCollection_ListNode*), faceMapIndex)
            || !BRepCensusAdd(faceMapEntries, faceMapIndex)
            || !BRepCensusAdd(faceMapEntries, sizeof(BRepCensusShapeMap))
            || !BRepCensusProduct(faceMapEntries, 2, twoFaceMaps)
            || !BRepCensusAdd(twoFaceMaps, sizeof(Bnd_Box))
            || !BRepCensusAdd(twoFaceMaps, sizeof(BRepAdaptor_Surface)))
            return false;
        census.visibleDownstreamScratch = twoFaceMaps;
        if (copyPrediction) {
            *copyPrediction = census;
            graphCensus = sourceCensusTarget;
            graphSeen = &sourceSeen;
            includeTriangulationParameters = true;
            if (!BRepCensusApplyBundleDelta(*copyPrediction,
                    copiedBundles, sourceBundles)) return false;

            // T14 is the union of nodes/datums reachable from final copied
            // fields, not source inventory plus a scalar. The union replays
            // concrete and native-event identities without constructing a
            // TopLoc value or allocating pre-admission storage.
            std::size_t predictedNodeCount = 0, predictedDatumCount = 0;
            std::size_t predictedNodeBytes = 0, predictedDatumBytes = 0;
            if (!BRepCensusPredictedFinalLocationCounts(topology,
                    predictedNodeCount, predictedDatumCount)
                || !BRepCensusProduct(predictedNodeCount,
                    sizeof(TopLoc_SListNodeOfItemLocation),
                    predictedNodeBytes)
                || !BRepCensusProduct(predictedDatumCount,
                    sizeof(TopLoc_Datum3D), predictedDatumBytes)
                || predictedNodeBytes < census.locationNodes
                || predictedDatumBytes < census.locationDatums)
                return false;
            const std::size_t nodeDelta =
                predictedNodeBytes - census.locationNodes;
            const std::size_t datumDelta =
                predictedDatumBytes - census.locationDatums;
            std::size_t locationDelta = nodeDelta;
            if (!BRepCensusAdd(locationDelta, datumDelta)
                || !BRepCensusAdd(copyPrediction->locations, locationDelta)
                || !BRepCensusAdd(copyPrediction->locationNodes, nodeDelta)
                || !BRepCensusAdd(copyPrediction->locationDatums, datumDelta)
                || !BRepCensusAdd(copyPrediction->total, locationDelta))
                return false;
            std::size_t predictedNewIdentities =
                nodeDelta / sizeof(TopLoc_SListNodeOfItemLocation);
            if (nodeDelta % sizeof(TopLoc_SListNodeOfItemLocation) != 0
                || datumDelta % sizeof(TopLoc_Datum3D) != 0
                || !BRepCensusAdd(predictedNewIdentities,
                    datumDelta / sizeof(TopLoc_Datum3D))) return false;
            std::size_t predictedLocationScratch = 0;
            if (!BRepCensusProduct(predictedNewIdentities,
                    BRepCensusIdentitySet::EntrySize(),
                    predictedLocationScratch)
                || !BRepCensusAdd(copyPrediction->observableMapScratch,
                    predictedLocationScratch)) return false;
        }
        return accounting.Recheck(FailureSite::BRepCensusMeasure);
    } catch (...) {
        accounting.AllocationFailed(FailureSite::BRepCensusMeasure);
        return false;
    }
}
#undef seen
#undef census

