namespace {

struct SavedGroupMeasuredMember final {
    decal_layer::bake::accounting::Ticket storage;
    TopoDS_Shape original;
    TopoDS_Shape detached;
    std::unique_ptr<BRepBuilderAPI_Copy> copier;
    TopTools_IndexedMapOfShape originalFaces;
    TopTools_IndexedMapOfShape detachedFaces;
    std::string definitionIdentifier;
    std::size_t savedTriangleCount = 0;
};

struct SavedGroupOccurrenceScope final {
    struct Entry final {
        std::string occurrenceIdentifier;
        std::string definitionIdentifier;
        std::size_t sourceInstanceIndex = 0;
        Matrix4d transform;
    };
    std::vector<Entry> entries;
    std::vector<std::string> expectedReceiverIdentifiers;
};

struct SavedGroupFinalResult final {
    painted_atlas_bake::owner::ExportBake bake;
    SavedGroupOccurrenceScope occurrences;
    std::vector<std::string> memberDefinitions;
    std::vector<std::size_t> finalTriangleCounts;
    std::vector<std::size_t> finalCornerCounts;
};

//! Distinct one-group authority. It deliberately does not reuse the
//! standalone receiver Owner above: membership comes only from the strict
//! persisted ExportCapture and always retains saved order.
struct SavedGroupOwner final {
    retained_edge_treatment::ReplayBudget budget;
    painted_atlas_bake::owner::ExportCapture capture;
    decal_layer::bake::accounting::Ticket measuredVectorTicket;
    std::vector<SavedGroupMeasuredMember> measured;
    painted_atlas_bake::owner::CapturedSourceStorage productionSources;
    painted_atlas_bake::owner::ExportBakePlan pendingPlan;
    SavedGroupOccurrenceScope pendingOccurrences;
    std::vector<std::string> pendingDefinitionOrder;
    std::vector<std::size_t> pendingTriangleCounts;
    std::vector<std::size_t> pendingCornerCounts;
    std::shared_ptr<const SavedGroupFinalResult> result;

    SavedGroupOwner() = default;
    SavedGroupOwner(const SavedGroupOwner&) = delete;
    SavedGroupOwner& operator=(const SavedGroupOwner&) = delete;
};

bool SavedGroupCancelled(const std::function<bool()>& cancelled) noexcept {
    if (!cancelled) return true;
    try { return cancelled(); }
    catch (...) { return true; }
}

bool PrepareSavedGroupOwner(
    OperationLedger& operation,
    const decal_layer::bake::accounting::View& accounting,
    painted_atlas_bake::owner::ExportCapture&& strictCapture,
    const Handle(OcctDocument)& privateDocument,
    const std::function<bool()>& cancelled,
    SavedGroupOwner& group,
    std::string& diagnosis,
    retained_edge_treatment::ReplayBudget* batchBudget = nullptr) noexcept {
    diagnosis.clear();
    try {
        const auto fail = [&diagnosis](const char* value) {
            diagnosis = value; return false;
        };
        if (privateDocument.IsNull() || SavedGroupCancelled(cancelled)
            || !strictCapture.operationView().valid()
            || strictCapture.operation.valid()
            || strictCapture.members.members.empty()
            || strictCapture.members.members.size()
                != strictCapture.savedAtlas.members.size())
            return fail("saved-group-capture-invalid");
        const Handle(TDocStd_Document)& document = privateDocument->Document();
        Standard_Real metersPerUnit = 0.0;
        if (document.IsNull() || document->HasOpenCommand()
            || !XCAFDoc_DocumentTool::GetLengthUnit(document, metersPerUnit)
            || !(metersPerUnit > 0.0))
            return fail("saved-group-document-invalid");

        group.capture = std::move(strictCapture);
        retained_edge_treatment::ReplayBudget& activeBudget = batchBudget
            ? *batchBudget : group.budget;
        if (!ReserveProtectedVector(group.measured,
                group.measuredVectorTicket, accounting,
                group.capture.members.members.size(),
                decal_layer::bake::accounting::Retention::Retained,
                decal_layer::bake::accounting::FailureSite::
                    ProtectedOwnerStorage))
            return fail("saved-group-member-storage");

        for (std::size_t index = 0;
             index < group.capture.members.members.size(); ++index) {
            if (SavedGroupCancelled(cancelled))
                return fail("saved-group-cancelled-before-copy");
            const auto& member = group.capture.members.members[index];
            if (!(member.slot.owner == group.capture.savedAtlas.members[index].owner))
                return fail("saved-group-member-order");
            SavedGroupMeasuredMember value;
            value.original = XCAFDoc_ShapeTool::GetShape(member.ownerLabel);
            value.definitionIdentifier =
                privateDocument->DefinitionIdentifierForLabel(member.ownerLabel);
            if (value.original.IsNull() || value.definitionIdentifier.empty())
                return fail("saved-group-member-shape");
            retained_solid::Record retained;
            retained_finishing::SourceRevision source;
            std::atomic_bool noCancellation{false};
            meshcopy::CurrentTessellationCopy savedCopy;
            if (!retained_finishing::producer::detail::Source(
                    document, member.slot.owner, source, nullptr, &retained)
                || !(source == member.slot.source)
                || meshcopy::PrepareCurrentTessellationCopy(
                    retained.current, savedCopy, noCancellation)
                    != meshcopy::PreparationResult::Ready
                || savedCopy.triangles <= 0)
                return fail("saved-group-saved-mesh");
            value.savedTriangleCount = std::size_t(savedCopy.triangles);
            BRepRepresentationCensus census;
            BRepRepresentationCensus prediction;
            BRepCensusPCurveLookup lookup;
            decal_layer::bake::accounting::Ticket scratch;
            if (!MeasureBRepRepresentation(value.original, activeBudget,
                    accounting, census, scratch, &prediction, &lookup))
                return fail("saved-group-member-census");
            scratch.reset();
            std::size_t retainedBytes = 0;
            if (!CopyMeasuredBRep(value.original, activeBudget, operation,
                    census, prediction, 0, value.storage, value.copier,
                    value.detached, value.originalFaces,
                    value.detachedFaces, retainedBytes
#ifdef DEBUG
                    , &accounting
#endif
                    )
                || value.detached.IsNull()
                || value.detached.IsSame(value.original))
                return fail("saved-group-member-copy");
            group.measured.push_back(std::move(value));
        }

        if (!ReserveProtectedVector(group.productionSources.values,
                group.productionSources.vectorTicket, accounting,
                group.capture.sources.size(),
                decal_layer::bake::accounting::Retention::Retained,
                decal_layer::bake::accounting::FailureSite::
                    ProtectedSourceStorage))
            return fail("saved-group-source-storage");
        for (std::size_t sourceIndex = 0;
             sourceIndex < group.capture.sources.size(); ++sourceIndex) {
            painted_atlas_bake::owner::CapturedSource source(
                group.capture.sources[sourceIndex]);
            std::size_t memberIndex = group.measured.size();
            for (std::size_t index = 0; index < group.measured.size(); ++index) {
                if (!(group.capture.savedAtlas.members[index].owner
                        == source.fence.owner)) continue;
                if (memberIndex != group.measured.size())
                    return fail("saved-group-source-owner-duplicate");
                memberIndex = index;
            }
            if (memberIndex == group.measured.size())
                return fail("saved-group-source-owner-foreign");
            source.memberIndex = memberIndex;
            source.order = sourceIndex;
            if (source.origin
                    == painted_atlas_bake::kernel::SourceOrigin::
                        OwnerMaterialSlot) {
                source.faceIndex = std::numeric_limits<std::size_t>::max();
            } else {
                Bnd_Box bounds;
                BRepBndLib::AddOptimal(group.measured[memberIndex].original,
                    bounds, Standard_False, Standard_False);
                if (bounds.IsVoid() || bounds.IsWhole() || bounds.IsOpen())
                    return fail("saved-group-source-bounds");
                int matches = 0;
                TopoDS_Face originalFace;
                for (Standard_Integer faceIndex = 1;
                     faceIndex <= group.measured[memberIndex].originalFaces.Extent();
                     ++faceIndex) {
                    const TopoDS_Face candidate = TopoDS::Face(
                        group.measured[memberIndex].originalFaces.FindKey(faceIndex));
                    dependent_replay::FaceImageGeometricReceipt receipt;
                    if (dependent_replay::detail::DeriveFaceImageReceipt(
                            bounds, candidate, metersPerUnit,
                            group.budget, receipt)
                            != dependent_replay::detail::
                                FaceImageDeriveStatus::Derived)
                        continue;
                    decal_layer::Digest proof{};
                    if (!dependent_replay::FaceImageReceiptProof(receipt, proof))
                        return fail("saved-group-source-receipt");
                    if (proof != source.fence.selectorProof) continue;
                    ++matches;
                    originalFace = candidate;
                }
                if (matches != 1 || originalFace.IsNull())
                    return fail("saved-group-source-selector");
                const TopoDS_Shape copied =
                    group.measured[memberIndex].copier->ModifiedShape(originalFace);
                const Standard_Integer copiedFace =
                    group.measured[memberIndex].detachedFaces.FindIndex(copied);
                if (copied.IsNull() || copied.ShapeType() != TopAbs_FACE
                    || copiedFace <= 0)
                    return fail("saved-group-source-correspondence");
                source.faceIndex = std::size_t(copiedFace - 1);
            }
            group.productionSources.values.push_back(std::move(source));
        }
        return group.measured.size() == group.capture.savedAtlas.members.size()
            && group.productionSources.size() == group.capture.sources.size();
    } catch (...) {
        diagnosis = "saved-group-preparation-exception";
        return false;
    }
}

bool SavedGroupExactFinalTriangles(
    const DefinitionData& definition,
    std::vector<shapeyard::uv::Triangle>& triangles) noexcept {
    triangles.clear();
    try {
        if (definition.shape.IsNull()
            || definition.mesh.indices.empty()
            || definition.mesh.indices.size() % 3U != 0) return false;
        triangles.resize(definition.mesh.indices.size() / 3U);
        std::size_t vertexBase = 0;
        std::size_t cornerOffset = 0;
        RWMesh_FaceIterator face(definition.shape);
        for (; face.More(); face.Next()) {
            if (face.NbNodes() <= 0 || face.NbTriangles() <= 0) return false;
            for (Standard_Integer triangleIndex = face.ElemLower();
                 triangleIndex <= face.ElemUpper(); ++triangleIndex) {
                const Poly_Triangle triangle =
                    face.TriangleOriented(triangleIndex);
                Standard_Integer nodes[3] = {0, 0, 0};
                triangle.Get(nodes[0], nodes[1], nodes[2]);
                if (cornerOffset + 3U > definition.mesh.indices.size())
                    return false;
                auto& output = triangles[cornerOffset / 3U];
                for (std::size_t corner = 0; corner < 3; ++corner) {
                    if (nodes[corner] < face.NodeLower()
                        || nodes[corner] > face.NodeUpper()) return false;
                    const std::uint32_t expected = std::uint32_t(
                        vertexBase + std::size_t(nodes[corner]
                            - face.NodeLower()));
                    if (definition.mesh.indices[cornerOffset + corner]
                            != expected) return false;
                    const gp_Pnt point = face.NodeTransformed(nodes[corner]);
                    if (!IsFinite(point.X()) || !IsFinite(point.Y())
                        || !IsFinite(point.Z())) return false;
                    output.points[corner] = {
                        point.X(), point.Y(), point.Z()};
                }
                cornerOffset += 3U;
            }
            vertexBase += std::size_t(face.NbNodes());
        }
        return cornerOffset == definition.mesh.indices.size()
            && vertexBase == definition.mesh.vertices.size();
    } catch (...) {
        triangles.clear();
        return false;
    }
}

painted_atlas_bake::owner::Outcome PrepareSavedGroupForBatch(
    SavedGroupOwner& group,
    const std::vector<DefinitionData>& actualFinalDefinitions,
    const SavedGroupOccurrenceScope& expectedOccurrences,
    const std::function<bool()>& cancelled,
    painted_atlas_bake::owner::AggregateBakePlan& aggregate,
    std::string& diagnosis
#ifdef DEBUG
    , const asset_atlas::build::DebugLayoutObserver* layoutObserver = nullptr
#endif
    ) noexcept {
    using Outcome = painted_atlas_bake::owner::Outcome;
    group.result.reset();
    group.pendingPlan = {};
    group.pendingOccurrences = {};
    group.pendingDefinitionOrder.clear();
    group.pendingTriangleCounts.clear();
    group.pendingCornerCounts.clear();
    diagnosis.clear();
    try {
        if (SavedGroupCancelled(cancelled)) {
            diagnosis = "saved-group-cancelled-before-build";
            return Outcome::Refused;
        }
        if (group.measured.empty()
            || group.measured.size() != group.capture.savedAtlas.members.size()
            || actualFinalDefinitions.size() < group.measured.size()) {
            diagnosis = "saved-group-final-definition-count";
            return Outcome::Malformed;
        }
        std::vector<asset_atlas::build::FinalMemberInput> inputs;
        inputs.reserve(group.measured.size());
        std::vector<std::string> definitionOrder;
        std::vector<std::size_t> triangleCounts;
        std::vector<std::size_t> cornerCounts;
        definitionOrder.reserve(group.measured.size());
        triangleCounts.reserve(group.measured.size());
        cornerCounts.reserve(group.measured.size());
        for (std::size_t memberIndex = 0;
             memberIndex < group.measured.size(); ++memberIndex) {
            const DefinitionData* definition = nullptr;
            for (const auto& candidate : actualFinalDefinitions) {
                if (candidate.mesh.definitionIdentifier
                        != group.measured[memberIndex].definitionIdentifier)
                    continue;
                if (definition) {
                    diagnosis = "saved-group-final-definition-duplicate";
                    return Outcome::Malformed;
                }
                definition = &candidate;
            }
            if (!definition || definition->shape.IsNull()
                || !definition->shape.IsSame(group.measured[memberIndex].detached)
                || definition->mesh.indices.empty()
                || definition->mesh.indices.size() % 3U != 0
                || definition->faces.Extent()
                    != group.measured[memberIndex].detachedFaces.Extent()) {
                diagnosis = "saved-group-final-definition-missing";
                return Outcome::StaleSource;
            }
            asset_atlas::build::FinalMemberInput input;
            input.savedMember = group.capture.members.members[memberIndex].slot;
            input.authority = group.capture.members.members[memberIndex].capture;
            if (!SavedGroupExactFinalTriangles(*definition,
                    input.triangles)) {
                diagnosis = "saved-group-final-index-stream";
                return Outcome::Malformed;
            }
            std::size_t coveredCorners = 0;
            for (const auto& primitive : definition->mesh.primitives) {
                const auto& analytic = primitive.analyticSourceFace;
                if (!analytic.available || primitive.firstIndex % 3U != 0
                    || primitive.indexCount == 0
                    || primitive.indexCount % 3U != 0
                    || std::size_t(primitive.firstIndex) != coveredCorners
                    || std::size_t(primitive.firstIndex)
                        + primitive.indexCount > definition->mesh.indices.size()
                    || (analytic.surfaceType != provenance::kSurfaceTypePlane
                        && analytic.surfaceType
                            != provenance::kSurfaceTypeCylinder)
                    || analytic.params.size()
                        != (analytic.surfaceType == provenance::kSurfaceTypePlane
                            ? 9U : 10U)) {
                    diagnosis = "saved-group-final-primitive";
                    return Outcome::UnsupportedSurface;
                }
                shapeyard::uv::curved::FaceInput face;
                face.surfaceType = analytic.surfaceType;
                face.firstTriangle = int(primitive.firstIndex / 3U);
                face.triangleCount = int(primitive.indexCount / 3U);
                face.reversed = analytic.reversed;
                face.params = analytic.params;
                face.toleranceMM = 1.0e-7;
                face.xDirection = {
                    analytic.params[6], analytic.params[7], analytic.params[8]};
                input.faces.push_back(std::move(face));
                coveredCorners += primitive.indexCount;
            }
            if (coveredCorners != definition->mesh.indices.size()) {
                diagnosis = "saved-group-final-corner-coverage";
                return Outcome::Malformed;
            }
            for (const auto& source : group.productionSources) {
                if (source.memberIndex == memberIndex
                    && source.faceIndex != std::numeric_limits<std::size_t>::max()
                    && source.faceIndex >= input.faces.size()) {
                    diagnosis = "saved-group-final-source-face";
                    return Outcome::StaleBinding;
                }
            }
            definitionOrder.push_back(
                group.measured[memberIndex].definitionIdentifier);
            triangleCounts.push_back(input.triangles.size());
            cornerCounts.push_back(definition->mesh.indices.size());
            inputs.push_back(std::move(input));
        }

        const asset_atlas::build::Settings settings{
            group.capture.savedAtlas.resolutionTexels,
            group.capture.savedAtlas.gutterTexels};
        const auto outcome = painted_atlas_bake::owner::PrepareBakeForExport(
            group.capture, group.productionSources, inputs, settings,
            group.pendingPlan, diagnosis
#ifdef DEBUG
            , layoutObserver
#endif
            );
        if (outcome != Outcome::Prepared
            || !painted_atlas_bake::owner::AdmitBakePlan(
                aggregate, group.pendingPlan)) return outcome == Outcome::Prepared
                    ? Outcome::OverBudget : outcome;
        group.pendingOccurrences = expectedOccurrences;
        group.pendingDefinitionOrder = std::move(definitionOrder);
        group.pendingTriangleCounts = std::move(triangleCounts);
        group.pendingCornerCounts = std::move(cornerCounts);
        return Outcome::Prepared;
    } catch (const std::bad_alloc&) {
        group.capture.operationView().AllocationFailed(
            decal_layer::bake::accounting::FailureSite::ExportBakeStorage);
        diagnosis = "saved-group-allocation";
        return Outcome::OverBudget;
    } catch (...) {
        diagnosis = "saved-group-build-exception";
        return Outcome::Malformed;
    }
}

painted_atlas_bake::owner::Outcome ExecuteSavedGroupForBatch(
    SavedGroupOwner& group,
    const painted_atlas_bake::owner::AggregateBakePlan& aggregate,
    const std::function<bool()>& cancelled,
    std::shared_ptr<const SavedGroupFinalResult>& output,
    std::string& diagnosis,
    const bool releaseEncodedRaster = false
#ifdef DEBUG
    , const painted_atlas_bake::kernel::DebugBakeObserver* bakeObserver = nullptr
#endif
    ) noexcept {
    using Outcome = painted_atlas_bake::owner::Outcome;
    output.reset();
    try {
        if (SavedGroupCancelled(cancelled)) {
            diagnosis = "saved-group-cancelled-before-execute";
            return Outcome::Refused;
        }
        painted_atlas_bake::owner::ExportBake baked;
        const auto outcome = painted_atlas_bake::owner::ExecuteBakeForExport(
            group.capture, group.productionSources, aggregate,
            group.pendingPlan, baked, diagnosis
#ifdef DEBUG
            , bakeObserver
#endif
            );
        if (outcome != Outcome::Prepared) return outcome;
        if (!baked.storage || baked.storage->layout.charts.empty()
            || baked.assignments.size()
                != group.pendingDefinitionOrder.size()) {
            diagnosis = "saved-group-result-incomplete";
            return Outcome::Malformed;
        }
        if (releaseEncodedRaster) {
            for (auto& role : baked.outputs) {
                std::vector<std::uint8_t>().swap(role.rgba);
                role.rgbaTicket.reset();
            }
        }
        const auto operation = group.capture.operationView();
        if (!baked.storage->bakeValueStorage.acquire(operation,
                decal_layer::bake::accounting::StorageDimension::PrivateStorage,
                sizeof(SavedGroupFinalResult),
                decal_layer::bake::accounting::Retention::Retained,
                decal_layer::bake::accounting::FailureSite::ExportBakeStorage)
            || !operation.EnterAllocation(
                decal_layer::bake::accounting::FailureSite::ExportBakeStorage)) {
            diagnosis = "saved-group-result-storage";
            return Outcome::OverBudget;
        }
        auto result = std::make_shared<SavedGroupFinalResult>();
        result->bake = std::move(baked);
        result->occurrences = std::move(group.pendingOccurrences);
        result->memberDefinitions = std::move(group.pendingDefinitionOrder);
        result->finalTriangleCounts = std::move(group.pendingTriangleCounts);
        result->finalCornerCounts = std::move(group.pendingCornerCounts);
        group.result = result;
        output = std::move(result);
        return Outcome::Prepared;
    } catch (const std::bad_alloc&) {
        group.capture.operationView().AllocationFailed(
            decal_layer::bake::accounting::FailureSite::ExportBakeStorage);
        diagnosis = "saved-group-allocation";
        return Outcome::OverBudget;
    } catch (...) {
        diagnosis = "saved-group-build-exception";
        return Outcome::Malformed;
    }
}

painted_atlas_bake::owner::Outcome BuildSavedGroupForExport(
    SavedGroupOwner& group,
    const std::vector<DefinitionData>& actualFinalDefinitions,
    const SavedGroupOccurrenceScope& expectedOccurrences,
    const std::function<bool()>& cancelled,
    std::shared_ptr<const SavedGroupFinalResult>& output,
    std::string& diagnosis
#ifdef DEBUG
    , const asset_atlas::build::DebugLayoutObserver* layoutObserver = nullptr,
    const painted_atlas_bake::kernel::DebugBakeObserver* bakeObserver = nullptr
#endif
    ) noexcept {
    painted_atlas_bake::owner::AggregateBakePlan aggregate;
    auto outcome = PrepareSavedGroupForBatch(group, actualFinalDefinitions,
        expectedOccurrences, cancelled, aggregate, diagnosis
#ifdef DEBUG
        , layoutObserver
#endif
        );
    if (outcome != painted_atlas_bake::owner::Outcome::Prepared)
        return outcome;
    if (!painted_atlas_bake::owner::SealBakePlan(aggregate)) {
        diagnosis = "saved-group-plan-seal";
        return painted_atlas_bake::owner::Outcome::OverBudget;
    }
    return ExecuteSavedGroupForBatch(group, aggregate, cancelled,
        output, diagnosis, false
#ifdef DEBUG
        , bakeObserver
#endif
        );
}

SavedGroupAllMemberLayoutReason PrepareSavedGroupLayoutRecord(
    std::vector<std::unique_ptr<SavedGroupOwner>>& groups,
    const Handle(OcctDocument)& privateDocument,
    const SceneSnapshot& wholeCommittedScene,
    const bool selectedObjectsOnly,
    const std::function<bool()>& cancelled,
    decal_layer::bake::accounting::Ticket& controlTicket,
    std::shared_ptr<const SavedGroupAllMemberLayoutRecord>& output) noexcept {
    using Outcome = painted_atlas_bake::owner::Outcome;
    using Reason = SavedGroupAllMemberLayoutReason;
    using Dimension = decal_layer::bake::accounting::StorageDimension;
    using Retention = decal_layer::bake::accounting::Retention;
    using FailureSite = decal_layer::bake::accounting::FailureSite;
    output.reset();
    if (groups.empty()) return Reason::Unavailable;
    const auto started = std::chrono::steady_clock::now();
    decal_layer::bake::accounting::Ticket recordTicket;
    const auto clearPending = [&]() noexcept {
        for (auto& owner : groups) {
            if (!owner) continue;
            owner->pendingPlan = {};
            owner->pendingOccurrences = {};
            owner->pendingDefinitionOrder = decltype(owner->pendingDefinitionOrder){};
            owner->pendingTriangleCounts = decltype(owner->pendingTriangleCounts){};
            owner->pendingCornerCounts = decltype(owner->pendingCornerCounts){};
        }
    };
    try {
        if (!groups.front()) return Reason::Unavailable;
        const auto operation = groups.front()->capture.operationView();
        std::size_t recordBytes = sizeof(SavedGroupAllMemberLayoutRecord);
        std::size_t groupBytes = 0;
        std::size_t storageBytes = 0;
        if (!operation.CheckedProduct(groups.size(),
                sizeof(SavedGroupAllMemberLayout), 1U, groupBytes,
                FailureSite::ExportBakeStorage)
            || !AddProtectedBytes(recordBytes, groupBytes)
            || !operation.CheckedProduct(groups.size(),
                sizeof(std::shared_ptr<
                    const painted_atlas_bake::owner::ExportBakeStorage>),
                1U, storageBytes, FailureSite::ExportBakeStorage)
            || !AddProtectedBytes(recordBytes, storageBytes))
            return Reason::Overflow;
        for (const auto& owner : groups) {
            if (!owner) return Reason::Unavailable;
            std::size_t definitionBytes = 0;
            if (!operation.CheckedProduct(owner->measured.size(),
                    sizeof(std::string), 1U, definitionBytes,
                    FailureSite::ExportBakeStorage)
                || !AddProtectedBytes(recordBytes, definitionBytes))
                return Reason::Overflow;
            for (const auto& member : owner->measured)
                if (!AddProtectedBytes(recordBytes,
                        member.definitionIdentifier.capacity() + 1U))
                    return Reason::Overflow;
        }
        if (!recordTicket.acquire(operation, Dimension::PrivateStorage,
                recordBytes, Retention::Retained,
                FailureSite::ExportBakeStorage)) return Reason::Overflow;
        // The same detached member compound and native fine profile used by
        // the final-result oracle. No document authority is remeshed.
        BRep_Builder compoundBuilder;
        TopoDS_Compound compound;
        compoundBuilder.MakeCompound(compound);
        for (const auto& owner : groups) {
            if (!owner || owner->measured.empty()
                || owner->capture.members.members.size()
                    != owner->measured.size()
                || owner->capture.savedAtlas.members.size()
                    != owner->measured.size()) return Reason::Unavailable;
            for (const auto& member : owner->measured)
                compoundBuilder.Add(compound, member.detached);
        }
        if (SavedGroupCancelled(cancelled)
            || !MeshSavedGroupLayoutPrivateSurfaces(compound)
            || SavedGroupCancelled(cancelled)) return Reason::Refused;
        std::uint64_t layoutNanoseconds = 0;
        painted_atlas_bake::owner::AggregateBakePlan aggregate;
        for (auto& owner : groups) {
            if (!owner) {
                clearPending();
                return Reason::Unavailable;
            }
            std::vector<DefinitionData> actualFinalDefinitions;
            actualFinalDefinitions.reserve(owner->measured.size());
            for (std::size_t index = 0;
                 index < owner->measured.size(); ++index) {
                const auto& definitionIdentifier =
                    owner->measured[index].definitionIdentifier;
                // Membership authority is the complete strict saved capture;
                // render aliases can split a member into several scene meshes.
                DefinitionData definition;
                definition.label = owner->capture.members.members[index]
                    .ownerLabel;
                definition.shape = owner->measured[index].detached;
                definition.representation =
                    privateDocument->GeometryRepresentationForLabel(
                        definition.label);
                if (definition.representation
                        == OcctGeometryRepresentation::Invalid
                    || !ExtractDefinitionGeometry(definition.label,
                        definitionIdentifier,
#ifdef DEBUG
                        0,
#endif
                        definition)) {
                    clearPending();
                    return Reason::Unavailable;
                }
                actualFinalDefinitions.push_back(std::move(definition));
            }
            SavedGroupOccurrenceScope occurrences;
            for (std::size_t index = 0;
                 index < wholeCommittedScene.instances.size(); ++index) {
                const auto& instance = wholeCommittedScene.instances[index];
                if (instance.meshIndex >= wholeCommittedScene.meshes.size()
                    || instance.role != RenderRole::Model
                    || (selectedObjectsOnly && !instance.selected)) continue;
                const auto& mesh =
                    wholeCommittedScene.meshes[instance.meshIndex];
                const std::string& definition =
                    mesh.paintedAtlasMasterDefinitionIdentifier.empty()
                    ? mesh.definitionIdentifier
                    : mesh.paintedAtlasMasterDefinitionIdentifier;
                const auto member = std::find_if(owner->measured.begin(),
                    owner->measured.end(), [&](const auto& value) {
                        return value.definitionIdentifier == definition;
                    });
                if (member == owner->measured.end()) continue;
                occurrences.entries.push_back({instance.entityIdentifier,
                    definition, index, instance.worldFromObject});
            }
            std::string diagnosis;
            const auto layoutStarted = std::chrono::steady_clock::now();
            const auto outcome = PrepareSavedGroupForBatch(*owner,
                actualFinalDefinitions, occurrences, cancelled, aggregate,
                diagnosis);
            layoutNanoseconds += std::uint64_t(
                std::chrono::duration_cast<std::chrono::nanoseconds>(
                    std::chrono::steady_clock::now() - layoutStarted).count());
            if (outcome != Outcome::Prepared) {
                clearPending();
                switch (outcome) {
                    case Outcome::OverBudget: return Reason::Overflow;
                    case Outcome::Malformed: return Reason::Malformed;
                    case Outcome::StaleSource: return Reason::StaleSource;
                    case Outcome::StaleBinding: return Reason::StaleBinding;
                    case Outcome::UnsupportedSurface:
                        return Reason::UnsupportedSurface;
                    default: return Reason::Refused;
                }
            }
        }
        // Layout values are complete after admission. This passive record
        // never executes a bake, so it must not seal the shared ledger's jobs
        // (the unchanged transient producer owns those later job seals).

        // The allocator charges the shared_ptr implementation's exact control
        // block to the capture-owned ticket before its allocation enters.
        constexpr std::size_t maximumControlBytes = 4096U;
        if (!controlTicket.acquire(operation, Dimension::PrivateStorage,
                maximumControlBytes, Retention::Retained,
                FailureSite::ExportBakeStorage)
            || !operation.EnterAllocation(FailureSite::ExportBakeStorage)) {
            clearPending();
            controlTicket.reset();
            return Reason::Overflow;
        }
        auto* rawRecord = new SavedGroupAllMemberLayoutRecord();
        std::shared_ptr<SavedGroupAllMemberLayoutRecord> record(rawRecord,
            std::default_delete<SavedGroupAllMemberLayoutRecord>(),
            ProtectedControlAllocator<SavedGroupAllMemberLayoutRecord>(
                operation, controlTicket, FailureSite::ExportBakeStorage));
        record->aggregate = aggregate;
        record->retainedBytes = recordBytes;
        if (!AddProtectedBytes(record->retainedBytes, controlTicket.bytes)) {
            clearPending();
            return Reason::Overflow;
        }
        if (!operation.EnterAllocation(FailureSite::ExportBakeStorage)) {
            clearPending();
            return Reason::Overflow;
        }
        record->groups.reserve(groups.size());
        if (!operation.EnterAllocation(FailureSite::ExportBakeStorage)) {
            clearPending();
            return Reason::Overflow;
        }
        record->planStorage.reserve(groups.size());
        for (auto& owner : groups) {
            SavedGroupAllMemberLayout value;
            value.memberDefinitions =
                std::move(owner->pendingDefinitionOrder);
            value.atlas = std::move(owner->pendingPlan.atlas);
            value.assignments = std::move(owner->pendingPlan.assignments);
            value.layout = std::move(owner->pendingPlan.layout);
            value.work = owner->pendingPlan.work;
            const auto storage = std::move(owner->pendingPlan.storage);
            if (!storage) {
                clearPending();
                return Reason::Unavailable;
            }
            for (const auto bytes : {
                    storage->controlStorage.bytes,
                    storage->bakeValueStorage.bytes,
                    storage->outputVectorStorage.bytes,
                    storage->evidenceStorage.bytes,
                    storage->finalAtlas.layoutStorage.bytes,
                    storage->finalAtlas.resultStorage.bytes})
                if (!AddProtectedBytes(record->retainedBytes, bytes)) {
                    clearPending();
                    return Reason::Overflow;
                }
            record->planStorage.push_back(storage);
            record->groups.push_back(std::move(value));
            owner->pendingPlan = {};
            owner->pendingOccurrences = {};
            owner->pendingTriangleCounts = decltype(owner->pendingTriangleCounts){};
            owner->pendingCornerCounts = decltype(owner->pendingCornerCounts){};
        }
        record->recordStorage = std::move(recordTicket);
        record->layoutNanoseconds = layoutNanoseconds;
        record->preparationNanoseconds = std::uint64_t(
            std::chrono::duration_cast<std::chrono::nanoseconds>(
                std::chrono::steady_clock::now() - started).count());
        output = std::move(record);
        return Reason::Present;
    } catch (const std::bad_alloc&) {
        clearPending();
        controlTicket.reset();
        return Reason::Overflow;
    } catch (...) {
        clearPending();
        controlTicket.reset();
        return Reason::Unavailable;
    }
}

const SavedGroupFinalResult* LookupSavedGroupFinalResult(
    const SavedGroupOwner& group,
    const asset_atlas::Key& strictKey) noexcept {
    return group.result && group.capture.savedAtlas.key == strictKey
        && group.result->bake.atlas.key == strictKey
        ? group.result.get() : nullptr;
}

//! Exact extraction of the pre-P2 ordinary final-assignment boundary.  The
//! ordinary caller supplies one transient member, so this deliberately keeps
//! its one-assignment rule while the complete saved producer exercises the
//! same validation with its real all-member ExportBake.
bool ValidateCurrentFinalAssignments(
    const painted_atlas_bake::owner::ExportBake& baked,
    const std::size_t expectedFinalCorners) noexcept {
    return !baked.outputs.empty() && !baked.atlas.charts.empty()
        && baked.assignments.size() == 1
        && baked.assignments.front().corners.size() == expectedFinalCorners;
}

#ifdef DEBUG
enum class DebugP2bEventKind : std::uint16_t {
    Reserve = 1, Release, Seal, Consume, Settle, Recheck, Cancel,
    Allocation, AllocationFailure, Refuse, LayoutBegin, LayoutEnd,
    BakeBegin, BakeEnd, CheckedProduct
};

struct DebugP2bAccountingEvent final {
    std::uint64_t sequence = 0, operationID = 0, units = 0, bytes = 0;
    std::uint32_t failureSite = 0;
    std::uint16_t kind = 0;
    std::uint8_t job = 0, dimension = 0, retention = 0, decision = 0;
    std::uint8_t groupKey[32]{};
    std::uint8_t reserved[5]{};
};
struct DebugP2bLifetimeEvent final {
    std::uint64_t sequence = 0, operationID = 0, bufferBytes = 0;
    std::uint64_t ticketBytes = 0, liveBytes = 0;
    std::uint8_t groupKey[32]{};
    std::uint8_t owner = 0, kind = 0, reserved[6]{};
};
static_assert(sizeof(DebugP2bAccountingEvent) == 80);
static_assert(sizeof(DebugP2bLifetimeEvent) == 80);

struct DebugP2bAccountingTrace final {
    using Accounting = decal_layer::bake::accounting::View;
    using Dimension = decal_layer::bake::accounting::StorageDimension;
    using Retention = decal_layer::bake::accounting::Retention;
    using Site = decal_layer::bake::accounting::FailureSite;
    using Job = decal_layer::bake::accounting::Job;
    using Settlement = decal_layer::bake::accounting::Settlement;
    using Receiver = decal_layer::bake::accounting::Receiver;
    using Context = decal_layer::bake::accounting::OperationContext;
    Accounting base;
    DebugP2bAccountingEvent* events = nullptr;
    std::uint64_t capacity = 0, count = 0, attempted = 0, operationID = 0;
    std::uint8_t groupKey[32]{};
    void* failureContext = nullptr;
    void (*failure)(void*, std::uint32_t) noexcept = nullptr;
    bool includeAdmissionEvents = false;

    void record(DebugP2bEventKind kind, bool decision, Job job = Job::Count,
        std::uint64_t units = 0, Dimension dimension = Dimension::Count,
        std::uint64_t bytes = 0, Retention retention = Retention::Scratch,
        Site site = Site::None) noexcept {
        const std::uint64_t sequence = attempted++;
        if (!events || count >= capacity) {
            if (failure) failure(failureContext, 18);
            return;
        }
        auto& row = events[count++];
        row.sequence = sequence; row.operationID = operationID;
        row.units = units; row.bytes = bytes;
        row.failureSite = std::uint32_t(site);
        row.kind = std::uint16_t(kind); row.job = std::uint8_t(job);
        row.dimension = std::uint8_t(dimension);
        row.retention = std::uint8_t(retention);
        row.decision = decision ? 1 : 0;
        std::memcpy(row.groupKey, groupKey, sizeof(groupKey));
    }
    Accounting view() noexcept {
        return {this, Reserve, Release, CheckedProduct, Seal, Consume,
            Recheck, Cancel, EnterAllocation, AllocationFailure, Settle,
            Refuse};
    }
    static bool Reserve(void* value, Dimension dimension, std::size_t bytes,
        Retention retention, Site site) noexcept {
        auto& self = *static_cast<DebugP2bAccountingTrace*>(value);
        const bool result = self.base.Reserve(dimension, bytes, retention, site);
        self.record(DebugP2bEventKind::Reserve, result, Job::Count, 0,
            dimension, bytes, retention, site);
        return result;
    }
    static void Release(void* value, Dimension dimension, std::size_t bytes,
        Retention retention) noexcept {
        auto& self = *static_cast<DebugP2bAccountingTrace*>(value);
        self.base.Release(dimension, bytes, retention);
        self.record(DebugP2bEventKind::Release, true, Job::Count, 0,
            dimension, bytes, retention, Site::StorageRelease);
    }
    static bool CheckedProduct(void* value, std::size_t first,
        std::size_t second, std::size_t third, std::size_t& product,
        Site site) noexcept {
        auto& self = *static_cast<DebugP2bAccountingTrace*>(value);
        const bool result = self.base.CheckedProduct(
            first, second, third, product, site);
        if (self.includeAdmissionEvents)
            self.record(DebugP2bEventKind::CheckedProduct, result,
                Job(std::min<std::size_t>(third, std::uint8_t(-1))), first,
                Dimension::Count, second, Retention::Scratch, site);
        return result;
    }
    static bool Seal(void* value, Job job, std::size_t units,
        Site site) noexcept {
        auto& self = *static_cast<DebugP2bAccountingTrace*>(value);
        const bool result = self.base.SealJob(job, units, site);
        self.record(DebugP2bEventKind::Seal, result, job, units,
            Dimension::Count, 0, Retention::Scratch, site);
        return result;
    }
    static bool Consume(void* value, Job job, std::size_t units,
        Site site) noexcept {
        auto& self = *static_cast<DebugP2bAccountingTrace*>(value);
        const bool result = self.base.ConsumeJob(job, units, site);
        self.record(DebugP2bEventKind::Consume, result, job, units,
            Dimension::Count, 0, Retention::Scratch, site);
        return result;
    }
    static bool Recheck(void* value, Site site) noexcept {
        auto& self = *static_cast<DebugP2bAccountingTrace*>(value);
        const bool result = self.base.Recheck(site);
        self.record(DebugP2bEventKind::Recheck, result, Job::Count, 0,
            Dimension::Count, 0, Retention::Scratch, site);
        return result;
    }
    static void Cancel(void* value, Site site) noexcept {
        auto& self = *static_cast<DebugP2bAccountingTrace*>(value);
        self.base.Cancel(site);
        self.record(DebugP2bEventKind::Cancel, false, Job::Count, 0,
            Dimension::Count, 0, Retention::Scratch, site);
    }
    static bool EnterAllocation(void* value, Site site) noexcept {
        auto& self = *static_cast<DebugP2bAccountingTrace*>(value);
        const bool result = self.base.EnterAllocation(site);
        self.record(DebugP2bEventKind::Allocation, result, Job::Count, 0,
            Dimension::Count, 0, Retention::Scratch, site);
        return result;
    }
    static void AllocationFailure(void* value, Site site) noexcept {
        auto& self = *static_cast<DebugP2bAccountingTrace*>(value);
        self.base.AllocationFailed(site);
        self.record(DebugP2bEventKind::AllocationFailure, false, Job::Count,
            0, Dimension::Count, 0, Retention::Scratch, site);
    }
    static void Settle(void* value, Dimension dimension, std::size_t bytes,
        Settlement settlement, Receiver receiver, Context context,
        Site site) noexcept {
        auto& self = *static_cast<DebugP2bAccountingTrace*>(value);
        self.base.Settle(dimension, bytes, settlement, receiver, context, site);
        self.record(DebugP2bEventKind::Settle, true,
            self.includeAdmissionEvents ? Job(context) : Job::Count,
            std::uint64_t(receiver), dimension, bytes,
            settlement == Settlement::Transfer
                ? Retention::Retained : Retention::Scratch, site);
    }
    static void Refuse(void* value, Site site) noexcept {
        auto& self = *static_cast<DebugP2bAccountingTrace*>(value);
        self.base.Refuse(site);
        self.record(DebugP2bEventKind::Refuse, false, Job::Count, 0,
            Dimension::Count, 0, Retention::Scratch, site);
    }
};

constexpr std::uint64_t kDebugP2bGroupCount = 2;
constexpr std::uint64_t kDebugP2bSlotBytes = 18'201'984;
constexpr std::uint64_t kDebugP2bNativeBytes = 36'408'064;
constexpr std::uint64_t kDebugP2bWireBytes = 388'729'600;
constexpr std::uint64_t kDebugP2bUsedBytes = 425'137'664;
