void DebugP2bEncodeP6Group(DebugP2bP6Writer& output,
    const std::size_t slot, const SavedGroupOwner& group,
    const SavedGroupFinalResult& result) noexcept {
    const auto& sources = group.capture.sources.values;
    const painted_atlas_bake::owner::CapturedSource* first = nullptr;
    const painted_atlas_bake::owner::CapturedSource* second = nullptr;
    if (slot == 0) {
        for (std::size_t left = 0; left < sources.size() && !second; ++left)
            for (std::size_t right = left + 1; right < sources.size(); ++right)
                if (!(sources[left].fence == sources[right].fence)) {
                    first = &sources[left]; second = &sources[right]; break;
                }
        if (!first || !second) { output.valid = false; return; }
    }
    static constexpr std::array<std::uint8_t, 8> magic{
        'S', 'Y', 'P', '2', 'B', 'P', '6', 0};
    output.fixed(magic); output.scalar(std::uint16_t(1));
    output.scalar(std::uint16_t(slot == 0 ? 12 : 11));
    const auto section = [&](const std::uint16_t identifier,
            const auto& encode) noexcept {
        DebugP2bP6Writer measure;
        encode(measure);
        if (!measure.valid) { output.valid = false; return; }
        output.scalar(identifier); output.scalar(measure.cursor);
        encode(output);
    };
    section(1, [&](DebugP2bP6Writer& out) noexcept {
        out.count(result.bake.atlas.resources.size());
        for (const auto& value : result.bake.atlas.resources) {
            out.fixed(value.identity); out.fixed(value.content);
        }
    });
    section(2, [&](DebugP2bP6Writer& out) noexcept {
        out.count(result.bake.outputs.size());
        for (const auto& value : result.bake.outputs) {
            DebugP2bP6BakedResource(out, value.descriptor);
            out.vector(value.png);
        }
    });
    section(3, [&](DebugP2bP6Writer& out) noexcept {
        out.fixed(result.bake.bake.layoutProof);
    });
    section(4, [&](DebugP2bP6Writer& out) noexcept {
        out.count(result.bake.bake.resources.size());
        for (const auto& value : result.bake.bake.resources)
            DebugP2bP6BakedResource(out, value);
    });
    section(5, [&](DebugP2bP6Writer& out) noexcept {
        out.count(result.bake.bake.bindings.size());
        for (const auto& value : result.bake.bake.bindings)
            DebugP2bP6Fence(out, value);
    });
    section(6, [&](DebugP2bP6Writer& out) noexcept {
        out.count(group.capture.sources.rawSlots.size());
        for (const auto& value : group.capture.sources.rawSlots)
            DebugP2bP6RawSlot(out, value);
    });
    section(7, [&](DebugP2bP6Writer& out) noexcept {
        out.count(group.capture.sources.values.size());
        for (const auto& value : group.capture.sources.values)
            DebugP2bP6Source(out, value);
    });
    section(8, [&](DebugP2bP6Writer& out) noexcept {
        out.count(group.productionSources.values.size());
        for (const auto& value : group.productionSources.values)
            DebugP2bP6Source(out, value);
    });
    section(9, [&](DebugP2bP6Writer& out) noexcept {
        out.vector(group.capture.canonicalAtlasBytes);
    });
    section(10, [&](DebugP2bP6Writer& out) noexcept {
        out.vector(group.capture.canonicalBakeBytes);
    });
    section(11, [&](DebugP2bP6Writer& out) noexcept {
        out.count(group.capture.sources.canonicalBindings.size());
        for (const auto& value : group.capture.sources.canonicalBindings) {
            DebugP2bP6Owner(out, value.owner); out.vector(value.bytes);
        }
    });
    if (slot == 0) section(12, [&](DebugP2bP6Writer& out) noexcept {
        DebugP2bP6Source(out, *first); DebugP2bP6Source(out, *second);
    });
}

class DebugP2bObservationArena final {
public:
    DebugP2bObservationArena() noexcept {
        if (!DebugP2bValidateLayout()) {
            failureCode_ = 4;
            return;
        }
        const long pageSize = sysconf(_SC_PAGESIZE);
        if (pageSize <= 0
            || std::uint64_t(pageSize) > kDebugP2bMappingAlignment
            || kDebugP2bMappingAlignment % std::uint64_t(pageSize) != 0) {
            failureCode_ = 1;
            return;
        }
        if (!account_.reserve(kDebugP2bArenaBytes)) {
            failureCode_ = 2;
            return;
        }
        mapping_ = mmap(nullptr, std::size_t(kDebugP2bArenaBytes),
            PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
        if (mapping_ == MAP_FAILED) {
            mapping_ = nullptr;
            failureCode_ = 3;
            account_.release();
            return;
        }
        gDebugP2bActiveMappings.fetch_add(1, std::memory_order_relaxed);
        gDebugP2bTotalMappings.fetch_add(1, std::memory_order_relaxed);
        new (mapping_) DebugP2bMappedControl();
    }
    DebugP2bObservationArena(const DebugP2bObservationArena&) = delete;
    DebugP2bObservationArena& operator=(
        const DebugP2bObservationArena&) = delete;
    ~DebugP2bObservationArena() { close(); }
    void retain() noexcept { references_.fetch_add(1, std::memory_order_relaxed); }
    void release() noexcept {
        if (references_.fetch_sub(1, std::memory_order_acq_rel) == 1)
            delete this;
    }
    std::uint64_t leaseCount() const noexcept {
        return references_.load(std::memory_order_acquire);
    }
    bool valid() const noexcept { return mapping_ != nullptr; }
    std::uint32_t failureCode() const noexcept { return failureCode_; }
    decal_layer::bake::accounting::View accountingView(
        const decal_layer::bake::accounting::View& base,
        const std::uint64_t operationID) noexcept {
        if (!mapping_ || !base.valid() || trace_.events) {
            fail(18); return base;
        }
        trace_.events = static_cast<DebugP2bAccountingEvent*>(stage(
            4096 * sizeof(DebugP2bAccountingEvent)));
        lifetimeEvents_ = static_cast<DebugP2bLifetimeEvent*>(stage(
            16 * sizeof(DebugP2bLifetimeEvent)));
        if (!trace_.events || !lifetimeEvents_) return base;
        trace_.base = base; trace_.capacity = 4096;
        trace_.operationID = operationID;
        trace_.failureContext = this;
        trace_.failure = [](void* value, std::uint32_t reason) noexcept {
            static_cast<DebugP2bObservationArena*>(value)->fail(reason);
        };
        return trace_.view();
    }
    void accountingGroup(const asset_atlas::Key* key) noexcept {
        std::memset(trace_.groupKey, 0, sizeof(trace_.groupKey));
        if (key) {
            std::memcpy(trace_.groupKey, key->document.data(), 16);
            std::memcpy(trace_.groupKey + 16, key->atlas.data(), 16);
        }
    }
    void boundary(const DebugP2bEventKind kind, const bool decision) noexcept {
        trace_.record(kind, decision);
    }
    void lifetime(const std::uint8_t owner, const std::uint8_t kind,
        const std::uint64_t bufferBytes, const std::uint64_t ticketBytes,
        const std::uint64_t liveBytes) noexcept {
        if (!lifetimeEvents_ || lifetimeCount_ >= 16) { fail(18); return; }
        auto& row = lifetimeEvents_[lifetimeCount_++];
        row.sequence = trace_.attempted + lifetimeCount_ - 1;
        row.operationID = trace_.operationID;
        row.bufferBytes = bufferBytes; row.ticketBytes = ticketBytes;
        row.liveBytes = liveBytes; row.owner = owner; row.kind = kind;
        std::memcpy(row.groupKey, trace_.groupKey,
            sizeof(row.groupKey));
    }
    const asset_atlas::build::DebugLayoutObserver* layoutObserver(
        const std::size_t slot, const asset_atlas::Key& key) noexcept {
        if (!mapping_ || slot >= contexts_.size()) {
            fail(10);
            return nullptr;
        }
        auto& context = contexts_[slot];
        auto& bakeContext = bakeContexts_[slot];
        if (context.directory && context.directory->states[0] != 0) {
            fail(11);
            return nullptr;
        }
        std::uint8_t* cursor = static_cast<std::uint8_t*>(mapping_) + 4096
            + slot * std::size_t(kDebugP2bSlotBytes);
        const auto take = [&](const std::uint64_t count,
                const std::uint64_t stride) noexcept {
            std::uint8_t* result = cursor;
            std::uint64_t bytes = 0;
            std::uint64_t aligned = 0;
            if (!DebugP2bCheckedProduct(count, stride, bytes)
                || !DebugP2bCheckedAlign64(bytes, aligned)) {
                fail(12);
                return static_cast<std::uint8_t*>(nullptr);
            }
            cursor += std::size_t(aligned);
            return result;
        };
        context.directory = reinterpret_cast<DebugP2bGroupDirectory*>(
            take(1, sizeof(DebugP2bGroupDirectory)));
        context.memberOffsets = reinterpret_cast<std::uint64_t*>(
            take(9, sizeof(std::uint64_t)));
        context.chartOffsets = reinterpret_cast<std::uint64_t*>(
            take(65, sizeof(std::uint64_t)));
        context.finalTriangleMap = reinterpret_cast<std::int32_t*>(
            take(174'762, sizeof(std::int32_t)));
        context.lineage = reinterpret_cast<DebugP2bEmittedTriangleLineage*>(
            take(174'762, sizeof(DebugP2bEmittedTriangleLineage)));
        context.adjacency = reinterpret_cast<DebugP2bAdjacency*>(
            take(262'143, sizeof(DebugP2bAdjacency)));
        context.islands = reinterpret_cast<DebugP2bPackedIslandRecord*>(
            take(512, sizeof(DebugP2bPackedIslandRecord)));
        bakeContext.samples = reinterpret_cast<DebugP2bSampleExtra*>(
            take(12, sizeof(DebugP2bSampleExtra)));
        bakeContext.normal = reinterpret_cast<DebugP2bNormalDomainHeader*>(
            take(1, sizeof(DebugP2bNormalDomainHeader)));
        bakeContext.normalMask = reinterpret_cast<std::uint8_t*>(
            take(2'097'152, sizeof(std::uint8_t)));
        const std::uint8_t* expected = static_cast<std::uint8_t*>(mapping_)
            + 4096 + (slot + 1) * std::size_t(kDebugP2bSlotBytes);
        if (!context.directory || !context.memberOffsets
            || !context.chartOffsets || !context.finalTriangleMap
            || !context.lineage || !context.adjacency || !context.islands
            || !bakeContext.samples || !bakeContext.normal
            || !bakeContext.normalMask
            || cursor != expected) {
            fail(12);
            return nullptr;
        }
        std::memcpy(context.directory->key, key.document.data(), 16);
        std::memcpy(context.directory->key + 2, key.atlas.data(), 16);
        context.directory->states[0] = 1;
        context.failureContext = this;
        context.failure = [](void* opaque, const std::uint32_t reason) noexcept {
            static_cast<DebugP2bObservationArena*>(opaque)->fail(reason);
        };
        bakeContext.directory = context.directory;
        bakeContext.failureContext = this;
        bakeContext.failure = [](void* opaque,
                const std::uint32_t reason) noexcept {
            static_cast<DebugP2bObservationArena*>(opaque)->fail(reason);
        };
        observers_[slot] = {&context, DebugP2bLineageCallback,
            DebugP2bIslandCallback, DebugP2bFinishLayoutCallback};
        bakeObservers_[slot] = {&bakeContext, DebugP2bBeginRoleCallback,
            DebugP2bQuantizedCallback, DebugP2bSampleCallback,
            DebugP2bFinishRoleCallback};
        return &observers_[slot];
    }
    const painted_atlas_bake::kernel::DebugBakeObserver* bakeObserver(
        const std::size_t slot) noexcept {
        if (!mapping_ || slot >= bakeContexts_.size()
            || !bakeContexts_[slot].directory) {
            fail(10);
            return nullptr;
        }
        return &bakeObservers_[slot];
    }
    void commitS2(const std::size_t slot) noexcept {
        if (!mapping_ || slot >= bakeContexts_.size()) {
            fail(10);
            return;
        }
        auto& context = bakeContexts_[slot];
        if (!context.directory || context.directory->states[7] != 0) return;
        if (context.normal && context.normal->available != 0) {
            if (context.normal->complete == 0
                || context.normal->sampleCount == 0) {
                DebugP2bBakeFailure(context, 13);
                return;
            }
        } else {
            context.directory->states[5] = 1;
        }
        context.directory->states[4] = 1;
    }
    void retainOccurrence(const std::size_t groupIndex,
        const std::size_t sourceInstanceIndex, const Matrix4d& world,
        const Matrix4d& object, const Matrix4d& explorer,
        const Matrix4d& origin) noexcept {
        DebugP2bP5OccurrenceRow row;
        row.groupIndex = groupIndex;
        row.sourceInstanceIndex = sourceInstanceIndex;
        std::copy(world.values.begin(), world.values.end(), row.worldFromObject);
        std::copy(object.values.begin(), object.values.end(), row.objectTransform);
        std::copy(explorer.values.begin(), explorer.values.end(), row.explorerTransform);
        std::copy(origin.values.begin(), origin.values.end(), row.meshOriginTransform);
        char key[64]{};
        std::snprintf(key, sizeof(key), "p5.occurrences.%zu", occurrenceCount_++);
        addP5Spec(key, 2, 1, sizeof(row), &row);
    }
    void retainSelectedOccurrences(
        const std::vector<std::string>& identifiers) noexcept {
        std::uint64_t bytes = 0;
        for (const auto& value : identifiers)
            if (!DebugP2bCheckedAdd(bytes, value.size() + 1, bytes)) {
                fail(14); return;
            }
        auto* target = static_cast<char*>(stage(bytes));
        if (bytes != 0 && !target) return;
        std::uint64_t cursor = 0;
        for (const auto& value : identifiers) {
            std::memcpy(target + cursor, value.c_str(), value.size() + 1);
            cursor += value.size() + 1;
        }
        addP5Spec("p5.selectedOccurrenceIdentifiers", 1, 1, bytes,
            target, true);
    }
    void retainP5Group(const std::size_t slot,
        const SavedGroupOwner& group,
        const std::vector<DefinitionData>& definitions,
        const SavedGroupFinalResult& result) noexcept {
        if (slot >= 2 || definitions.size() != group.measured.size()
            || result.bake.atlas.members.size() != group.measured.size()
            || !result.bake.storage) { fail(16); return; }
        char key[64]{};
        const auto addNamed = [&](const char* suffix, std::uint16_t kind,
                std::uint16_t width, std::uint64_t count,
                const void* bytes) noexcept {
            std::snprintf(key, sizeof(key), "p5.%zu.%s", slot, suffix);
            addP5Spec(key, kind, width, count, bytes);
        };
        std::uint64_t summary[16]{};
        std::memcpy(summary, result.bake.atlas.key.document.data(), 16);
        std::memcpy(summary + 2, result.bake.atlas.key.atlas.data(), 16);
        summary[4] = std::uint32_t(group.capture.savedAtlas.resolutionTexels)
            | std::uint64_t(std::uint32_t(group.capture.savedAtlas.gutterTexels)) << 32;
        summary[5] = std::uint32_t(result.bake.atlas.resolutionTexels)
            | std::uint64_t(std::uint32_t(result.bake.atlas.gutterTexels)) << 32;
        std::memcpy(summary + 6, &result.bake.atlas.globalTexelsPerMM, 8);
        std::memcpy(summary + 7, result.bake.atlas.layoutProof.data(), 32);
        summary[11] = result.bake.atlas.members.size();
        summary[12] = result.bake.atlas.charts.size();
        summary[13] = result.bake.assignments.size();
        summary[14] = result.bake.storage->layout.charts.size();
        summary[15] = result.bake.storage->layout.packed.triangles.size();
        addNamed("group", 6, 128, 1, summary);
        addNamed("savedMembers", 2, 1,
            group.capture.savedAtlas.members.size() * sizeof(asset_atlas::Member),
            group.capture.savedAtlas.members.data());
        addNamed("finalMembers", 2, 1,
            result.bake.atlas.members.size() * sizeof(asset_atlas::Member),
            result.bake.atlas.members.data());
        addNamed("charts", 2, 1,
            result.bake.atlas.charts.size() * sizeof(asset_atlas::Chart),
            result.bake.atlas.charts.data());

        auto* assignments = static_cast<DebugP2bP5AssignmentRow*>(stage(
            result.bake.assignments.size() * sizeof(DebugP2bP5AssignmentRow)));
        std::uint64_t cornerCount = 0;
        for (std::size_t i = 0; i < result.bake.assignments.size(); ++i) {
            const auto& source = result.bake.assignments[i];
            std::memcpy(assignments[i].member, source.member.data(), 16);
            assignments[i].triangleCount = source.triangleCount;
            assignments[i].cornerOffset = cornerCount;
            cornerCount += source.corners.size();
        }
        addNamed("assignments", 6, 32, result.bake.assignments.size(), assignments);
        auto* corners = static_cast<std::array<double, 2>*>(stage(
            cornerCount * sizeof(std::array<double, 2>)));
        std::uint64_t cornerCursor = 0;
        for (const auto& assignment : result.bake.assignments) {
            std::copy(assignment.corners.begin(), assignment.corners.end(),
                corners + cornerCursor);
            cornerCursor += assignment.corners.size();
        }
        addNamed("assignmentCorners", 2, 1,
            cornerCount * sizeof(std::array<double, 2>), corners);

        const auto& layout = result.bake.storage->layout;
        if (layout.chartMembers.size() != layout.charts.size()
            || layout.chartFaces.size() != layout.charts.size()) { fail(16); return; }
        auto* layoutRows = static_cast<DebugP2bP5LayoutChartRow*>(stage(
            layout.charts.size() * sizeof(DebugP2bP5LayoutChartRow)));
        std::uint64_t developedCount = 0;
        for (std::size_t i = 0; i < layout.charts.size(); ++i) {
            const auto& source = layout.charts[i];
            auto& row = layoutRows[i];
            row.faceID = source.faceId; row.kernel = std::int32_t(source.kernel);
            row.memberIndex = layout.chartMembers[i].first;
            row.memberChartOrdinal = layout.chartMembers[i].second;
            row.memberFaceIndex = layout.chartFaces[i];
            row.rectMin[0] = source.rectMin.x; row.rectMin[1] = source.rectMin.y;
            row.rectMax[0] = source.rectMax.x; row.rectMax[1] = source.rectMax.y;
            row.triangleOffset = developedCount;
            row.triangleCount = source.triangles.size();
            developedCount += source.triangles.size();
        }
        addNamed("layoutCharts", 6, 80, layout.charts.size(), layoutRows);
        auto* developed = static_cast<curveduv::ChartTriangle*>(stage(
            developedCount * sizeof(curveduv::ChartTriangle)));
        std::uint64_t developedCursor = 0;
        for (const auto& chart : layout.charts) {
            std::copy(chart.triangles.begin(), chart.triangles.end(),
                developed + developedCursor);
            developedCursor += chart.triangles.size();
        }
        addNamed("developedTriangles", 6, 48, developedCount, developed);
        addNamed("packedTriangles", 2, 1,
            layout.packed.triangles.size() * sizeof(curveduv::TriangleUV),
            layout.packed.triangles.data());

        std::uint64_t vertexCount = 0, indexCount = 0, tangentCount = 0;
        std::uint64_t primitiveCount = 0, parameterCount = 0, faceCount = 0;
        for (const auto& definition : definitions) {
            vertexCount += definition.mesh.vertices.size();
            indexCount += definition.mesh.indices.size();
            tangentCount += definition.mesh.cornerTangents.size();
            primitiveCount += definition.mesh.primitives.size();
            faceCount += definition.faces.Extent();
            for (const auto& primitive : definition.mesh.primitives)
                parameterCount += primitive.analyticSourceFace.params.size();
        }
        // Original analytic parameters are appended after final parameters.
        parameterCount += faceCount * 11;
        auto* meshRows = static_cast<DebugP2bP5MeshRow*>(stage(
            definitions.size() * sizeof(DebugP2bP5MeshRow)));
        auto* vertices = static_cast<Vertex*>(stage(vertexCount * sizeof(Vertex)));
        auto* indices = static_cast<std::uint32_t*>(stage(
            indexCount * sizeof(std::uint32_t)));
        auto* tangents = static_cast<Float4*>(stage(tangentCount * sizeof(Float4)));
        auto* primitives = static_cast<DebugP2bP5PrimitiveRow*>(stage(
            primitiveCount * sizeof(DebugP2bP5PrimitiveRow)));
        auto* parameters = static_cast<double*>(stage(parameterCount * sizeof(double)));
        auto* lineage = static_cast<DebugP2bP5FaceLineageRow*>(stage(
            faceCount * sizeof(DebugP2bP5FaceLineageRow)));
        if ((vertexCount && !vertices) || (indexCount && !indices)
            || (primitiveCount && !primitives) || (faceCount && !lineage)) return;
        std::uint64_t vo = 0, io = 0, to = 0, po = 0, ao = 0, fo = 0;
        for (std::size_t member = 0; member < definitions.size(); ++member) {
            const auto& definition = definitions[member];
            auto& mesh = meshRows[member];
            mesh.vertexOffset = vo; mesh.vertexCount = definition.mesh.vertices.size();
            mesh.indexOffset = io; mesh.indexCount = definition.mesh.indices.size();
            mesh.tangentOffset = to; mesh.tangentCount = definition.mesh.cornerTangents.size();
            mesh.primitiveOffset = po; mesh.primitiveCount = definition.mesh.primitives.size();
            mesh.geometryRevision = definition.mesh.geometryRevision;
            mesh.tangentBasis = std::uint64_t(definition.mesh.tangentBasis);
            mesh.sourceOrigin[0] = definition.sourceOrigin.x;
            mesh.sourceOrigin[1] = definition.sourceOrigin.y;
            mesh.sourceOrigin[2] = definition.sourceOrigin.z;
            std::copy(definition.mesh.vertices.begin(), definition.mesh.vertices.end(), vertices + vo);
            std::copy(definition.mesh.indices.begin(), definition.mesh.indices.end(), indices + io);
            std::copy(definition.mesh.cornerTangents.begin(), definition.mesh.cornerTangents.end(), tangents + to);
            vo += mesh.vertexCount; io += mesh.indexCount; to += mesh.tangentCount;
            for (const auto& source : definition.mesh.primitives) {
                auto& row = primitives[po++];
                row.firstIndex = source.firstIndex; row.indexCount = source.indexCount;
                row.faceIndex = source.faceIndex;
                row.flags = (source.hasTextureCoordinates ? 1U : 0U)
                    | (source.analyticSourceFace.available ? 2U : 0U)
                    | (source.analyticSourceFace.reversed ? 4U : 0U);
                row.surfaceType = source.analyticSourceFace.surfaceType;
                row.parameterOffset = ao;
                row.parameterCount = std::uint32_t(source.analyticSourceFace.params.size());
                std::memcpy(row.digest, source.analyticSourceFace.digest.data(),
                    std::min<std::size_t>(64, source.analyticSourceFace.digest.size()));
                std::copy(source.analyticSourceFace.params.begin(),
                    source.analyticSourceFace.params.end(), parameters + ao);
                ao += source.analyticSourceFace.params.size();
            }
            for (Standard_Integer original = 1;
                 original <= group.measured[member].originalFaces.Extent(); ++original) {
                const TopoDS_Face originalFace = TopoDS::Face(
                    group.measured[member].originalFaces.FindKey(original));
                const TopoDS_Shape copied = group.measured[member].copier->ModifiedShape(originalFace);
                const Standard_Integer copiedIndex = group.measured[member].detachedFaces.FindIndex(copied);
                std::size_t primitiveIndex = definition.mesh.primitives.size();
                for (std::size_t candidate = 0; candidate < definition.mesh.primitives.size(); ++candidate)
                    if (definition.mesh.primitives[candidate].faceIndex == std::uint32_t(copiedIndex - 1)) {
                        primitiveIndex = candidate; break;
                    }
                AnalyticSourceFaceWitness witness;
                if (copiedIndex <= 0 || primitiveIndex == definition.mesh.primitives.size()
                    || !CaptureAnalyticSourceFaceWitness(originalFace,
                        definition.mesh.primitives[primitiveIndex].firstIndex,
                        definition.mesh.primitives[primitiveIndex].indexCount,
                        witness) || !witness.available) { fail(16); return; }
                auto& row = lineage[fo++];
                row.memberIndex = std::uint32_t(member);
                row.originalFaceIndex = std::uint32_t(original - 1);
                row.copiedFaceIndex = std::uint32_t(copiedIndex - 1);
                row.finalPrimitiveIndex = std::uint32_t(primitiveIndex);
                row.surfaceType = witness.surfaceType;
                row.flags = 1U | (witness.reversed ? 2U : 0U);
                row.parameterOffset = ao;
                row.parameterCount = std::uint32_t(witness.params.size());
                std::memcpy(row.digest, witness.digest.data(), 64);
                std::copy(witness.params.begin(), witness.params.end(), parameters + ao);
                ao += witness.params.size();
            }
        }
        addNamed("meshes", 6, 128, definitions.size(), meshRows);
        addNamed("vertices", 6, 32, vertexCount, vertices);
        addNamed("indices", 4, 4, indexCount, indices);
        addNamed("cornerTangents", 2, 1, tangentCount * sizeof(Float4), tangents);
        addNamed("primitives", 6, 128, primitiveCount, primitives);
        addNamed("analyticParameters", 5, 8, ao, parameters);
        addNamed("faceLineage", 6, 128, faceCount, lineage);
    }
    void retainP6Group(const std::size_t slot,
        const SavedGroupOwner& group,
        const SavedGroupFinalResult& result) noexcept {
        if (slot >= 2 || !result.bake.storage) { fail(17); return; }
        DebugP2bP6Writer measure;
        DebugP2bEncodeP6Group(measure, slot, group, result);
        if (!measure.valid || measure.cursor == 0) { fail(17); return; }
        auto* retained = static_cast<std::uint8_t*>(stage(measure.cursor));
        if (!retained) return;
        DebugP2bP6Writer writer{retained, measure.cursor};
        DebugP2bEncodeP6Group(writer, slot, group, result);
        if (!writer.valid || writer.cursor != measure.cursor) {
            fail(17); return;
        }
        char key[64]{};
        std::snprintf(key, sizeof(key), "p6.%zu.raw", slot);
        addP5Spec(key, 2, 1, writer.cursor, retained, true);
    }
    void retainP8SingleGroup() noexcept {
        const auto* directory = contexts_[0].directory;
        if (!directory || contexts_[1].directory
            || directory->states[1] == 0 || directory->states[4] == 0
            || directory->states[7] != 0) { fail(18); return; }
        p8Ready_ = true;
    }
    void retainP7(const OperationLedger& operation,
        const painted_atlas_bake::owner::AggregateBakePlan& aggregate,
        const std::array<SavedGroupOwner, 2>& groups) noexcept {
        using Dimension = decal_layer::bake::accounting::StorageDimension;
        using Job = decal_layer::bake::accounting::Job;
        using Site = decal_layer::bake::accounting::FailureSite;
        static constexpr char magic[8] = {'S','Y','P','2','B','P','7',0};
        static constexpr char inventorySHA[] =
            "1f90d433567f688af08ea653ae9251924ad9590ecd40d713a742a45be4b9301d";
        const auto settlement = operation.debugSettlementObservation();
        const auto encode = [&](DebugP2bP6Writer& out) noexcept {
            out.bytes(magic, sizeof(magic));
            out.scalar(std::uint64_t(1));
            out.scalar(std::uint64_t(488));
            out.bytes(inventorySHA, sizeof(inventorySHA) - 1);
            out.scalar(trace_.operationID);
            out.scalar(trace_.count); out.scalar(lifetimeCount_);
            out.scalar(std::uint64_t(Dimension::Count));
            out.scalar(std::uint64_t(Job::Count));
            out.scalar(std::uint64_t(Site::Count));
            out.scalar(std::uint64_t(groups.size()));
            out.scalar(std::uint64_t(aggregate.admittedWork.atlasRoles));
            out.scalar(std::uint64_t(aggregate.admittedWork.sourcePixels));
            out.scalar(std::uint64_t(aggregate.admittedWork.maskPixels));
            out.scalar(std::uint64_t(aggregate.admittedWork.gutter));
            out.scalar(std::uint64_t(aggregate.admittedWork.encoder));
            out.scalar(std::uint64_t(aggregate.admittedItems));
            out.scalar(std::uint64_t(aggregate.sealed));
            out.scalar(std::uint64_t(operation.debugCumulativeAdmittedWork()));
            out.scalar(std::uint64_t(operation.cumulativeWork()));
            out.scalar(std::uint64_t(operation.firstFailureSite()));
            out.scalar(std::uint64_t(settlement.faceImageTransfers));
            out.scalar(std::uint64_t(settlement.paintedBakeTransfers));
            out.scalar(std::uint64_t(settlement.destructions));
            out.scalar(std::uint64_t(settlement.faceImageBytes));
            out.scalar(std::uint64_t(settlement.paintedBakeBytes));
            out.scalar(std::uint64_t(settlement.destroyedBytes));
            out.scalar(std::uint64_t(settlement.finalLiveBytes));
            out.scalar(std::uint64_t(settlement.overflow));
            for (const auto& group : groups) {
                out.bytes(group.capture.savedAtlas.key.document.data(), 16);
                out.bytes(group.capture.savedAtlas.key.atlas.data(), 16);
                out.scalar(std::uint64_t(group.pendingPlan.admitted));
                out.scalar(std::uint64_t(group.pendingPlan.executed));
                out.scalar(std::uint64_t(group.pendingPlan.work.atlasRoles));
                out.scalar(std::uint64_t(group.pendingPlan.work.sourcePixels));
                out.scalar(std::uint64_t(group.pendingPlan.work.maskPixels));
                out.scalar(std::uint64_t(group.pendingPlan.work.gutter));
                out.scalar(std::uint64_t(group.pendingPlan.work.encoder));
            }
            for (std::size_t index = 0;
                 index < std::size_t(Dimension::Count); ++index) {
                const auto state = operation.debugStorageState(
                    Dimension(index));
                for (const auto value : state)
                    out.scalar(std::uint64_t(value));
            }
            for (std::size_t index = 0;
                 index < std::size_t(Job::Count); ++index) {
                const auto state = operation.debugJobState(Job(index));
                for (const auto value : state)
                    out.scalar(std::uint64_t(value));
            }
            for (std::size_t index = 0;
                 index < std::size_t(Site::Count); ++index)
                out.scalar(std::uint64_t(operation.allocationEntries(
                    Site(index))));
            out.bytes(trace_.events,
                trace_.count * sizeof(DebugP2bAccountingEvent));
            out.bytes(lifetimeEvents_,
                lifetimeCount_ * sizeof(DebugP2bLifetimeEvent));
        };
        DebugP2bP6Writer measure; encode(measure);
        if (!measure.valid || measure.cursor == 0 || trace_.count == 0
            || trace_.count != trace_.attempted || lifetimeCount_ < 5
            || !aggregate.sealed || aggregate.admittedItems != groups.size()
            || std::any_of(groups.begin(), groups.end(), [](const auto& value) {
                return !value.pendingPlan.admitted
                    || !value.pendingPlan.executed;
            })) { fail(18); return; }
        auto* bytes = static_cast<std::uint8_t*>(stage(measure.cursor));
        if (!bytes) return;
        DebugP2bP6Writer writer{bytes, measure.cursor}; encode(writer);
        if (!writer.valid || writer.cursor != measure.cursor) {
            fail(18); return;
        }
        addP5Spec("p7.raw", 2, 1, writer.cursor, bytes, true);
        p7Ready_ = true;
    }
    NSData* serialize(const double metersPerUnit) noexcept {
        if (!mapping_ || wireLength_ != 0 || !std::isfinite(metersPerUnit)
            || !(metersPerUnit > 0)) {
            fail(14);
            return nil;
        }
        struct Spec final {
            const char* key;
            std::uint16_t kind;
            std::uint16_t width;
            std::uint64_t count;
            const void* bytes;
            std::uint64_t flags;
        };
        std::array<Spec, 64> specs{};
        std::size_t next = 0;
        const auto add = [&](const char* key, const std::uint16_t kind,
                const std::uint16_t width, const std::uint64_t count,
                const void* bytes, const std::uint64_t flags = 0) noexcept {
            if (next >= specs.size()) {
                fail(14);
                return;
            }
            specs[next++] = {key, kind, width, count, bytes, flags};
        };
        static constexpr char schema[] = "shapeyard.p2b-observation.v1";
        static constexpr char stage[] =
            "saved-batch-before-current-validation";
        const bool batchComplete = p7Ready_ && occurrenceCount_ == 3
            && std::all_of(contexts_.begin(), contexts_.end(),
                [](const auto& value) {
                    return value.directory
                        && value.directory->states[1] != 0
                        && value.directory->states[4] != 0
                        && value.directory->states[7] == 0;
                });
        const bool complete = failureCode_ == 0
            && (batchComplete || p8Ready_);
        if (complete)
            static_cast<DebugP2bMappedControl*>(mapping_)->state =
                DebugP2bObservationState::Complete;
        else fail(18);
        static constexpr char completeStatus[] = "COMPLETE";
        static constexpr char incompleteStatus[] = "INCOMPLETE";
        const char* status = complete ? completeStatus : incompleteStatus;
        add("schema", 1, 1, sizeof(schema) - 1, schema);
        add("captureStage", 1, 1, sizeof(stage) - 1, stage);
        add("metersPerUnit", 5, 8, 1, &metersPerUnit);
        add("captureStatus", 1, 1, std::strlen(status), status);
        static constexpr char rawComplete[] = "1";
        static constexpr char rawIncomplete[] = "0";
        add("rawFamiliesComplete", 1, 1, 1,
            complete ? rawComplete : rawIncomplete);
        static constexpr const char* keys[2][10] = {
            {"s1.0.key", "s1.0.memberOffsets", "s1.0.chartOffsets",
             "s1.0.finalTriangleMap", "s1.0.lineage", "s1.0.adjacency",
             "s1.0.islands", "s2.0.samples", "s2.0.normal",
             "s2.0.normalMask"},
            {"s1.1.key", "s1.1.memberOffsets", "s1.1.chartOffsets",
             "s1.1.finalTriangleMap", "s1.1.lineage", "s1.1.adjacency",
             "s1.1.islands", "s2.1.samples", "s2.1.normal",
             "s2.1.normalMask"},
        };
        for (std::size_t slot = 0; slot < contexts_.size(); ++slot) {
            const auto& c = contexts_[slot];
            const auto& b = bakeContexts_[slot];
            const bool present = c.directory != nullptr;
            add(keys[slot][0], 2, 1, present ? 32 : 0,
                present ? c.directory->key : nullptr);
            add(keys[slot][1], 3, 8, present ? c.directory->lengths[0] : 0,
                c.memberOffsets);
            add(keys[slot][2], 3, 8, present ? c.directory->lengths[1] : 0,
                c.chartOffsets);
            add(keys[slot][3], 4, 4, present ? c.directory->lengths[2] : 0,
                c.finalTriangleMap, 1);
            add(keys[slot][4], 6, 40, present ? c.directory->lengths[3] : 0,
                c.lineage);
            add(keys[slot][5], 6, 32, present ? c.directory->lengths[4] : 0,
                c.adjacency);
            add(keys[slot][6], 6, 48, present ? c.directory->lengths[5] : 0,
                c.islands);
            add(keys[slot][7], 6, 80, present ? c.directory->lengths[6] : 0,
                b.samples);
            add(keys[slot][8], 6, 128, present ? 1 : 0, b.normal);
            add(keys[slot][9], 2, 1, present ? c.directory->lengths[7] : 0,
                b.normalMask);
        }
        for (std::size_t index = 0; index < p5SpecCount_; ++index) {
            const auto& spec = p5Specs_[index];
            add(spec.key, spec.kind, spec.width, spec.count, spec.bytes,
                spec.flags);
        }
        if (next != 25 + p5SpecCount_) {
            fail(14);
            return nil;
        }
        std::uint64_t keysOffset = sizeof(DebugP2bWireHeader);
        std::uint64_t tableBytes = 0;
        if (!DebugP2bCheckedProduct(next,
                sizeof(DebugP2bWireRecord), tableBytes)
            || !DebugP2bCheckedAdd(keysOffset, tableBytes, keysOffset)) {
            fail(14);
            return nil;
        }
        std::uint64_t payloadOffset = keysOffset;
        for (std::size_t index = 0; index < next; ++index) {
            const auto& spec = specs[index];
            const std::size_t keyLength = std::strlen(spec.key);
            if (keyLength > std::numeric_limits<std::uint32_t>::max()
                || !DebugP2bCheckedAdd(payloadOffset, keyLength,
                    payloadOffset)) {
                fail(14);
                return nil;
            }
        }
        std::uint64_t total = payloadOffset;
        for (std::size_t index = 0; index < next; ++index) {
            const auto& spec = specs[index];
            std::uint64_t length = 0;
            if (!DebugP2bCheckedProduct(spec.count, spec.width, length)
                || (length != 0 && !spec.bytes)
                || !DebugP2bCheckedAdd(total, length, total)
                || total > stagingCursor_) {
                fail(14);
                return nil;
            }
        }
        auto* const base = static_cast<std::uint8_t*>(mapping_)
            + std::size_t(kDebugP2bNativeBytes);
        DebugP2bWireHeader header;
        header.recordCount = std::uint16_t(next);
        header.keysOffset = keysOffset;
        header.payloadOffset = payloadOffset;
        header.totalLength = total;
        std::memcpy(base, &header, sizeof(header));
        std::uint64_t keyCursor = keysOffset;
        std::uint64_t valueCursor = payloadOffset;
        for (std::size_t index = 0; index < next; ++index) {
            const auto& spec = specs[index];
            const std::uint32_t keyLength = std::uint32_t(
                std::strlen(spec.key));
            const std::uint64_t valueLength = spec.count * spec.width;
            const DebugP2bWireRecord record{keyCursor, keyLength,
                spec.kind, spec.width, spec.count, valueCursor,
                valueLength, spec.flags};
            std::memcpy(base + sizeof(header) + index * sizeof(record),
                &record, sizeof(record));
            std::memcpy(base + keyCursor, spec.key, keyLength);
            keyCursor += keyLength;
            valueCursor += valueLength;
        }
        valueCursor = payloadOffset;
        for (std::size_t index = 0; index < next; ++index) {
            const auto& spec = specs[index];
            const std::uint64_t length = spec.count * spec.width;
            if (length != 0)
                std::memcpy(base + valueCursor, spec.bytes,
                    std::size_t(length));
            valueCursor += length;
        }
        wireLength_ = total;
        retain();
        DebugP2bObservationArena* const lease = this;
        @try {
            NSData* result = [[NSData alloc] initWithBytesNoCopy:base
                length:std::size_t(total)
                deallocator:^(void*, NSUInteger) { lease->release(); }];
            if (result) return result;
        } @catch (...) {}
        release();
        fail(15);
        return nil;
    }
    void copyDiagnostic(DebugP2bObservationDiagnostic& diagnostic) const noexcept {
        if (mapping_)
            diagnostic.state = static_cast<const DebugP2bMappedControl*>(
                mapping_)->state;
        for (std::size_t index = 0; index < contexts_.size(); ++index) {
            const auto& context = contexts_[index];
            auto& output = diagnostic.s1Slots[index];
            if (!context.directory) continue;
            std::copy(std::begin(context.directory->key),
                std::end(context.directory->key), std::begin(output.key));
            std::copy_n(context.directory->lengths, 6, output.lengths);
            std::copy_n(context.directory->counters, 3, output.attempted);
            output.prepared = context.directory->states[0] != 0;
            output.sealed = context.directory->states[1] != 0;
            output.firstFailure = context.directory->states[7];
            if (output.lengths[3] != 0) {
                output.firstLineage = context.lineage[0];
                output.lastLineage = context.lineage[output.lengths[3] - 1];
            }
            if (output.lengths[5] != 0) {
                output.firstIsland = context.islands[0];
                output.lastIsland = context.islands[output.lengths[5] - 1];
            }
            if (output.lengths[4] != 0) {
                output.firstAdjacency = context.adjacency[0];
                output.lastAdjacency = context.adjacency[output.lengths[4] - 1];
            }
            const auto& bakeContext = bakeContexts_[index];
            auto& s2 = diagnostic.s2Slots[index];
            if (!bakeContext.directory) continue;
            if (bakeContext.normal) s2.normal = *bakeContext.normal;
            s2.retainedSampleCount = std::min<std::uint64_t>(
                bakeContext.directory->lengths[6], s2.samples.size());
            if (bakeContext.samples)
                std::copy_n(bakeContext.samples, s2.retainedSampleCount,
                    s2.samples.begin());
            s2.maskBytes = bakeContext.directory->lengths[7];
            s2.quantizedAttempts = bakeContext.directory->counters[3];
            s2.sampleAttempts = bakeContext.directory->counters[4];
            s2.beginRoleAttempts = bakeContext.directory->counters[5];
            s2.finishRoleAttempts = bakeContext.directory->counters[6];
            s2.sealed = bakeContext.directory->states[3] != 0;
            s2.committed = bakeContext.directory->states[4] != 0;
            s2.noNormal = bakeContext.directory->states[5] != 0;
            s2.firstFailure = bakeContext.directory->states[7];
        }
    }
    void close() noexcept {
        if (mapping_) {
            static_cast<DebugP2bMappedControl*>(mapping_)
                ->~DebugP2bMappedControl();
            munmap(mapping_, std::size_t(kDebugP2bArenaBytes));
            mapping_ = nullptr;
            gDebugP2bActiveMappings.fetch_sub(1, std::memory_order_relaxed);
            gDebugP2bTotalUnmaps.fetch_add(1, std::memory_order_relaxed);
        }
        account_.release();
    }
private:
    void* stage(const std::uint64_t bytes) noexcept {
        if (bytes == 0) return nullptr;
        if (!mapping_ || bytes > stagingCursor_) { fail(14); return nullptr; }
        const std::uint64_t start = (stagingCursor_ - bytes) & ~std::uint64_t(63);
        if (start >= stagingCursor_ || start < 64 * 1024) {
            fail(14); return nullptr;
        }
        stagingCursor_ = start;
        return static_cast<std::uint8_t*>(mapping_)
            + std::size_t(kDebugP2bNativeBytes + start);
    }
    void addP5Spec(const char* key, const std::uint16_t kind,
        const std::uint16_t width, const std::uint64_t count,
        const void* bytes, const bool alreadyStaged = false) noexcept {
        if (!key || p5SpecCount_ >= p5Specs_.size()) { fail(14); return; }
        std::uint64_t length = 0;
        if (!DebugP2bCheckedProduct(count, width, length)
            || (length != 0 && !bytes)) { fail(14); return; }
        void* retained = const_cast<void*>(bytes);
        if (length != 0 && !alreadyStaged) {
            retained = stage(length);
            if (!retained) return;
            std::memcpy(retained, bytes, std::size_t(length));
        }
        if (std::strlen(key) >= sizeof(p5Specs_[0].key)) { fail(14); return; }
        auto& spec = p5Specs_[p5SpecCount_++];
        std::strcpy(spec.key, key);
        spec.kind = kind; spec.width = width; spec.count = count;
        spec.bytes = retained;
    }
    void fail(const std::uint32_t reason) noexcept {
        if (failureCode_ == 0) failureCode_ = reason;
        if (mapping_)
            static_cast<DebugP2bMappedControl*>(mapping_)->state =
                DebugP2bObservationState::Incomplete;
    }
    DebugP2bObserverAccount account_;
    std::atomic<std::uint64_t> references_{1};
    void* mapping_ = nullptr;
    std::uint32_t failureCode_ = 0;
    std::uint64_t wireLength_ = 0;
    std::uint64_t stagingCursor_ = kDebugP2bWireBytes;
    std::size_t p5SpecCount_ = 0, occurrenceCount_ = 0;
    bool p7Ready_ = false;
    bool p8Ready_ = false;
    DebugP2bAccountingTrace trace_{};
    DebugP2bLifetimeEvent* lifetimeEvents_ = nullptr;
    std::uint64_t lifetimeCount_ = 0;
    std::array<DebugP2bP5Spec, 40> p5Specs_{};
    std::array<DebugP2bLayoutContext, 2> contexts_{};
    std::array<DebugP2bBakeContext, 2> bakeContexts_{};
    std::array<asset_atlas::build::DebugLayoutObserver, 2> observers_{};
    std::array<painted_atlas_bake::kernel::DebugBakeObserver, 2>
        bakeObservers_{};
};

class DebugP2bObserverSession final {
public:
    explicit DebugP2bObserverSession(
        DebugP2bObservationDiagnostic* diagnostic) noexcept
        : diagnostic_(diagnostic) {
        if (!diagnostic_) return;
        diagnostic_->state = diagnostic_->enabled
            ? DebugP2bObservationState::Incomplete
            : DebugP2bObservationState::Disabled;
    }
    bool start() noexcept {
        if (!diagnostic_ || !diagnostic_->enabled || diagnostic_->started)
            return false;
        diagnostic_->started = true;
        arena_ = new (std::nothrow) DebugP2bObservationArena();
        diagnostic_->mapped = arena_ && arena_->valid();
        diagnostic_->failureCode = arena_ ? arena_->failureCode() : 5;
        if (diagnostic_->mapped) diagnostic_->state =
            DebugP2bObservationState::Recording;
        return diagnostic_->mapped;
    }
    const asset_atlas::build::DebugLayoutObserver* layoutObserver(
        const std::size_t slot, const asset_atlas::Key& key) noexcept {
        return arena_ && arena_->valid()
            ? arena_->layoutObserver(slot, key) : nullptr;
    }
    const painted_atlas_bake::kernel::DebugBakeObserver* bakeObserver(
        const std::size_t slot) noexcept {
        return arena_ && arena_->valid()
            ? arena_->bakeObserver(slot) : nullptr;
    }
    void commitS2(const std::size_t slot) noexcept {
        if (arena_ && arena_->valid()) arena_->commitS2(slot);
    }
    decal_layer::bake::accounting::View accountingView(
        const decal_layer::bake::accounting::View& base,
        const std::uint64_t operationID) noexcept {
        return arena_ && arena_->valid()
            ? arena_->accountingView(base, operationID) : base;
    }
    void accountingGroup(const asset_atlas::Key* key) noexcept {
        if (arena_ && arena_->valid()) arena_->accountingGroup(key);
    }
    void boundary(const DebugP2bEventKind kind,
        const bool decision = true) noexcept {
        if (arena_ && arena_->valid()) arena_->boundary(kind, decision);
    }
    void lifetime(const std::uint8_t owner, const std::uint8_t kind,
        const std::uint64_t bufferBytes, const std::uint64_t ticketBytes,
        const std::uint64_t liveBytes) noexcept {
        if (arena_ && arena_->valid()) arena_->lifetime(owner, kind,
            bufferBytes, ticketBytes, liveBytes);
    }
    void retainOccurrence(const std::size_t groupIndex,
        const std::size_t sourceInstanceIndex, const Matrix4d& world,
        const Matrix4d& object, const Matrix4d& explorer,
        const Matrix4d& origin) noexcept {
        if (arena_ && arena_->valid()) arena_->retainOccurrence(groupIndex,
            sourceInstanceIndex, world, object, explorer, origin);
    }
    void retainSelectedOccurrences(
        const std::vector<std::string>& identifiers) noexcept {
        if (arena_ && arena_->valid())
            arena_->retainSelectedOccurrences(identifiers);
    }
    void retainP5Group(const std::size_t slot, const SavedGroupOwner& group,
        const std::vector<DefinitionData>& definitions,
        const SavedGroupFinalResult& result) noexcept {
        if (arena_ && arena_->valid())
            arena_->retainP5Group(slot, group, definitions, result);
    }
    void retainP6Group(const std::size_t slot, const SavedGroupOwner& group,
        const SavedGroupFinalResult& result) noexcept {
        if (arena_ && arena_->valid())
            arena_->retainP6Group(slot, group, result);
    }
    void retainP8SingleGroup() noexcept {
        if (arena_ && arena_->valid()) arena_->retainP8SingleGroup();
    }
    void retainP7(const OperationLedger& operation,
        const painted_atlas_bake::owner::AggregateBakePlan& aggregate,
        const std::array<SavedGroupOwner, 2>& groups) noexcept {
        if (arena_ && arena_->valid())
            arena_->retainP7(operation, aggregate, groups);
    }
    void projectWire(const double metersPerUnit) noexcept {
        if (!diagnostic_) return;
        diagnostic_->metersPerUnit = metersPerUnit;
        if (!arena_ || !arena_->valid() || diagnostic_->wire) return;
        diagnostic_->wire = arena_->serialize(metersPerUnit);
        diagnostic_->wireLength = diagnostic_->wire.length;
        diagnostic_->wireLeaseCountAfterReturn = diagnostic_->wire
            ? arena_->leaseCount() - 1 : 0;
        diagnostic_->failureCode = arena_->failureCode();
    }
    ~DebugP2bObserverSession() {
        if (!diagnostic_) return;
        if (diagnostic_->enabled)
            diagnostic_->state = DebugP2bObservationState::Incomplete;
        if (arena_) {
            arena_->copyDiagnostic(*diagnostic_);
            diagnostic_->failureCode = arena_->failureCode();
        }
        const bool retainedView = diagnostic_->wire != nil;
        if (arena_) arena_->release();
        arena_ = nullptr;
        diagnostic_->activeBytesAfter = retainedView ? 0 :
            gDebugP2bActiveBytes.load(std::memory_order_relaxed);
        diagnostic_->activeMappingsAfter = retainedView ? 0 :
            gDebugP2bActiveMappings.load(std::memory_order_relaxed);
        diagnostic_->reservationsAfter = retainedView
            ? diagnostic_->reservationsBefore + 1
            : gDebugP2bTotalReservations.load(std::memory_order_relaxed);
        diagnostic_->releasesAfter = retainedView
            ? diagnostic_->releasesBefore + 1
            : gDebugP2bTotalReleases.load(std::memory_order_relaxed);
        diagnostic_->mapsAfter =
            gDebugP2bTotalMappings.load(std::memory_order_relaxed);
        diagnostic_->unmapsAfter = retainedView
            ? diagnostic_->unmapsBefore + 1
            : gDebugP2bTotalUnmaps.load(std::memory_order_relaxed);
        diagnostic_->hookCallsAfter =
            gDebugP2bHookCalls.load(std::memory_order_relaxed);
    }
private:
    DebugP2bObservationDiagnostic* diagnostic_ = nullptr;
    DebugP2bObservationArena* arena_ = nullptr;
};

DebugP2bObservationDiagnostic DebugP2bBeginDiagnostic(
    const bool enabled) noexcept {
    DebugP2bObservationDiagnostic value;
    value.enabled = enabled;
    value.activeBytesBefore =
        gDebugP2bActiveBytes.load(std::memory_order_relaxed);
    value.activeMappingsBefore =
        gDebugP2bActiveMappings.load(std::memory_order_relaxed);
    value.reservationsBefore =
        gDebugP2bTotalReservations.load(std::memory_order_relaxed);
    value.releasesBefore =
        gDebugP2bTotalReleases.load(std::memory_order_relaxed);
    value.mapsBefore = gDebugP2bTotalMappings.load(std::memory_order_relaxed);
    value.unmapsBefore = gDebugP2bTotalUnmaps.load(std::memory_order_relaxed);
    value.hookCallsBefore =
        gDebugP2bHookCalls.load(std::memory_order_relaxed);
    value.s1BoundRefusalVerified = DebugP2bVerifyBoundRefusal();
    value.s2CallbacksVerified = DebugP2bVerifyS2Callbacks();
    value.s2BoundRefusalVerified = DebugP2bVerifyS2BoundRefusal();
    std::uint64_t ignored = 0;
    value.arithmeticRefused = !DebugP2bCheckedAlign64(
        std::numeric_limits<std::uint64_t>::max(), ignored);
    return value;
}

NSString* DebugP2bStateText(const DebugP2bObservationState state) noexcept {
    switch (state) {
        case DebugP2bObservationState::Disabled: return @"DISABLED";
        case DebugP2bObservationState::Recording: return @"RECORDING";
        case DebugP2bObservationState::Complete: return @"COMPLETE";
        case DebugP2bObservationState::Incomplete: return @"INCOMPLETE";
    }
    return @"INCOMPLETE";
}

NSDictionary<NSString*, id>* DebugP2bRawDictionary(
    const DebugP2bObservationDiagnostic& value) noexcept {
    @try {
        return @{
            @"schema": @"shapeyard.p2b-observation.v1",
            @"captureStage": @"saved-batch-before-current-validation",
            @"metersPerUnit": @(value.metersPerUnit),
            @"captureStatus": DebugP2bStateText(value.state),
            @"complete": @(value.state == DebugP2bObservationState::Complete),
            @"wire": value.wire ?: NSNull.null,
            @"wireLength": @(value.wireLength),
            @"wireLeaseCountAfterReturn": @(
                value.wireLeaseCountAfterReturn),
        };
    } @catch (...) {
        return nil;
    }
}

NSDictionary<NSString*, id>* DebugP2bDiagnosticDictionary(
    const DebugP2bObservationDiagnostic& value) noexcept {
    @try {
        const auto lineage = [](const DebugP2bEmittedTriangleLineage& row) {
            return @[@(row.packedTriangleIndex), @(row.memberIndex),
                @(row.memberChartOrdinal), @(row.chartIndex),
                @(row.chartLocalTriangleIndex), @(row.subChartIndex),
                @(row.finalTriangleIndex)];
        };
        const auto island = [](const DebugP2bPackedIslandRecord& row) {
            return @[@(row.chartIndex), @(row.subChartIndex),
                @(row.memberChartOrdinal), @(row.segmentRank),
                @(row.atlasChartIndex),
                [NSData dataWithBytes:row.uuid length:sizeof(row.uuid)]];
        };
        const auto edge = [](const DebugP2bAdjacency& row) {
            return @[@(row.values[0]), @(row.values[1]), @(row.values[2]),
                @(row.values[3]), @(row.values[4]), @(row.values[5]),
                @(row.values[6]), @(row.kernelSeam != 0)];
        };
        const auto sample = [](const DebugP2bSampleExtra& row) {
            return @[@(row.aimed[0]), @(row.aimed[1]), @(row.aimed[2]),
                @(row.aimed[3]), @(row.preNormalizationLength),
                @(row.preQuantizationLengthError),
                @(row.normalInvocationOrdinal), @(row.packedTriangleIndex),
                @(row.sampleIndex), @(row.normalizationApplied != 0),
                @(row.applicability != 0)];
        };
        NSMutableArray<NSDictionary<NSString*, id>*>* slots =
            [NSMutableArray arrayWithCapacity:value.s1Slots.size()];
        for (const auto& slot : value.s1Slots) {
            NSMutableArray<NSNumber*>* lengths = [NSMutableArray array];
            NSMutableArray<NSNumber*>* attempted = [NSMutableArray array];
            for (const auto length : slot.lengths)
                [lengths addObject:@(length)];
            for (const auto count : slot.attempted)
                [attempted addObject:@(count)];
            [slots addObject:@{
                @"key": [NSData dataWithBytes:slot.key length:sizeof(slot.key)],
                @"prepared": @(slot.prepared),
                @"sealed": @(slot.sealed),
                @"firstFailure": @(slot.firstFailure),
                @"lengths": lengths,
                @"attempted": attempted,
                @"firstLineage": lineage(slot.firstLineage),
                @"lastLineage": lineage(slot.lastLineage),
                @"firstIsland": island(slot.firstIsland),
                @"lastIsland": island(slot.lastIsland),
                @"firstAdjacency": edge(slot.firstAdjacency),
                @"lastAdjacency": edge(slot.lastAdjacency),
            }];
        }
        NSMutableArray<NSDictionary<NSString*, id>*>* s2Slots =
            [NSMutableArray arrayWithCapacity:value.s2Slots.size()];
        for (const auto& slot : value.s2Slots) {
            NSMutableArray<NSArray*>* samples = [NSMutableArray array];
            for (std::uint64_t index = 0;
                 index < slot.retainedSampleCount; ++index)
                [samples addObject:sample(slot.samples[index])];
            [s2Slots addObject:@{
                @"available": @(slot.normal.available != 0),
                @"sealed": @(slot.sealed),
                @"committed": @(slot.committed),
                @"noNormal": @(slot.noNormal),
                @"firstFailure": @(slot.firstFailure),
                @"role": @(slot.normal.role),
                @"width": @(slot.normal.width),
                @"height": @(slot.normal.height),
                @"sampleCount": @(slot.normal.sampleCount),
                @"uniqueTexelCount": @(slot.normal.uniqueTexelCount),
                @"duplicateInvocationCount": @(
                    slot.normal.duplicateInvocationCount),
                @"validNormalizationCount": @(
                    slot.normal.validNormalizationCount),
                @"invalidNormalizationCount": @(
                    slot.normal.invalidNormalizationCount),
                @"measuredMaximumLengthError": @(
                    slot.normal.measuredMaximumLengthError),
                @"maskBytes": @(slot.maskBytes),
                @"quantizedAttempts": @(slot.quantizedAttempts),
                @"sampleAttempts": @(slot.sampleAttempts),
                @"beginRoleAttempts": @(slot.beginRoleAttempts),
                @"finishRoleAttempts": @(slot.finishRoleAttempts),
                @"samples": samples,
            }];
        }
        return @{
            @"schema": @"shapeyard.p2b-arena-diagnostic.v1",
            @"account": [NSString stringWithUTF8String:
                kDebugP2bAccountName] ?: @"",
            @"enabled": @(value.enabled),
            @"started": @(value.started),
            @"mapped": @(value.mapped),
            @"status": DebugP2bStateText(value.state),
            @"complete": @(value.state == DebugP2bObservationState::Complete),
            @"failureCode": @(value.failureCode),
            @"hardCapBytes": @(kDebugP2bArenaBytes),
            @"nativeBytes": @(kDebugP2bNativeBytes),
            @"wireBytes": @(kDebugP2bWireBytes),
            @"usedBytes": @(kDebugP2bUsedBytes),
            @"mappingAlignmentBytes": @(kDebugP2bMappingAlignment),
            @"slotBytes": @(kDebugP2bSlotBytes),
            @"groupCount": @(kDebugP2bGroupCount),
            @"sampleEvidenceSize": @(sizeof(
                painted_atlas_bake::kernel::SampleEvidence)),
            @"layoutEvidenceSize": @(sizeof(
                asset_atlas::build::LayoutEvidence)),
            @"exportBakeStorageSize": @(sizeof(
                painted_atlas_bake::owner::ExportBakeStorage)),
            @"sampleEvidenceMirrorSize": @(
                sizeof(DebugP2bFrozenSampleEvidence)),
            @"layoutEvidenceMirrorSize": @(
                sizeof(DebugP2bFrozenLayoutEvidence)),
            @"exportBakeStorageMirrorSize": @(
                sizeof(DebugP2bFrozenExportBakeStorage)),
            @"activeBytesBefore": @(value.activeBytesBefore),
            @"activeBytesAfter": @(value.activeBytesAfter),
            @"activeMappingsBefore": @(value.activeMappingsBefore),
            @"activeMappingsAfter": @(value.activeMappingsAfter),
            @"reservationDelta": @(
                value.reservationsAfter - value.reservationsBefore),
            @"releaseDelta": @(value.releasesAfter - value.releasesBefore),
            @"mappingDelta": @(value.mapsAfter - value.mapsBefore),
            @"unmapDelta": @(value.unmapsAfter - value.unmapsBefore),
            @"hookCallDelta": @(
                value.hookCallsAfter - value.hookCallsBefore),
            @"s1BoundRefusalVerified": @(value.s1BoundRefusalVerified),
            @"s1Slots": slots,
            @"s2CallbacksVerified": @(value.s2CallbacksVerified),
            @"s2BoundRefusalVerified": @(value.s2BoundRefusalVerified),
            @"s2Slots": s2Slots,
            @"p2bRaw": DebugP2bRawDictionary(value) ?: @{},
            @"arithmeticOverflowRefused": @(value.arithmeticRefused),
            @"wireLength": @(value.wireLength),
            @"wireLeaseCountAfterReturn": @(
                value.wireLeaseCountAfterReturn),
            @"entryRejectionMappingDelta": @0,
            @"assetAtlasBuildSourceSHA256":
                @"d4d855cdaf0864244f8c620fd2070c7b11a74766c8e0aa3e9e0e7d3651383b8d",
            @"paintedAtlasBakeSourceSHA256":
                @"ae3b05ed978a1ca2cd9483e3a6eb78b0c8b78bf8db8893e697283372b22f4757",
        };
    } @catch (...) {
        return nil;
    }
}

struct DebugP2bAdmissionDiagnostic final {
    NSData* __strong trace = nil;
    NSData* __strong comparison = nil;
    NSArray<NSNumber*>* __strong ledgerState = nil;
    std::uint64_t operationID = 0, eventCount = 0, eventAttempted = 0;
    std::uint64_t targetOrdinal = 0, targetCount = 0;
    std::uint64_t targetRequestBytes = 0, privateLimit = 0;
    bool contextEqual = true, productComplete = false;
    bool traceComplete = false, targetTuple = false;
    bool outputVectorPrecedesTarget = false, complete = false;
};

class DebugP2bAdmissionControl final {
public:
    static constexpr std::size_t kDebugP2bAdmissionTraceRows = 131'072;
    explicit DebugP2bAdmissionControl(
        DebugP2bAdmissionDiagnostic* diagnostic) noexcept
        : diagnostic_(diagnostic),
          events_(diagnostic ? new (std::nothrow)
              DebugP2bAccountingEvent[kDebugP2bAdmissionTraceRows]
              : nullptr) {}
    ~DebugP2bAdmissionControl() { finish(); }
    void begin(OperationLedger& operation, const asset_atlas::Key& key) noexcept {
        if (!diagnostic_) return;
        operation_ = &operation;
        trace_.base = operation.view();
        trace_.events = events_.get();
        trace_.capacity = events_ ? kDebugP2bAdmissionTraceRows : 0;
        trace_.includeAdmissionEvents = true;
        trace_.operationID = std::uint64_t(
            reinterpret_cast<std::uintptr_t>(&operation));
        std::memcpy(trace_.groupKey, key.document.data(), 16);
        std::memcpy(trace_.groupKey + 16, key.atlas.data(), 16);
        diagnostic_->operationID = trace_.operationID;
    }
    decal_layer::bake::accounting::View view() noexcept {
        return operation_ ? trace_.view()
            : decal_layer::bake::accounting::View{};
    }
    void requireContext(const void* context) noexcept {
        if (diagnostic_ && context != &trace_) diagnostic_->contextEqual = false;
    }
    void retainComparison(const SavedGroupOwner& group,
        const SavedGroupFinalResult& result) noexcept {
        if (!diagnostic_) return;
        DebugP2bP6Writer measure;
        DebugP2bEncodeP6Group(measure, 0, group, result);
        if (!measure.valid || measure.cursor == 0) return;
        @try {
            NSMutableData* bytes = [NSMutableData dataWithLength:
                std::size_t(measure.cursor)];
            if (!bytes) return;
            DebugP2bP6Writer writer{static_cast<std::uint8_t*>(
                bytes.mutableBytes), measure.cursor};
            DebugP2bEncodeP6Group(writer, 0, group, result);
            if (writer.valid && writer.cursor == measure.cursor)
                diagnostic_->comparison = bytes;
        } @catch (...) {}
    }
    void markProductComplete(const bool value) noexcept {
        if (diagnostic_) diagnostic_->productComplete = value;
    }
private:
    void finish() noexcept {
        if (!diagnostic_ || !operation_) return;
        using Dimension = decal_layer::bake::accounting::StorageDimension;
        using Job = decal_layer::bake::accounting::Job;
        using Site = decal_layer::bake::accounting::FailureSite;
        diagnostic_->eventCount = trace_.count;
        diagnostic_->eventAttempted = trace_.attempted;
        diagnostic_->traceComplete = trace_.count != 0
            && trace_.count == trace_.attempted;
        for (std::size_t index = 0; index < trace_.count; ++index) {
            const auto& target = events_[index];
            if (target.kind != std::uint16_t(DebugP2bEventKind::Reserve)
                || target.failureSite != std::uint32_t(
                    Site::ExportObservedStorage)
                || target.dimension != std::uint8_t(Dimension::PrivateStorage)
                || target.retention != std::uint8_t(
                    decal_layer::bake::accounting::Retention::Retained)
                || target.bytes != 12 * sizeof(
                    painted_atlas_bake::kernel::SampleEvidence)) continue;
            ++diagnostic_->targetCount;
            diagnostic_->targetOrdinal = target.sequence;
            diagnostic_->targetRequestBytes = target.bytes;
            if (index >= 3) {
                const auto& product = events_[index - 1];
                const auto& outputReserve = events_[index - 2];
                const auto& outputProduct = events_[index - 3];
                diagnostic_->targetTuple = product.kind == std::uint16_t(
                        DebugP2bEventKind::CheckedProduct)
                    && product.failureSite == target.failureSite
                    && product.units == 12
                    && product.bytes == sizeof(
                        painted_atlas_bake::kernel::SampleEvidence)
                    && product.job == 1 && product.decision != 0;
                diagnostic_->outputVectorPrecedesTarget =
                    outputReserve.kind == std::uint16_t(
                        DebugP2bEventKind::Reserve)
                    && outputReserve.failureSite == std::uint32_t(
                        Site::ExportBakeStorage)
                    && outputReserve.dimension == std::uint8_t(
                        Dimension::PrivateStorage)
                    && outputProduct.kind == std::uint16_t(
                        DebugP2bEventKind::CheckedProduct)
                    && outputProduct.failureSite == outputReserve.failureSite
                    && outputProduct.job == 1
                    && outputProduct.units * outputProduct.bytes
                        == outputReserve.bytes;
            }
        }
        if (diagnostic_->targetCount != 1) {
            diagnostic_->targetRequestBytes = 0;
        }
        const auto privateState = operation_->debugStorageState(
            Dimension::PrivateStorage);
        diagnostic_->privateLimit = privateState[4];
        @try {
            diagnostic_->trace = [NSData dataWithBytes:events_.get()
                length:std::size_t(trace_.count * sizeof(events_[0]))];
            NSMutableArray<NSNumber*>* state = [NSMutableArray array];
            for (std::size_t index = 0;
                 index < std::size_t(Dimension::Count); ++index)
                for (const auto value : operation_->debugStorageState(
                        Dimension(index))) [state addObject:@(value)];
            for (std::size_t index = 0; index < std::size_t(Job::Count); ++index)
                for (const auto value : operation_->debugJobState(Job(index)))
                    [state addObject:@(value)];
            for (std::size_t index = 0; index < std::size_t(Site::Count); ++index)
                [state addObject:@(operation_->allocationEntries(Site(index)))];
            const auto settlement = operation_->debugSettlementObservation();
            for (const auto value : {settlement.faceImageTransfers,
                    settlement.paintedBakeTransfers, settlement.destructions,
                    settlement.faceImageBytes, settlement.paintedBakeBytes,
                    settlement.destroyedBytes, settlement.finalLiveBytes,
                    std::size_t(settlement.firstFailure),
                    std::size_t(settlement.overflow)})
                [state addObject:@(value)];
            diagnostic_->ledgerState = state;
        } @catch (...) {}
        diagnostic_->complete = diagnostic_->productComplete
            && diagnostic_->contextEqual && diagnostic_->traceComplete
            && diagnostic_->targetCount == 1 && diagnostic_->targetTuple
            && diagnostic_->outputVectorPrecedesTarget
            && diagnostic_->trace && diagnostic_->comparison
            && diagnostic_->ledgerState;
        operation_ = nullptr;
    }
    DebugP2bAdmissionDiagnostic* diagnostic_ = nullptr;
    OperationLedger* operation_ = nullptr;
    DebugP2bAccountingTrace trace_{};
    std::unique_ptr<DebugP2bAccountingEvent[]> events_;
};

NSDictionary<NSString*, id>* DebugP2bAdmissionDictionary(
    const DebugP2bAdmissionDiagnostic& value) noexcept {
    @try {
        return @{
            @"schema": @"shapeyard.p2b-admission.v1",
            @"complete": @(value.complete),
            @"contextEqual": @(value.contextEqual),
            @"productComplete": @(value.productComplete),
            @"traceComplete": @(value.traceComplete),
            @"operationID": @(value.operationID),
            @"eventCount": @(value.eventCount),
            @"eventAttempted": @(value.eventAttempted),
            @"targetCount": @(value.targetCount),
            @"targetOrdinal": @(value.targetOrdinal),
            @"targetRequestBytes": @(value.targetRequestBytes),
            @"targetTuple": @(value.targetTuple),
            @"outputVectorPrecedesTarget": @(
                value.outputVectorPrecedesTarget),
            @"privateLimit": @(value.privateLimit),
            @"trace": value.trace ?: NSData.data,
            @"ledgerState": value.ledgerState ?: @[],
            @"comparisonP6": value.comparison ?: NSData.data,
            @"kernelAdmissionSourceSHA256":
                @"045ae2683d8fa339b057c15fcab176f0a041c823333fbe0ad5dd6009497d64c8",
            @"productAnchor": @"PaintedAtlasBake.hxx:evidenceTicket.acquireProduct",
        };
    } @catch (...) { return nil; }
}
