struct PrivateDecalCapture::Impl final {
    struct Owner final {
        struct Receiver final {
            decal_layer::ReceiverReceipt receipt;
            dependent_replay::FaceImageGeometricReceipt geometricReceipt;
            TopoDS_Face originalFace;
            TopoDS_Face disposableFace;
            std::uint32_t originalFaceIndex = 0;
            std::uint32_t disposableFaceIndex = 0;
        };
        decal_layer::bake::accounting::Ticket definitionLayersTicket;
        decal_layer::bake::accounting::Ticket canonicalBytesTicket;
        decal_layer::bake::accounting::Ticket receiverVectorTicket;
        decal_layer::bake::accounting::Ticket finishingStorageTicket;
        decal_layer::bake::accounting::Ticket paintedSourcesTicket;
        decal_layer::bake::accounting::Ticket definitionIdentifierTicket;
        retained_recipe::OwnerKey owner;
        decal_layer::Definition definition;
        std::vector<std::uint8_t> canonicalBytes;
        decal_layer::source::Witness source;
        // Declared before every retained native reference so reverse member
        // destruction releases the measured ticket only after those owners.
        decal_layer::bake::accounting::Ticket brepCensusTicket;
        TopoDS_Shape detachedAuthorityShape;
        std::unique_ptr<BRepBuilderAPI_Copy> copier;
        // Non-null when this owner borrows the saved group's one admitted
        // measured copy instead of owning a second one. Non-owning: the
        // saved-group measured ticket dominates every receiver handle (the
        // saved groups are declared before owners in Impl below).
        const SavedGroupMeasuredMember* borrowedMeasured = nullptr;
        std::vector<Receiver> receivers;
        asset_atlas::build::FinalMemberInput savedMember;
        asset_atlas::Key transientAtlas;
        retained_finishing::Definition transientFinishing;
        TDF_Label ownerLabel;
        std::vector<painted_atlas_bake::owner::CapturedSource> paintedSources;
        std::string definitionIdentifier;
    };

    // Impl is the single operation context. Capture creation transfers the
    // already-admitted stack ledger here before any protected scene copy; the
    // existing ReplayBudget below remains its unchanged topology component.
    OperationLedger operationLedger;
    decal_layer::bake::accounting::Ticket controlStorageTicket;
    decal_layer::bake::accounting::Ticket terminalSceneObjectTicket;
    decal_layer::bake::accounting::Ticket terminalSceneNumericTicket;
    decal_layer::bake::accounting::Ticket terminalSceneEncodedTicket;
    decal_layer::bake::accounting::Ticket terminalScenePrivateTicket;
    decal_layer::bake::accounting::Ticket terminalSceneControlTicket;
    decal_layer::bake::accounting::Ticket terminalOwnerObjectTicket;
    decal_layer::bake::accounting::Ticket terminalOwnerControlTicket;
    decal_layer::bake::accounting::Ticket finalCorrespondenceTicket;
    decal_layer::bake::accounting::Ticket finalEvidenceTicket;
    decal_layer::bake::accounting::Ticket documentIdentifierTicket;
    decal_layer::bake::accounting::Ticket ownersTicket;
    decal_layer::bake::accounting::Ticket wholeSceneNumericTicket;
    decal_layer::bake::accounting::Ticket wholeSceneEncodedTicket;
    decal_layer::bake::accounting::Ticket wholeScenePrivateTicket;
    SceneSnapshot wholeCommittedScene;
    // The strict atlas read admission dominates both the materialized census
    // and the operation-owned immutable saved-group captures. The saved-group
    // measured tickets in turn dominate every borrowed receiver handle inside
    // owners: the groups are declared before owners and destroyed after them.
    painted_atlas_bake::owner::AtlasReadAdmission savedAtlasReadAdmission;
    decal_layer::bake::accounting::Ticket savedGroupsTicket;
    std::vector<std::unique_ptr<SavedGroupOwner>> savedGroups;
    decal_layer::bake::accounting::Ticket savedGroupLayoutControlTicket;
    decal_layer::bake::accounting::Ticket rawEvidenceControlTicket;
    std::shared_ptr<const SavedGroupAllMemberLayoutRecord> savedGroupLayout;
    SavedGroupAllMemberLayoutReason savedGroupLayoutReason =
        SavedGroupAllMemberLayoutReason::Unavailable;
#ifdef DEBUG
    // Counts any receiver-pass measured copy made for a saved member; the
    // borrowed one-copy contract keeps this zero.
    std::uint64_t debugSavedMemberReceiverCopies = 0;
#endif
    std::vector<Owner> owners;
    mutable retained_edge_treatment::ReplayBudget budget;
    decal_layer::bake::publication::PrivateDestination destination;
    std::string documentIdentifier;
    decal_layer::Digest occluderProof{};
    double metersPerUnit = 0.0;
    bool selectedObjectsOnly = false;
    Handle(OcctDocument) privateDocument;

    bool recheckProtected(const std::function<bool()>& cancelled,
        decal_layer::bake::accounting::FailureSite boundary) noexcept;
};

const char* PrivatePaintedRoleText(const face_image::Role role) noexcept {
    switch (role) {
        case face_image::Role::BaseColor: return "baseColor";
        case face_image::Role::Emissive: return "emissive";
        case face_image::Role::MetallicRoughness: return "metallicRoughness";
        case face_image::Role::Occlusion: return "occlusion";
        case face_image::Role::Normal: return "normal";
    }
    return "unknown";
}

PrivateDecalCapture::PrivateDecalCapture() noexcept
    : impl_(new (std::nothrow) Impl()) {}

PrivateDecalCapture::~PrivateDecalCapture() = default;
PrivateDecalCapture::PrivateDecalCapture(PrivateDecalCapture&&) noexcept = default;
PrivateDecalCapture& PrivateDecalCapture::operator=(
    PrivateDecalCapture&&) noexcept = default;

#ifdef DEBUG
bool OcctSceneSnapshotBuilder::DebugCapturePersistedAtlasLineage(
    const Handle(OcctDocument)& privateDocument,
    const std::string& selectedDefinitionIdentifier,
    const DebugPersistedAtlasCaptureMode mode,
    DebugPersistedAtlasCaptureLineageObservation& observation) noexcept {
    observation = {};
    try {
        observation.failureStage = "entry";
        if (privateDocument.IsNull()
            || selectedDefinitionIdentifier.empty()) return false;
        const Handle(TDocStd_Document)& document = privateDocument->Document();
        if (document.IsNull() || document->HasOpenCommand()) return false;
        Standard_Real metersPerUnit = 0.0;
        if (!XCAFDoc_DocumentTool::GetLengthUnit(
                document, metersPerUnit) || !(metersPerUnit > 0.0))
            return false;

        std::vector<asset_atlas::persistence::Record> records;
        if (!asset_atlas::persistence::ReadAll(document, records)
            || records.size() != 1 || !records.front().value) return false;
        observation.atlasCount = records.size();
        const auto& persisted = *records.front().value;

        // The ledger is declared before every capture/copy/bake value below:
        // inherited views and their tickets therefore die before the concrete
        // builder-owned operation.
        OperationLedger ledger;
        retained_edge_treatment::ReplayBudget budget;
        if (!ledger.bindTopology(budget,
                decal_layer::bake::accounting::FailureSite::ContextControl))
            return false;
        painted_atlas_bake::owner::ExportCapture capture;
        observation.failureStage = "persisted-capture";
        const auto captureOutcome = painted_atlas_bake::owner::CaptureForExport(
            capture, document, persisted.definition.key, ledger.view());
        if (captureOutcome
                != painted_atlas_bake::owner::Outcome::Prepared
            || capture.operation.valid()
            || capture.operationView().context != ledger.view().context
            || capture.members.members.size()
                != persisted.definition.members.size()) return false;
        observation.inheritedOperation = true;
        observation.memberCount = capture.members.members.size();
        observation.sourceCount = capture.sources.size();

        painted_atlas_bake::owner::ExportCapture moved(std::move(capture));
        observation.captureMovePreserved = !capture.operationView().valid()
            && moved.operationView().context == ledger.view().context;
        if (!observation.captureMovePreserved) return false;

        struct MeasuredMember final {
            decal_layer::bake::accounting::Ticket storage;
            TopoDS_Shape original;
            TopoDS_Shape detached;
            std::unique_ptr<BRepBuilderAPI_Copy> copier;
            TopTools_IndexedMapOfShape originalFaces;
            TopTools_IndexedMapOfShape detachedFaces;
            std::string definitionIdentifier;
        };
        std::vector<MeasuredMember> measured;
        decal_layer::bake::accounting::Ticket measuredVectorTicket;
        if (!ReserveProtectedVector(measured, measuredVectorTicket,
                ledger.view(), moved.members.members.size(),
                decal_layer::bake::accounting::Retention::Retained,
                decal_layer::bake::accounting::FailureSite::
                    ProtectedOwnerStorage)) return false;

        if (mode == DebugPersistedAtlasCaptureMode::CancelBeforeCopy) {
            observation.cancelledBeforeCopy =
                ledger.allocationEntries(
                    decal_layer::bake::accounting::FailureSite::
                        BRepCensusCopy) == 0;
            return observation.cancelledBeforeCopy;
        }

        std::size_t measuredIndex = 0;
        for (const auto& member : moved.members.members) {
            observation.failureStage = "measured-member-shape-"
                + std::to_string(measuredIndex);
            MeasuredMember value;
            value.original = XCAFDoc_ShapeTool::GetShape(member.ownerLabel);
            value.definitionIdentifier =
                privateDocument->DefinitionIdentifierForLabel(
                    member.ownerLabel);
            if (value.original.IsNull()
                || value.definitionIdentifier.empty()) return false;
            BRepRepresentationCensus sourceCensus;
            BRepRepresentationCensus copyPrediction;
            BRepCensusPCurveLookup lookup;
            decal_layer::bake::accounting::Ticket scratch;
            observation.failureStage = "measured-member-census-"
                + std::to_string(measuredIndex);
            if (!MeasureBRepRepresentation(value.original, budget,
                    ledger.view(), sourceCensus, scratch, &copyPrediction,
                    &lookup)) {
                observation.failureStage += "-lookup-"
                    + std::to_string(std::uint8_t(lookup.kind)) + "-"
                    + (lookup.reason ? lookup.reason : "none") + "-failure-"
                    + std::to_string(std::uint16_t(
                        ledger.firstFailureSite()));
                return false;
            }
            scratch.reset();
            std::size_t retainedBytes = 0;
            observation.failureStage = "measured-member-copy-"
                + std::to_string(measuredIndex);
            const bool copied = CopyMeasuredBRep(value.original, budget,
                ledger, sourceCensus, copyPrediction,
                mode == DebugPersistedAtlasCaptureMode::DenyFirstCopy ? 2 : 0,
                value.storage, value.copier, value.detached,
                value.originalFaces, value.detachedFaces, retainedBytes);
            if (mode == DebugPersistedAtlasCaptureMode::DenyFirstCopy) {
                observation.deniedBeforeCopy = !copied
                    && measured.empty()
                    && ledger.allocationEntries(
                        decal_layer::bake::accounting::FailureSite::
                            BRepCensusCopy) == 0;
                return observation.deniedBeforeCopy;
            }
            if (!copied || value.detached.IsSame(value.original)) return false;
            for (const auto& prior : measured)
                if (value.detached.IsSame(prior.detached)) return false;
            observation.memberDefinitions.push_back(
                value.definitionIdentifier);
            measured.push_back(std::move(value));
            ++measuredIndex;
        }
        observation.measuredCopyCount = measured.size();
        observation.detachedAuthority = measured.size()
            == moved.members.members.size();

        observation.stableMemberOrder =
            moved.savedAtlas.members.size() == measured.size();
        for (std::size_t index = 0;
             observation.stableMemberOrder && index < measured.size(); ++index) {
            observation.stableMemberOrder =
                moved.savedAtlas.members[index].owner
                    == moved.members.members[index].slot.owner;
            observation.selectedMemberPresent =
                observation.selectedMemberPresent
                || measured[index].definitionIdentifier
                    == selectedDefinitionIdentifier;
        }
        if (!observation.stableMemberOrder
            || !observation.selectedMemberPresent) return false;

        const Handle(XCAFDoc_ShapeTool) shapeTool =
            XCAFDoc_DocumentTool::ShapeTool(document->Main());
        TDF_LabelSequence freeShapes;
        if (shapeTool.IsNull()) return false;
        shapeTool->GetFreeShapes(freeShapes);
        if (freeShapes.Length() < Standard_Integer(measured.size()))
            return false;
        observation.nonMemberCount = std::size_t(freeShapes.Length())
            - measured.size();

        painted_atlas_bake::owner::CapturedSourceStorage productionSources;
        if (!ReserveProtectedVector(productionSources.values,
                productionSources.vectorTicket, ledger.view(),
                moved.sources.size(),
                decal_layer::bake::accounting::Retention::Retained,
                decal_layer::bake::accounting::FailureSite::
                    ProtectedSourceStorage)) return false;
        std::array<bool, asset_atlas::kMaximumMembers> memberHasSource{};
        observation.failureStage = "source-correspondence";
        for (std::size_t sourceIndex = 0;
             sourceIndex < moved.sources.size(); ++sourceIndex) {
            painted_atlas_bake::owner::CapturedSource source(
                moved.sources[sourceIndex]);
            std::size_t memberIndex = measured.size();
            for (std::size_t index = 0; index < measured.size(); ++index) {
                if (!(moved.savedAtlas.members[index].owner
                        == source.fence.owner)) continue;
                if (memberIndex != measured.size()) return false;
                memberIndex = index;
            }
            if (memberIndex == measured.size()) return false;
            memberHasSource[memberIndex] = true;
            Bnd_Box bounds;
            BRepBndLib::AddOptimal(measured[memberIndex].original, bounds,
                Standard_False, Standard_False);
            if (bounds.IsVoid() || bounds.IsWhole() || bounds.IsOpen())
                return false;
            int matches = 0;
            TopoDS_Face originalFace;
            for (Standard_Integer faceIndex = 1;
                 faceIndex <= measured[memberIndex].originalFaces.Extent();
                 ++faceIndex) {
                const TopoDS_Face candidate = TopoDS::Face(
                    measured[memberIndex].originalFaces.FindKey(faceIndex));
                dependent_replay::FaceImageGeometricReceipt receipt;
                if (dependent_replay::detail::DeriveFaceImageReceipt(
                        bounds, candidate, metersPerUnit,
                        budget, receipt)
                        != dependent_replay::detail::
                            FaceImageDeriveStatus::Derived)
                    continue;
                decal_layer::Digest proof{};
                if (!dependent_replay::FaceImageReceiptProof(receipt, proof))
                    return false;
                if (proof != source.fence.selectorProof) continue;
                ++matches;
                originalFace = candidate;
            }
            if (matches != 1 || originalFace.IsNull()) return false;
            const TopoDS_Shape copied =
                measured[memberIndex].copier->ModifiedShape(originalFace);
            const Standard_Integer finalFace =
                measured[memberIndex].detachedFaces.FindIndex(copied);
            if (copied.IsNull() || copied.ShapeType() != TopAbs_FACE
                || finalFace <= 0) return false;
            source.memberIndex = memberIndex;
            source.faceIndex = std::size_t(finalFace - 1);
            source.order = sourceIndex;
            observation.sourceDefinitions.push_back(
                measured[memberIndex].definitionIdentifier);
            productionSources.values.push_back(std::move(source));
            ++observation.correspondenceCount;
        }
        for (std::size_t index = 0; index < measured.size(); ++index)
            if (!memberHasSource[index]) ++observation.originalOnlyCount;
        if (productionSources.size() != moved.sources.size()
            || observation.originalOnlyCount == 0) return false;

        std::vector<asset_atlas::build::FinalMemberInput> inputs;
        decal_layer::bake::accounting::Ticket inputsTicket;
        if (!ReserveProtectedVector(inputs, inputsTicket, ledger.view(),
                moved.members.members.size(),
                decal_layer::bake::accounting::Retention::Scratch,
                decal_layer::bake::accounting::FailureSite::
                    ExportMemberStorage)) return false;
        observation.failureStage = "final-member-inputs";
        for (std::size_t index = 0;
             index < moved.members.members.size(); ++index) {
            const auto& member = moved.members.members[index];
            retained_solid::Record retained;
            retained_finishing::SourceRevision observed;
            if (!retained_finishing::producer::detail::Source(
                    document, member.slot.owner, observed, nullptr, &retained)
                || !(observed == member.slot.source)) return false;
            std::atomic_bool cancelled{false};
            meshcopy::CurrentTessellationCopy copy;
            if (meshcopy::PrepareCurrentTessellationCopy(
                    retained.current, copy, cancelled)
                    != meshcopy::PreparationResult::Ready) return false;
            asset_atlas::build::FinalMemberInput input;
            input.savedMember = member.slot;
            input.authority = member.capture;
            if (!retained_finishing::producer::detail::Triangles(
                    copy, input.triangles, input.faces)) return false;
            inputs.push_back(std::move(input));
        }
        for (const auto& source : productionSources)
            if (source.memberIndex >= inputs.size()
                || source.faceIndex >= inputs[source.memberIndex].faces.size())
                return false;

        painted_atlas_bake::owner::ExportBake baked;
        std::string diagnosis;
        const asset_atlas::build::Settings settings{
            moved.savedAtlas.resolutionTexels,
            moved.savedAtlas.gutterTexels};
        observation.failureStage = "all-member-bake";
        const auto bakeOutcome = painted_atlas_bake::owner::
            BuildAndBakeForExport(moved, productionSources, inputs,
                settings, baked, diagnosis);
        if (bakeOutcome != painted_atlas_bake::owner::Outcome::Prepared) {
            observation.failureStage += "-"
                + std::to_string(std::uint8_t(bakeOutcome)) + "-"
                + diagnosis.substr(0, 96);
            return false;
        }
        observation.assignmentCount = baked.assignments.size();
        observation.roleCount = baked.outputs.size();
        observation.resolution = std::uint64_t(baked.atlas.resolutionTexels);
        observation.gutter = std::uint64_t(baked.atlas.gutterTexels);
        observation.allMemberBake = baked.assignments.size() == inputs.size()
            && baked.atlas.members.size() == inputs.size()
            && !baked.outputs.empty();
        observation.oneSharedBake = observation.allMemberBake
            && painted_atlas_bake::Nonzero(baked.bake.bakeProof)
            && painted_atlas_bake::Nonzero(baked.atlas.layoutProof);

        observation.failureStage = "canonical-recheck";
        asset_atlas::persistence::Record observedAtlas;
        painted_atlas_bake::persistence::Record observedBake;
        observation.canonicalUnchanged =
            asset_atlas::persistence::Read(
                document, persisted.definition.key, observedAtlas)
            && observedAtlas.value
            && observedAtlas.value->bytes == moved.canonicalAtlasBytes
            && painted_atlas_bake::persistence::Read(
                document, persisted.definition.key, observedBake)
                == painted_atlas_bake::persistence::ReadState::Present
            && observedBake.definition == moved.savedBake;

        moved.reset();
        observation.outputSurvivedCaptureReset = !baked.outputs.empty()
            && baked.assignments.size() == inputs.size()
            && ledger.recheck(
                decal_layer::bake::accounting::FailureSite::
                    ProtectedRecheckStorage);
        const bool completed = observation.detachedAuthority
            && observation.canonicalUnchanged
            && observation.allMemberBake
            && observation.oneSharedBake
            && observation.outputSurvivedCaptureReset;
        if (completed) observation.failureStage.clear();
        return completed;
    } catch (...) {
        observation = {};
        return false;
    }
}

bool DebugProduceSavedGroupFinalResultImpl(
    const Handle(OcctDocument)& privateDocument,
    const SceneSnapshot& wholeCommittedScene,
    const bool selectedObjectsOnly,
    const std::function<void(const TopoDS_Shape&)>& meshPrivateSurfaces,
    const std::function<bool()>& cancelled,
    DebugSavedGroupFinalObservation& observation,
    DebugP2bObservationDiagnostic* arenaDiagnostic,
    DebugP2bAdmissionDiagnostic* admissionDiagnostic) noexcept {
    observation = {};
    observation.selectedObjectsOnly = selectedObjectsOnly;
    DebugP2bObserverSession arenaSession(arenaDiagnostic);
    try {
        observation.failureStage = "entry";
        if (privateDocument.IsNull() || !meshPrivateSurfaces
            || !cancelled || SavedGroupCancelled(cancelled)) return false;
        const Handle(TDocStd_Document)& document = privateDocument->Document();
        if (document.IsNull() || document->HasOpenCommand()) return false;
        Standard_Real observationUnit = 0;
        XCAFDoc_DocumentTool::GetLengthUnit(document, observationUnit);

        std::vector<asset_atlas::persistence::Record> records;
        if (!asset_atlas::persistence::ReadAll(document, records)
            || records.size() != 1 || !records.front().value) return false;
        arenaSession.start();
        const asset_atlas::Key strictKey =
            records.front().value->definition.key;
        const auto* layoutObserver =
            arenaSession.layoutObserver(0, strictKey);
        const auto* bakeObserver = arenaSession.bakeObserver(0);
        observation.strictKey = retained_solid::UUIDText(strictKey.document)
            + "/" + retained_solid::UUIDText(strictKey.atlas);

        // The concrete ledger dominates the group, result and every inherited
        // capture view for the whole transaction.
        OperationLedger operation;
        DebugP2bAdmissionControl admission(admissionDiagnostic);
        admission.begin(operation, strictKey);
        const auto accounting = admissionDiagnostic
            ? admission.view() : operation.view();
        SavedGroupOwner group;
        if (!operation.bindTopology(group.budget,
                decal_layer::bake::accounting::FailureSite::ContextControl))
            return false;
        painted_atlas_bake::owner::ExportCapture capture;
        observation.failureStage = "strict-capture";
        if (painted_atlas_bake::owner::CaptureForExport(
                capture, document, strictKey, accounting)
                != painted_atlas_bake::owner::Outcome::Prepared
            || capture.operation.valid()
            || capture.operationView().context != accounting.context)
            return false;
        admission.requireContext(capture.operationView().context);

        std::string diagnosis;
        observation.failureStage = "saved-group-preparation";
        if (!PrepareSavedGroupOwner(operation, accounting, std::move(capture),
                privateDocument, cancelled, group, diagnosis)) {
            observation.failureStage += "-" + diagnosis;
            return false;
        }
        observation.measuredCopyCount = group.measured.size();
        for (const auto& member : group.measured) {
            observation.memberDefinitions.push_back(
                member.definitionIdentifier);
            observation.savedTriangleCounts.push_back(
                member.savedTriangleCount);
        }
        for (const auto& source : group.productionSources)
            observation.sourceOrigins.push_back(
                std::uint8_t(source.origin));

        observation.failureStage = "native-final-mesh";
        BRep_Builder compoundBuilder;
        TopoDS_Compound compound;
        compoundBuilder.MakeCompound(compound);
        for (const auto& member : group.measured)
            compoundBuilder.Add(compound, member.detached);
        meshPrivateSurfaces(compound);
        if (SavedGroupCancelled(cancelled)) return false;

        observation.failureStage = "final-definition-extraction";
        std::vector<DefinitionData> definitions;
        definitions.reserve(group.measured.size());
        for (std::size_t index = 0; index < group.measured.size(); ++index) {
            DefinitionData definition;
            definition.label = group.capture.members.members[index].ownerLabel;
            definition.shape = group.measured[index].detached;
            definition.representation =
                privateDocument->GeometryRepresentationForLabel(
                    definition.label);
            if (definition.representation
                    == OcctGeometryRepresentation::Invalid
                || !ExtractDefinitionGeometry(definition.label,
                    group.measured[index].definitionIdentifier, 0,
                    definition)) return false;
            observation.finalTriangleCounts.push_back(
                definition.mesh.indices.size() / 3U);
            observation.finalCornerCounts.push_back(
                definition.mesh.indices.size());
            for (const auto& primitive : definition.mesh.primitives) {
                observation.planeInput = observation.planeInput
                    || primitive.analyticSourceFace.surfaceType
                        == provenance::kSurfaceTypePlane;
                observation.cylinderInput = observation.cylinderInput
                    || primitive.analyticSourceFace.surfaceType
                        == provenance::kSurfaceTypeCylinder;
            }
            if (observation.cylinderInput
                && observation.finalTriangleCounts.back()
                    != observation.savedTriangleCounts[index])
                observation.changedCylinderInput = true;
            definitions.push_back(std::move(definition));
        }

        SavedGroupOccurrenceScope occurrenceScope;
        for (std::size_t index = 0;
             index < wholeCommittedScene.instances.size(); ++index) {
            const auto& instance = wholeCommittedScene.instances[index];
            if (instance.meshIndex >= wholeCommittedScene.meshes.size()
                || (selectedObjectsOnly && !instance.selected)) continue;
            const auto& definition =
                wholeCommittedScene.meshes[instance.meshIndex].definitionIdentifier;
            if (std::find(observation.memberDefinitions.begin(),
                    observation.memberDefinitions.end(), definition)
                    == observation.memberDefinitions.end()) continue;
            occurrenceScope.entries.push_back({instance.entityIdentifier,
                definition, index, instance.worldFromObject});
        }
        observation.occurrenceCount = occurrenceScope.entries.size();

        observation.failureStage = "saved-group-build";
        std::shared_ptr<const SavedGroupFinalResult> result;
        const auto outcome = BuildSavedGroupForExport(group, definitions,
            occurrenceScope, cancelled, result, diagnosis,
            layoutObserver, bakeObserver);
        if (outcome != painted_atlas_bake::owner::Outcome::Prepared) {
            observation.failureStage += "-"
                + std::to_string(std::uint8_t(outcome)) + "-" + diagnosis;
            return false;
        }
        arenaSession.commitS2(0);
        const SavedGroupFinalResult* first =
            LookupSavedGroupFinalResult(group, strictKey);
        const SavedGroupFinalResult* second =
            LookupSavedGroupFinalResult(group, strictKey);
        if (!first || first != second || first != result.get()) {
            observation.failureStage = "strict-key-lookup";
            return false;
        }
        observation.sharedResultIdentity = true;
        observation.fullSavedMembership =
            first->memberDefinitions == observation.memberDefinitions
            && first->bake.atlas.members.size() == group.measured.size();
        observation.assignmentCount = first->bake.assignments.size();
        for (const auto& assignment : first->bake.assignments)
            observation.assignmentCornerCounts.push_back(
                assignment.corners.size());
        observation.outputCount = first->bake.outputs.size();
        for (const auto& baked : first->bake.outputs)
            observation.outputPNGs.push_back(baked.png);
        observation.resolution = first->bake.atlas.resolutionTexels;
        observation.gutter = first->bake.atlas.gutterTexels;
        observation.retainedLayout = first->bake.storage
            && !first->bake.storage->layout.charts.empty()
            && first->bake.storage->layout.chartMembers.size()
                == first->bake.storage->layout.charts.size()
            && first->bake.storage->layout.chartFaces.size()
                == first->bake.storage->layout.charts.size();
        observation.layoutChartCount = first->bake.storage
            ? first->bake.storage->layout.charts.size() : 0;
        observation.exactFaceCorrespondence = true;
        for (const auto& source : group.productionSources) {
            if (source.faceIndex == std::numeric_limits<std::size_t>::max())
                continue;
            observation.exactFaceCorrespondence =
                observation.exactFaceCorrespondence
                && source.memberIndex < definitions.size()
                && source.faceIndex < std::size_t(
                    definitions[source.memberIndex].faces.Extent());
        }
        bool completeCorners = observation.assignmentCornerCounts.size()
            == observation.finalCornerCounts.size();
        for (std::size_t index = 0;
             completeCorners && index < observation.finalCornerCounts.size();
             ++index)
            completeCorners = observation.assignmentCornerCounts[index]
                == observation.finalCornerCounts[index];
        observation.complete = observation.fullSavedMembership
            && observation.exactFaceCorrespondence
            && observation.planeInput && observation.cylinderInput
            && observation.changedCylinderInput
            && observation.retainedLayout
            && observation.sharedResultIdentity
            && observation.assignmentCount == group.measured.size()
            && observation.outputCount == 5
            && observation.resolution == 2048
            && observation.gutter == 4
            && completeCorners;
        arenaSession.retainP5Group(0, group, definitions, *result);
        arenaSession.retainP6Group(0, group, *result);
        arenaSession.retainP8SingleGroup();
        admission.requireContext(group.capture.operationView().context);
        admission.retainComparison(group, *result);
        admission.markProductComplete(observation.complete);
        arenaSession.projectWire(observationUnit);
        if (observation.complete) observation.failureStage.clear();
        return observation.complete;
    } catch (const std::exception& error) {
        observation.failureStage += "-exception-";
        observation.failureStage += error.what();
        return false;
    } catch (...) {
        observation.failureStage += "-exception";
        return false;
    }
}

bool OcctSceneSnapshotBuilder::DebugProduceSavedGroupFinalResult(
    const Handle(OcctDocument)& privateDocument,
    const SceneSnapshot& wholeCommittedScene,
    const bool selectedObjectsOnly,
    const std::function<void(const TopoDS_Shape&)>& meshPrivateSurfaces,
    const std::function<bool()>& cancelled,
    DebugSavedGroupFinalObservation& observation) noexcept {
    return DebugProduceSavedGroupFinalResultImpl(privateDocument,
        wholeCommittedScene, selectedObjectsOnly, meshPrivateSurfaces,
        cancelled, observation, nullptr, nullptr);
}

bool DebugProduceSavedGroupFinalResultObserved(
    const Handle(OcctDocument)& privateDocument,
    const SceneSnapshot& wholeCommittedScene,
    const bool selectedObjectsOnly,
    const std::function<void(const TopoDS_Shape&)>& meshPrivateSurfaces,
    const std::function<bool()>& cancelled,
    DebugSavedGroupFinalObservation& observation,
    NSDictionary<NSString*, id>** extraObservation) noexcept {
    DebugP2bObservationDiagnostic diagnostic = DebugP2bBeginDiagnostic(
        DebugP2bObservationEnabled());
    DebugP2bAdmissionDiagnostic admission;
    const bool completed = DebugProduceSavedGroupFinalResultImpl(
        privateDocument, wholeCommittedScene, selectedObjectsOnly,
        meshPrivateSurfaces, cancelled, observation, &diagnostic, &admission);
    if (extraObservation) {
        NSDictionary<NSString*, id>* arena =
            DebugP2bDiagnosticDictionary(diagnostic) ?: @{};
        NSMutableDictionary<NSString*, id>* result = [arena mutableCopy];
        result[@"admission"] = DebugP2bAdmissionDictionary(admission) ?: @{};
        *extraObservation = result;
    }
    return completed;
}

bool ProduceSavedProducerBatchImpl(
    const Handle(OcctDocument)& privateDocument,
    const SceneSnapshot& wholeCommittedScene,
    const std::function<void(const TopoDS_Shape&)>& meshPrivateSurfaces,
    const std::function<bool()>& cancelled,
    DebugSavedProducerBatchObservation& observation,
    DebugSavedCompleteAssemblyObservation* completeAssembly,
    DebugP2bObservationDiagnostic* arenaDiagnostic) noexcept {
    observation = {};
    DebugP2bObserverSession arenaSession(arenaDiagnostic);
    if (completeAssembly) {
        *completeAssembly = {};
        completeAssembly->observationWired = true;
        ++completeAssembly->entries[0];
    }
    using Outcome = painted_atlas_bake::owner::Outcome;
    try {
        observation.failureStage = "entry";
        if (privateDocument.IsNull()) {
            observation.failureStage = "entry-private-document";
            return false;
        }
        if (!meshPrivateSurfaces || !cancelled
            || SavedGroupCancelled(cancelled)) {
            observation.failureStage = "entry-callback";
            return false;
        }
        const Handle(TDocStd_Document)& document = privateDocument->Document();
        Standard_Real observationUnit = 0;
        XCAFDoc_DocumentTool::GetLengthUnit(document, observationUnit);
        std::vector<asset_atlas::persistence::Record> records;
        if (document.IsNull() || document->HasOpenCommand()) {
            observation.failureStage = "entry-document-state";
            return false;
        }
        if (completeAssembly) ++completeAssembly->entries[1];
        if (!asset_atlas::persistence::ReadAll(document, records)) {
            observation.failureStage = "entry-record-read";
            return false;
        }
        if (records.size() != 2) {
            observation.failureStage = "entry-record-count-"
                + std::to_string(records.size());
            return false;
        }
        if (!records[0].value || !records[1].value) {
            observation.failureStage = "entry-record-value";
            return false;
        }
        arenaSession.start();
        std::sort(records.begin(), records.end(), [](const auto& first,
                const auto& second) {
            return first.value->definition.key.atlas
                < second.value->definition.key.atlas;
        });
        std::array<const asset_atlas::build::DebugLayoutObserver*, 2>
            layoutObservers{};
        std::array<const painted_atlas_bake::kernel::DebugBakeObserver*, 2>
            bakeObservers{};
        for (std::size_t index = 0; index < layoutObservers.size(); ++index)
            layoutObservers[index] = arenaSession.layoutObserver(
                index, records[index].value->definition.key);
        for (std::size_t index = 0; index < bakeObservers.size(); ++index)
            bakeObservers[index] = arenaSession.bakeObserver(index);

        OperationLedger operation;
        const auto accounting = arenaSession.accountingView(operation.view(),
            std::uint64_t(reinterpret_cast<std::uintptr_t>(&operation)));
        arenaSession.lifetime(1, 1, 0, 0, operation.totalLive());
        if (completeAssembly) ++completeAssembly->entries[2];
        std::array<SavedGroupOwner, 2> groups;
        retained_edge_treatment::ReplayBudget batchBudget;
        observation.failureStage = "batch-topology";
        if (!operation.bindTopology(batchBudget,
                decal_layer::bake::accounting::FailureSite::ContextControl))
            return false;
        for (std::size_t index = 0; index < groups.size(); ++index) {
            const auto& key = records[index].value->definition.key;
            arenaSession.accountingGroup(&key);
            observation.strictKeys.push_back(
                retained_solid::UUIDText(key.document) + "/"
                + retained_solid::UUIDText(key.atlas));
            painted_atlas_bake::owner::ExportCapture capture;
            observation.failureStage = "strict-capture-" +
                std::to_string(index);
            if (painted_atlas_bake::owner::CaptureForExport(
                    capture, document, key, accounting)
                    != Outcome::Prepared
                || capture.operationView().context
                    != accounting.context) return false;
            if (completeAssembly) ++completeAssembly->entries[3];
            std::string diagnosis;
            observation.failureStage = "group-preparation-" +
                std::to_string(index);
            if (!PrepareSavedGroupOwner(operation, accounting,
                    std::move(capture),
                    privateDocument, cancelled, groups[index], diagnosis,
                    &batchBudget)) {
                observation.failureStage += "-" + diagnosis;
                return false;
            }
            arenaSession.lifetime(2, 2,
                groups[index].capture.canonicalAtlasBytes.size()
                    + groups[index].capture.canonicalBakeBytes.size(),
                groups[index].measuredVectorTicket.bytes
                    + groups[index].productionSources.vectorTicket.bytes,
                operation.totalLive());
            observation.memberCounts.push_back(
                groups[index].measured.size());
            observation.measuredCopyCount += groups[index].measured.size();
            if (completeAssembly)
                completeAssembly->entries[4] += groups[index].measured.size();
            for (const auto& witness : groups[index].capture.sources.rawSlots) {
                ++observation.rawSlotCount;
                if (witness.present) ++observation.presentSlotCount;
                else ++observation.absentSlotCount;
                observation.shadowedByteCount +=
                    witness.shadowedSource.envelope.originalBytes.size()
                    + witness.shadowedSource.envelope.workingBytes.size();
            }
            const auto& captured = groups[index].capture.sources.values;
            for (std::size_t left = 0;
                 left < captured.size()
                    && !observation.descriptorDifferenceDetected; ++left)
                for (std::size_t right = left + 1;
                     right < captured.size(); ++right)
                    if (!(captured[left].fence == captured[right].fence)) {
                        observation.descriptorDifferenceDetected = true;
                        break;
                    }
            auto moved = std::move(groups[index].capture.sources);
            groups[index].capture.sources = std::move(moved);
            observation.rawAuthorityRetained =
                observation.rawAuthorityRetained
                || !groups[index].capture.sources.rawSlots.empty();
        }
        observation.disjointMembership = groups[0].measured.size() == 2
            && groups[1].measured.size() == 1
            && groups[0].capture.savedAtlas.members[0].owner
                != groups[1].capture.savedAtlas.members[0].owner
            && groups[0].capture.savedAtlas.members[1].owner
                != groups[1].capture.savedAtlas.members[0].owner;

        observation.failureStage = "native-final-mesh";
        BRep_Builder compoundBuilder;
        TopoDS_Compound compound;
        compoundBuilder.MakeCompound(compound);
        for (const auto& group : groups)
            for (const auto& member : group.measured)
                compoundBuilder.Add(compound, member.detached);
        meshPrivateSurfaces(compound);
        if (completeAssembly) ++completeAssembly->entries[5];
        if (SavedGroupCancelled(cancelled)) return false;

        std::array<std::vector<DefinitionData>, 2> definitions;
        std::array<SavedGroupOccurrenceScope, 2> occurrences;
        for (std::size_t groupIndex = 0;
             groupIndex < groups.size(); ++groupIndex) {
            definitions[groupIndex].reserve(groups[groupIndex].measured.size());
            for (std::size_t memberIndex = 0;
                 memberIndex < groups[groupIndex].measured.size(); ++memberIndex) {
                DefinitionData definition;
                definition.label = groups[groupIndex].capture.members
                    .members[memberIndex].ownerLabel;
                definition.shape = groups[groupIndex].measured[memberIndex].detached;
                definition.representation =
                    privateDocument->GeometryRepresentationForLabel(
                        definition.label);
                if (definition.representation
                        == OcctGeometryRepresentation::Invalid
                    || !ExtractDefinitionGeometry(definition.label,
                        groups[groupIndex].measured[memberIndex]
                            .definitionIdentifier,
                        0, definition)) return false;
                definitions[groupIndex].push_back(std::move(definition));
            }
            if (!completeAssembly) {
                for (std::size_t instanceIndex = 0;
                     instanceIndex < wholeCommittedScene.instances.size();
                     ++instanceIndex) {
                    const auto& instance =
                        wholeCommittedScene.instances[instanceIndex];
                    if (instance.meshIndex >= wholeCommittedScene.meshes.size())
                        continue;
                    const auto& definition = wholeCommittedScene.meshes[
                        instance.meshIndex].definitionIdentifier;
                    for (const auto& member : groups[groupIndex].measured)
                        if (member.definitionIdentifier == definition)
                            occurrences[groupIndex].entries.push_back({
                                instance.entityIdentifier, definition,
                                instanceIndex, instance.worldFromObject});
                }
            }
        }

        if (completeAssembly) {
            const std::string documentIdentifier =
                privateDocument->DocumentIdentifier();
            XCAFPrs_DocumentExplorer explorer(document,
                XCAFPrs_DocumentExplorerFlags_OnlyLeafNodes,
                XCAFPrs_Style());
            std::size_t sourceInstanceIndex = 0;
            for (; explorer.More(); explorer.Next(), ++sourceInstanceIndex) {
                const auto& node = explorer.Current();
                const TDF_Label definitionLabel = node.RefLabel.IsNull()
                    ? node.Label : node.RefLabel;
                const std::string definition =
                    privateDocument->DefinitionIdentifierForLabel(
                        definitionLabel);
                std::size_t groupIndex = groups.size();
                const DefinitionData* definitionData = nullptr;
                for (std::size_t candidate = 0;
                     candidate < groups.size(); ++candidate) {
                    for (std::size_t memberIndex = 0;
                         memberIndex < groups[candidate].measured.size();
                         ++memberIndex) {
                        if (groups[candidate].measured[memberIndex]
                                .definitionIdentifier == definition) {
                            if (definitionData) return false;
                            groupIndex = candidate;
                            definitionData = &definitions[candidate][memberIndex];
                        }
                    }
                }
                if (groupIndex == groups.size()) continue;
                if (explorer.CurrentDepth() < 0
                    || explorer.CurrentDepth() >= kMaxOccurrenceDepth)
                    return false;
                std::vector<std::string> path;
                for (Standard_Integer depth = 0;
                     depth <= explorer.CurrentDepth(); ++depth) {
                    const std::string identifier =
                        privateDocument->EntityIdentifierForLabel(
                            explorer.Current(depth).Label);
                    if (identifier.empty()) return false;
                    path.push_back(identifier);
                }
                const std::string occurrence = DeriveOccurrenceIdentifier(
                    documentIdentifier, path);
                gp_Trsf objectTransform;
                if (!definitionData
                    || !privateDocument->TryObjectTransformForLabel(
                        definitionLabel, objectTransform)) return false;
                gp_Trsf worldTransform = objectTransform.Multiplied(
                    node.Location.Transformation());
                gp_Trsf meshOrigin;
                meshOrigin.SetTranslation(gp_Vec(
                    definitionData->sourceOrigin.x,
                    definitionData->sourceOrigin.y,
                    definitionData->sourceOrigin.z));
                worldTransform.Multiply(meshOrigin);
                Matrix4d transform;
                if (occurrence.empty()
                    || !MatrixFromTransform(worldTransform, transform))
                    return false;
                Matrix4d objectMatrix, explorerMatrix, originMatrix;
                if (MatrixFromTransform(objectTransform, objectMatrix)
                    && MatrixFromTransform(node.Location.Transformation(),
                        explorerMatrix)
                    && MatrixFromTransform(meshOrigin, originMatrix))
                    arenaSession.retainOccurrence(groupIndex,
                        sourceInstanceIndex, transform, objectMatrix,
                        explorerMatrix, originMatrix);
                occurrences[groupIndex].entries.push_back({occurrence,
                    definition, sourceInstanceIndex, transform});
                completeAssembly->occurrenceIdentifiers.push_back(occurrence);
                completeAssembly->definitionIdentifiers.push_back(definition);
                completeAssembly->occurrenceTransforms.push_back(
                    transform.values);
            }
            std::set<std::string> selectedEntities;
            for (const auto& instance : wholeCommittedScene.instances)
                if (instance.selected)
                    selectedEntities.insert(instance.entityIdentifier);
            for (const auto& occurrence :
                 completeAssembly->occurrenceIdentifiers)
                if (selectedEntities.count(occurrence) != 0)
                    completeAssembly->selectedOccurrenceIdentifiers.push_back(
                        occurrence);
            arenaSession.retainSelectedOccurrences(
                completeAssembly->selectedOccurrenceIdentifiers);
            bool distinctTransform = false;
            for (std::size_t first = 0;
                 first < completeAssembly->occurrenceTransforms.size(); ++first)
                for (std::size_t second = first + 1;
                     second < completeAssembly->occurrenceTransforms.size();
                     ++second)
                    distinctTransform = distinctTransform
                        || completeAssembly->occurrenceTransforms[first]
                            != completeAssembly->occurrenceTransforms[second];
            const std::set<std::string> expectedOccurrences{
                "01002222-2222-2222-2222-222222222222",
                "01002121-2121-2121-2121-212121212121",
                "01002323-2323-2323-2323-232323232323",
            };
            const std::set<std::string> expectedDefinitions{
                "02002222-2222-2222-2222-222222222222",
                "02002121-2121-2121-2121-212121212121",
                "02002323-2323-2323-2323-232323232323",
            };
            completeAssembly->occurrenceVariantReady =
                completeAssembly->occurrenceIdentifiers.size() == 3
                && std::set<std::string>(
                    completeAssembly->occurrenceIdentifiers.begin(),
                    completeAssembly->occurrenceIdentifiers.end())
                    == expectedOccurrences
                && std::set<std::string>(
                    completeAssembly->definitionIdentifiers.begin(),
                    completeAssembly->definitionIdentifiers.end())
                    == expectedDefinitions
                && completeAssembly->selectedOccurrenceIdentifiers
                    == std::vector<std::string>({
                        "01002121-2121-2121-2121-212121212121"})
                && distinctTransform;
            if (!completeAssembly->occurrenceVariantReady) {
                observation.failureStage = "occurrence-variant-setup";
                return false;
            }
        }

        painted_atlas_bake::owner::AggregateBakePlan aggregate;
        for (std::size_t index = 0; index < groups.size(); ++index) {
            std::string diagnosis;
            observation.failureStage = "plan-prepare-" +
                std::to_string(index);
            arenaSession.accountingGroup(
                &groups[index].capture.savedAtlas.key);
            arenaSession.boundary(DebugP2bEventKind::LayoutBegin);
            const auto outcome = PrepareSavedGroupForBatch(groups[index],
                definitions[index], occurrences[index], cancelled,
                aggregate, diagnosis, layoutObservers[index]);
            arenaSession.boundary(DebugP2bEventKind::LayoutEnd,
                outcome == Outcome::Prepared);
            if (outcome != Outcome::Prepared) {
                observation.failureStage += "-" + diagnosis;
                return false;
            }
        }
        observation.work = {
            aggregate.admittedWork.atlasRoles,
            aggregate.admittedWork.sourcePixels,
            aggregate.admittedWork.maskPixels,
            aggregate.admittedWork.gutter,
            aggregate.admittedWork.encoder};
        observation.failureStage = "plan-seal";
        arenaSession.accountingGroup(nullptr);
        if (!painted_atlas_bake::owner::SealBakePlan(aggregate)) return false;
        observation.oneAggregateSeal = aggregate.sealed
            && aggregate.admittedItems == groups.size();

        std::array<std::shared_ptr<const SavedGroupFinalResult>, 2> results;
        for (std::size_t index = 0; index < groups.size(); ++index) {
            std::string diagnosis;
            observation.failureStage = "plan-execute-" +
                std::to_string(index);
            arenaSession.accountingGroup(
                &groups[index].capture.savedAtlas.key);
            arenaSession.boundary(DebugP2bEventKind::BakeBegin);
            const auto outcome = ExecuteSavedGroupForBatch(groups[index],
                aggregate, cancelled, results[index], diagnosis, true,
                bakeObservers[index]);
            arenaSession.boundary(DebugP2bEventKind::BakeEnd,
                outcome == Outcome::Prepared && results[index] != nullptr);
            if (outcome != Outcome::Prepared || !results[index]) {
                observation.failureStage += "-" + diagnosis;
                return false;
            }
            arenaSession.commitS2(index);
            std::uint64_t outputBytes = 0;
            for (const auto& value : results[index]->bake.outputs)
                outputBytes += value.png.size();
            arenaSession.lifetime(3, 3, outputBytes,
                results[index]->bake.storage->bakeValueStorage.bytes,
                operation.totalLive());
            if (completeAssembly) {
                ++completeAssembly->entries[6];
                ++completeAssembly->entries[7];
            }
            observation.assignmentCounts.push_back(
                results[index]->bake.assignments.size());
            observation.outputCounts.push_back(
                results[index]->bake.outputs.size());
            observation.layoutCount += !results[index]->bake.storage
                || results[index]->bake.storage->layout.charts.empty()
                ? 0 : 1;
        }
        for (const auto& output : results[0]->bake.outputs)
            observation.firstGroupPNGs.push_back(output.png);
        observation.distinctGroupResults = results[0].get()
            != results[1].get();
        observation.sharedWithinGroups =
            LookupSavedGroupFinalResult(groups[0],
                records[0].value->definition.key) == results[0].get()
            && LookupSavedGroupFinalResult(groups[0],
                records[0].value->definition.key) == results[0].get()
            && LookupSavedGroupFinalResult(groups[1],
                records[1].value->definition.key) == results[1].get();
        if (completeAssembly) completeAssembly->entries[8] = 3;
        observation.complete = observation.disjointMembership
            && observation.rawAuthorityRetained
            && observation.descriptorDifferenceDetected
            && observation.shadowedByteCount > 0
            && observation.oneAggregateSeal
            && observation.distinctGroupResults
            && observation.sharedWithinGroups
            && observation.rawSlotCount == 18
            && observation.presentSlotCount == 10
            && observation.absentSlotCount == 8
            && observation.measuredCopyCount == 3
            && observation.assignmentCounts
                == std::vector<std::uint64_t>({2, 1})
            && observation.layoutCount == 2
            && observation.outputCounts.size() == 2
            && observation.outputCounts[0] == 5
            && observation.outputCounts[1] == 1;
        for (std::size_t index = 0; index < groups.size(); ++index)
            arenaSession.retainP5Group(index, groups[index],
                definitions[index], *results[index]);
        for (std::size_t index = 0; index < groups.size(); ++index)
            arenaSession.retainP6Group(index, groups[index], *results[index]);
        arenaSession.accountingGroup(nullptr);
        arenaSession.lifetime(4, 4, 0, 0, operation.totalLive());
        arenaSession.retainP7(operation, aggregate, groups);
        arenaSession.projectWire(observationUnit);
        if (completeAssembly) {
            completeAssembly->batchReady = observation.complete;
            observation.failureStage = "complete-current-assignment-validation-"
                + std::to_string(results[0]->bake.assignments.size());
            completeAssembly->currentAssemblyAccepted =
                !results[0]->finalCornerCounts.empty()
                && ValidateCurrentFinalAssignments(results[0]->bake,
                    results[0]->finalCornerCounts.front());
            if (!completeAssembly->currentAssemblyAccepted) return false;
            completeAssembly->candidateReady = true;
        }
        if (observation.complete) observation.failureStage.clear();
        if (completeAssembly) {
            completeAssembly->operationComplete = true;
            ++completeAssembly->entries[9];
        }
        return observation.complete;
    } catch (const std::exception& error) {
        observation.failureStage += "-exception-";
        observation.failureStage += error.what();
        return false;
    } catch (...) {
        observation.failureStage += "-exception";
        return false;
    }
}

bool OcctSceneSnapshotBuilder::DebugProduceSavedProducerBatch(
    const Handle(OcctDocument)& privateDocument,
    const SceneSnapshot& wholeCommittedScene,
    const std::function<void(const TopoDS_Shape&)>& meshPrivateSurfaces,
    const std::function<bool()>& cancelled,
    DebugSavedProducerBatchObservation& observation) noexcept {
    return ProduceSavedProducerBatchImpl(privateDocument, wholeCommittedScene,
        meshPrivateSurfaces, cancelled, observation, nullptr, nullptr);
}

NSDictionary<NSString *, id> *DebugProduceSavedCompleteAssembly(
    const Handle(OcctDocument)& privateDocument,
    const SceneSnapshot& wholeCommittedScene,
    const std::function<void(const TopoDS_Shape&)>& meshPrivateSurfaces,
    const std::function<bool()>& cancelled) noexcept {
    DebugSavedProducerBatchObservation batch;
    DebugSavedCompleteAssemblyObservation assembly;
    DebugP2bObservationDiagnostic arenaDiagnostic = DebugP2bBeginDiagnostic(
        DebugP2bObservationEnabled());
    const bool completed = ProduceSavedProducerBatchImpl(privateDocument,
        wholeCommittedScene, meshPrivateSurfaces, cancelled, batch, &assembly,
        &arenaDiagnostic);
    const auto numbers = [](const auto& values) {
        NSMutableArray<NSNumber *> *result = [NSMutableArray array];
        for (const auto value : values)
            [result addObject:@(static_cast<unsigned long long>(value))];
        return result;
    };
    const auto doubles = [](const auto& values) {
        NSMutableArray<NSNumber *> *result = [NSMutableArray array];
        for (const auto value : values)
            [result addObject:[NSNumber numberWithDouble:value]];
        return result;
    };
    const auto strings = [](const auto& values) {
        NSMutableArray<NSString *> *result = [NSMutableArray array];
        for (const auto& value : values)
            [result addObject:[NSString stringWithUTF8String:value.c_str()]
                ?: @""];
        return result;
    };
    NSMutableArray<NSArray<NSNumber *> *> *transforms =
        [NSMutableArray array];
    for (const auto& matrix : assembly.occurrenceTransforms)
        [transforms addObject:doubles(matrix)];
    return @{
        @"complete": @(completed),
        @"failureStage": [NSString stringWithUTF8String:
            batch.failureStage.c_str()] ?: @"invalid-stage",
        @"strictKeys": strings(batch.strictKeys),
        @"memberCounts": numbers(batch.memberCounts),
        @"assignmentCounts": numbers(batch.assignmentCounts),
        @"outputCounts": numbers(batch.outputCounts),
        @"work": numbers(batch.work),
        @"rawSlotCount": @(batch.rawSlotCount),
        @"presentSlotCount": @(batch.presentSlotCount),
        @"absentSlotCount": @(batch.absentSlotCount),
        @"shadowedByteCount": @(batch.shadowedByteCount),
        @"measuredCopyCount": @(batch.measuredCopyCount),
        @"layoutCount": @(batch.layoutCount),
        @"observationWired": @(assembly.observationWired),
        @"entryWork": numbers(assembly.entries),
        @"batchReady": @(assembly.batchReady),
        @"occurrenceIdentifiers": strings(
            assembly.occurrenceIdentifiers),
        @"definitionIdentifiers": strings(
            assembly.definitionIdentifiers),
        @"occurrenceTransforms": transforms,
        @"selectedOccurrenceIdentifiers": strings(
            assembly.selectedOccurrenceIdentifiers),
        @"occurrenceVariantReady": @(assembly.occurrenceVariantReady),
        @"candidateReady": @(assembly.candidateReady),
        @"operationComplete": @(assembly.operationComplete),
        @"currentAssemblyAccepted": @(
            assembly.currentAssemblyAccepted),
        @"productPresent": @(assembly.candidateReady),
        @"p2bArena": DebugP2bDiagnosticDictionary(arenaDiagnostic) ?: @{},
        @"p2bRaw": DebugP2bRawDictionary(arenaDiagnostic) ?: @{},
    };
}
#endif

bool PrivateDecalCapture::Impl::recheckProtected(
    const std::function<bool()>& cancelled,
    const decal_layer::bake::accounting::FailureSite boundary) noexcept {
    using FailureSite = decal_layer::bake::accounting::FailureSite;
    using Retention = decal_layer::bake::accounting::Retention;
    using StorageDimension = decal_layer::bake::accounting::StorageDimension;
    try {
        bool isCancelled = !cancelled;
        if (!isCancelled) {
            try { isCancelled = cancelled(); }
            catch (...) { isCancelled = true; }
        }
        if (isCancelled) {
            operationLedger.cancel(FailureSite::Cancellation);
            return false;
        }
        // Early currentness prerequisite: the captured union of standalone
        // SYDL owners and complete saved-atlas groups must be nonempty. An
        // admitted no-SYDL saved group therefore reaches the unchanged
        // nonempty-atlas refusal below instead of being stopped here.
        if (!operationLedger.recheck(boundary)
            || privateDocument.IsNull()
            || !IsValidSceneSnapshot(wholeCommittedScene)
            || (owners.empty() && savedGroups.empty())) return false;
        const Handle(TDocStd_Document)& document = privateDocument->Document();
        if (document.IsNull() || document->HasOpenCommand()
            || privateDocument->DocumentIdentifier() != documentIdentifier)
            return false;
        Standard_Real observedUnit = 0.0;
        XCAFDoc_DocumentTool::GetLengthUnit(document, observedUnit);
        if (observedUnit != metersPerUnit
            || wholeCommittedScene.metersPerUnit != metersPerUnit)
            return false;

        painted_atlas_bake::owner::AtlasReadAdmission atlasAdmission;
        std::vector<asset_atlas::persistence::Record> atlases;
        if (painted_atlas_bake::owner::PreflightAtlasRead(
                document, operationLedger.view(), atlasAdmission,
                FailureSite::ProtectedAtlasRead)
                != painted_atlas_bake::owner::Outcome::Prepared
            || !operationLedger.enterAllocation(
                FailureSite::ProtectedAtlasRead)
            || !asset_atlas::persistence::ReadAll(document, atlases)
            || !atlases.empty()) return false;
        atlasAdmission.reset();

        for (const auto& owner : owners) {
            if (!operationLedger.recheck(boundary)) return false;
            TDF_Label label;
            retained_solid::Record retained;
            if (!retained_finishing::producer::detail::Resolve(
                    document, owner.owner, label, retained)
                || !label.IsEqual(owner.ownerLabel)
                || privateDocument->DefinitionIdentifierForLabel(label)
                    != owner.definitionIdentifier)
                return false;

            ProtectedDefinitionAdmission definitionAdmission;
            decal_layer::Definition definition;
            std::vector<std::uint8_t> canonical;
            if (!PreflightProtectedDefinitionRead(label,
                    operationLedger.view(), definitionAdmission)
                || !operationLedger.enterAllocation(
                    FailureSite::ProtectedDefinitionStorage)
                || decal_layer::persistence::Read(document, label,
                    definition, &canonical, nullptr)
                    != decal_layer::persistence::ReadState::Present
                || definitionAdmission.layerCount != definition.layers.size()
                || definition.layers.capacity() * sizeof(decal_layer::Layer)
                    > definitionAdmission.layers.bytes
                || canonical.capacity() > definitionAdmission.canonical.bytes
                || canonical != owner.canonicalBytes
                || !(definition.owner == owner.owner))
                return false;
            definitionAdmission.readScratch.reset();

            decal_layer::source::Witness source;
            if (!decal_layer::source::CaptureSource(privateDocument,
                    owner.owner, budget, cancelled, source)
                || !decal_layer::source::ExactMatch(definition, source)
                || !(source.owner == owner.source.owner)
                || source.sourceRecipe != owner.source.sourceRecipe
                || source.sourceProof != owner.source.sourceProof
                || source.recipeDigest != owner.source.recipeDigest
                || source.geometryDigest != owner.source.geometryDigest
                || source.placementDigest != owner.source.placementDigest)
                return false;

            decal_layer::bake::accounting::Ticket finishingScratch;
            retained_finishing::producer::Capture finishing;
            if (!AcquireProtectedStorage(finishingScratch,
                    operationLedger.view(), StorageDimension::PrivateStorage,
                    sizeof(retained_finishing::MaterialResource) + 48U,
                    Retention::Scratch, FailureSite::ProtectedRecheckStorage)
                || !retained_finishing::producer::CaptureSource(
                    document, owner.owner, finishing)
                || !(finishing.source == owner.savedMember.authority.source)
                || finishing.resourceManifest
                    != owner.savedMember.authority.resourceManifest
                || finishing.resources.size()
                    != owner.savedMember.authority.resources.size())
                return false;
            for (std::size_t index = 0;
                 index < finishing.resources.size(); ++index) {
                if (finishing.resources[index].identity
                        != owner.savedMember.authority.resources[index].identity
                    || finishing.resources[index].content
                        != owner.savedMember.authority.resources[index].content)
                    return false;
            }
            if (owner.paintedSources.size() != definition.layers.size())
                return false;
            for (std::size_t index = 0;
                 index < owner.paintedSources.size(); ++index) {
                const auto& captured = owner.paintedSources[index];
                const auto& layer = definition.layers[index];
                painted_atlas_bake::BindingFence fence;
                fence.owner = owner.owner;
                fence.binding = layer.identifier;
                fence.resource = layer.image.resource;
                fence.selectorProof =
                    decal_layer::bake::IntentReceipt(layer).selectorProof;
                fence.bindingProof = definition.layerProof;
                fence.originalContent = layer.image.originalContent;
                fence.workingContent = layer.image.normalizedContent;
                fence.role = layer.image.role;
                fence.colorSpace = layer.image.colorSpace;
                if (!(fence == captured.fence) || captured.order != index
                    || captured.memberIndex != 0
                    || captured.origin
                        != painted_atlas_bake::kernel::SourceOrigin::OrderedLayer
                    || captured.materialSlot
                        != painted_atlas_bake::kernel::MaterialSlot::None
                    || captured.maskPresent != layer.mask.present)
                    return false;

                painted_atlas_bake::owner::ResourceReadAdmission read;
                face_image::ResourceEnvelope envelope;
                if (painted_atlas_bake::owner::PreflightResourceRead(
                        document, fence.resource, operationLedger.view(), read)
                        != painted_atlas_bake::owner::Outcome::Prepared
                    || !operationLedger.enterAllocation(
                        FailureSite::ResourceReadMaterialize)
                    || !face_image::owner::ReadResource(
                        document, fence.resource, envelope)
                    || !read.selected
                    || envelope.originalBytes.capacity()
                        > read.originalBytes.bytes
                    || envelope.workingBytes.capacity()
                        > read.workingBytes.bytes
                    || !(envelope == captured.envelope))
                    return false;
                if (captured.maskPresent) {
                    painted_atlas_bake::owner::ResourceReadAdmission maskRead;
                    face_image::ResourceEnvelope mask;
                    if (painted_atlas_bake::owner::PreflightResourceRead(
                            document, layer.mask.image.resource,
                            operationLedger.view(), maskRead)
                            != painted_atlas_bake::owner::Outcome::Prepared
                        || !operationLedger.enterAllocation(
                            FailureSite::ResourceReadMaterialize)
                        || !face_image::owner::ReadResource(document,
                            layer.mask.image.resource, mask)
                        || !maskRead.selected
                        || mask.originalBytes.capacity()
                            > maskRead.originalBytes.bytes
                        || mask.workingBytes.capacity()
                            > maskRead.workingBytes.bytes
                        || !(mask == captured.maskEnvelope))
                        return false;
                }
            }

            const TopoDS_Shape shape = XCAFDoc_ShapeTool::GetShape(label);
            Bnd_Box stageBox;
            BRepBndLib::AddOptimal(
                shape, stageBox, Standard_False, Standard_False);
            decal_layer::bake::accounting::Ticket receiptScratch;
            if (shape.IsNull() || stageBox.IsVoid() || stageBox.IsWhole()
                || stageBox.IsOpen()
                || !AcquireProtectedStorage(receiptScratch,
                    operationLedger.view(), StorageDimension::PrivateStorage,
                    4096U, Retention::Scratch,
                    FailureSite::ProtectedRecheckStorage))
                return false;
            for (const auto& receiver : owner.receivers) {
                dependent_replay::FaceImageGeometricReceipt observed;
                if (dependent_replay::detail::DeriveFaceImageReceipt(stageBox,
                        receiver.originalFace, metersPerUnit, budget, observed)
                        != dependent_replay::detail::
                            FaceImageDeriveStatus::Derived)
                    return false;
                decal_layer::Digest proof{};
                if (!dependent_replay::FaceImageReceiptProof(observed, proof)
                    || proof != receiver.receipt.selectorProof)
                    return false;
                dependent_replay::FaceImageGeometricReceipt resolved;
                TopoDS_Face observedFace;
                if (dependent_replay::detail::ResolveFaceImageReceipt(
                        shape, observed.intent, metersPerUnit, budget,
                        resolved, observedFace)
                        != retained_face_selector::Refusal::None
                    || !(resolved == observed)
                    || !observedFace.IsSame(receiver.originalFace))
                    return false;
            }

            bool occurrenceFound = false;
            for (const auto& instance : wholeCommittedScene.instances) {
                if (instance.role != RenderRole::Model
                    || instance.meshIndex >= wholeCommittedScene.meshes.size())
                    continue;
                const auto& mesh = wholeCommittedScene.meshes[instance.meshIndex];
                const std::string& master =
                    mesh.paintedAtlasMasterDefinitionIdentifier.empty()
                    ? mesh.definitionIdentifier
                    : mesh.paintedAtlasMasterDefinitionIdentifier;
                occurrenceFound = occurrenceFound
                    || master == owner.definitionIdentifier;
            }
            if (!occurrenceFound) return false;
        }

        std::vector<decal_math::DecalWorldTriangle> occluders;
        decal_layer::bake::accounting::Ticket occluderTicket;
        Bounds3d bounds;
        decal_layer::Digest proof{};
        if (!decal_math::CaptureDecalOccluders(wholeCommittedScene,
                occluders, bounds, proof, operationLedger.view(),
                occluderTicket)
            || proof != occluderProof)
            return false;
        return operationLedger.recheck(boundary);
    } catch (const std::bad_alloc&) {
        operationLedger.allocationFailure(boundary);
        return false;
    } catch (...) {
        operationLedger.refuse(boundary);
        return false;
    }
}

struct ReturnedPrivateExportOwner final {
    PrivateDecalCapturePointer capture;
    PrivateExportDecalArtifact artifact;

    ReturnedPrivateExportOwner(PrivateDecalCapturePointer&& protectedCapture,
        PrivateExportDecalArtifact&& protectedArtifact) noexcept
        : capture(std::move(protectedCapture)),
          artifact(std::move(protectedArtifact)) {}
};

struct ReturnedPrivateExportOwnerDeleter final {
    ReturnedPrivateExportOwner* owner = nullptr;

    void operator()(ReturnedPrivateExportOwner* value) const noexcept {
        delete value;
    }
};

SavedGroupAllMemberLayoutRead OcctSceneSnapshotBuilder::
SavedGroupAllMemberLayoutForReturnedScene(
    const SnapshotPointer& returnedScene) noexcept {
    SavedGroupAllMemberLayoutRead result;
    try {
        const auto* deleter = std::get_deleter<
            ReturnedPrivateExportOwnerDeleter>(returnedScene);
        if (!deleter || !deleter->owner
            || returnedScene.get() != deleter->owner->artifact.scene.get())
            return result;
        const auto* record = deleter->owner->artifact.savedGroupLayout.get();
        if (record)
            result.record = std::shared_ptr<const SavedGroupAllMemberLayoutRecord>(
                returnedScene, record);
        result.reason = deleter->owner->artifact.savedGroupLayoutReason;
        return result;
    } catch (...) {
        return {};
    }
}

PrivateExportRawEvidenceRead OcctSceneSnapshotBuilder::
OperationOwnedRawEvidenceForReturnedScene(
    const SnapshotPointer& returnedScene) noexcept {
    PrivateExportRawEvidenceRead result;
    try {
        const auto* deleter = std::get_deleter<
            ReturnedPrivateExportOwnerDeleter>(returnedScene);
        if (!deleter || !deleter->owner
            || returnedScene.get() != deleter->owner->artifact.scene.get())
            return result;
        const auto* record = deleter->owner->artifact.rawEvidence.get();
        if (!record || !record->complete
            || record->returnedSceneAlias != returnedScene.get())
            return result;
        result.record = std::shared_ptr<const PrivateExportRawEvidenceRecord>(
            returnedScene, record);
        return result;
    } catch (...) {
        return {};
    }
}

#ifdef DEBUG
//! Typed text for the inherited capture outcome; the enum stays the
//! authority and this only names the same values for the bounded diagnostic.
const char* SavedAtlasCaptureOutcomeText(
    const painted_atlas_bake::owner::Outcome outcome) noexcept {
    using Outcome = painted_atlas_bake::owner::Outcome;
    switch (outcome) {
        case Outcome::Prepared: return "prepared";
        case Outcome::Committed: return "committed";
        case Outcome::Refused: return "refused";
        case Outcome::StaleSource: return "stale-source";
        case Outcome::StaleBinding: return "stale-binding";
        case Outcome::MissingResource: return "missing-resource";
        case Outcome::ForeignResource: return "foreign-resource";
        case Outcome::OverBudget: return "over-budget";
        case Outcome::UnsupportedSurface: return "unsupported-surface";
        case Outcome::OwnerMismatch: return "owner-mismatch";
        case Outcome::Busy: return "busy";
        case Outcome::Malformed: return "malformed";
        case Outcome::PersistenceFailure: return "persistence-failure";
        case Outcome::Absent: return "absent";
    }
    return "unknown";
}

bool DebugSavedAtlasCaptureFaultApplies(
    const DebugPrivateExportDecalFault fault) noexcept {
    switch (fault) {
        case DebugPrivateExportDecalFault::SavedAtlasCaptureMissingBake:
        case DebugPrivateExportDecalFault::SavedAtlasCaptureMalformedBake:
        case DebugPrivateExportDecalFault::SavedAtlasCaptureStaleBinding:
        case DebugPrivateExportDecalFault::SavedAtlasCaptureMissingMember:
        case DebugPrivateExportDecalFault::SavedAtlasCaptureForeignMember:
        case DebugPrivateExportDecalFault::SavedAtlasCaptureDuplicateMember:
        case DebugPrivateExportDecalFault::SavedAtlasCaptureForeignRawSlot:
        case DebugPrivateExportDecalFault::SavedAtlasCaptureMalformedResource:
            return true;
        default:
            return false;
    }
}

//! Bounded field token for a named saved-atlas capture corruption fault, or
//! nullptr when no such fault is armed.
const char* DebugSavedAtlasCaptureFaultField(
    const DebugPrivateExportDecalFault fault) noexcept {
    switch (fault) {
        case DebugPrivateExportDecalFault::SavedAtlasCaptureMissingBake:
        case DebugPrivateExportDecalFault::SavedAtlasCaptureMalformedBake:
            return "SYEB";
        case DebugPrivateExportDecalFault::SavedAtlasCaptureStaleBinding:
            return "SYEB.binding";
        case DebugPrivateExportDecalFault::SavedAtlasCaptureForeignRawSlot:
            return "SYFI";
        case DebugPrivateExportDecalFault::SavedAtlasCaptureMalformedResource:
            return "SYFR";
        default:
            return nullptr;
    }
}

//! Named DEBUG-only fault adapters for the saved-atlas pre-capture boundary.
//! Each alters only this operation's private document input inside one
//! committed command; the live document and frozen resources are never
//! touched. cause/field describe the corruption actually applied; the typed
//! refusal itself comes from the real census/capture checkers downstream.
bool DebugCorruptSavedAtlasCaptureInput(
    const Handle(TDocStd_Document)& document,
    const DebugPrivateExportDecalFault fault,
    std::string& cause, std::string& field) noexcept {
    cause.clear();
    field.clear();
    if (!DebugSavedAtlasCaptureFaultApplies(fault)) return false;
    const char* stage = "entry";
    Standard_Integer savedUndoLimit = 0;
    bool undoLimitRaised = false;
    try {
        if (document.IsNull() || document->HasOpenCommand()) return false;
        std::vector<asset_atlas::persistence::Record> records;
        if (!asset_atlas::persistence::ReadAll(document, records)
            || records.size() != 1 || !records.front().value
            || records.front().memberOwners.empty()) {
            field = "adapter-census";
            return false;
        }
        const asset_atlas::Key& key = records.front().value->definition.key;
        const auto& memberOwners = records.front().memberOwners;
        const Standard_GUID entityAttribute(
            "0074F7C2-9EAA-4F89-B2DE-8716E155FF62");
        const Standard_GUID definitionAttribute(
            "3611F2B2-C694-4E12-AED8-A2A97A3D283B");
        // The cold-open operation-private document carries undo disabled, and
        // StageCommitted requires a genuinely open command. Preserve the
        // document's undo setting, enable one bounded command, prove it
        // opened, and restore the setting on every exit below.
        savedUndoLimit = document->GetUndoLimit();
        if (savedUndoLimit < 1) {
            document->SetUndoLimit(1);
            undoLimitRaised = true;
        }
        document->NewCommand();
        if (!document->HasOpenCommand()) {
            if (undoLimitRaised) document->SetUndoLimit(savedUndoLimit);
            field = "adapter-command";
            return false;
        }
        bool applied = false;
        painted_atlas_bake::Definition stagedStale;
        switch (fault) {
            case DebugPrivateExportDecalFault::SavedAtlasCaptureMissingBake: {
                painted_atlas_bake::persistence::Record bake;
                if (painted_atlas_bake::persistence::Read(document, key, bake)
                        == painted_atlas_bake::persistence::ReadState::Present
                    && !bake.label.IsNull()) {
                    bake.label.ForgetAllAttributes(Standard_True);
                    applied = true;
                }
                cause = "missing-bake";
                field = "SYEB";
                break;
            }
            case DebugPrivateExportDecalFault::SavedAtlasCaptureMalformedBake: {
                painted_atlas_bake::persistence::Record bake;
                if (painted_atlas_bake::persistence::Read(document, key, bake)
                        == painted_atlas_bake::persistence::ReadState::Present
                    && !bake.label.IsNull()) {
                    TDataStd_Integer::Set(bake.label,
                        painted_atlas_bake::persistence::VersionID(), 2);
                    applied = true;
                }
                cause = "malformed-bake";
                field = "SYEB";
                break;
            }
            case DebugPrivateExportDecalFault::SavedAtlasCaptureStaleBinding: {
                painted_atlas_bake::persistence::Record bake;
                painted_atlas_bake::Definition modified;
                painted_atlas_bake::Refusal refusal;
                stage = "bake-read";
                if (painted_atlas_bake::persistence::Read(document, key, bake)
                        == painted_atlas_bake::persistence::ReadState::Present
                    && !bake.label.IsNull()) {
                    stage = "bake-decode";
                    if (painted_atlas_bake::Decode(bake.bytes, modified,
                            refusal)
                        && !modified.bindings.empty()) {
                        modified.bindings.front().originalContent[0] ^= 0x5A;
                        stage = "bake-stage";
                        applied = painted_atlas_bake::persistence::
                            StageCommitted(document, modified);
                        if (applied) stagedStale = modified;
                    }
                }
                cause = "stale-binding";
                field = "SYEB.binding";
                break;
            }
            case DebugPrivateExportDecalFault::SavedAtlasCaptureMissingMember: {
                retained_solid::UUID entity{};
                if (retained_solid::ReadUUID(memberOwners.front(),
                        entityAttribute, entity)) {
                    field = retained_solid::UUIDText(entity);
                    memberOwners.front().ForgetAttribute(entityAttribute);
                    applied = true;
                }
                cause = "missing-member-identity";
                break;
            }
            case DebugPrivateExportDecalFault::SavedAtlasCaptureForeignMember: {
                retained_solid::UUID entity{};
                if (retained_solid::ReadUUID(memberOwners.front(),
                        entityAttribute, entity)) {
                    field = retained_solid::UUIDText(entity);
                    entity[0] ^= 0x5A;
                    TDataStd_AsciiString::Set(memberOwners.front(),
                        entityAttribute, TCollection_AsciiString(
                            retained_solid::UUIDText(entity).c_str()));
                    applied = true;
                }
                cause = "foreign-member-identity";
                break;
            }
            case DebugPrivateExportDecalFault::
                SavedAtlasCaptureDuplicateMember: {
                retained_solid::UUID entity{};
                retained_solid::UUID definition{};
                if (memberOwners.size() >= 2
                    && retained_solid::ReadUUID(memberOwners[0],
                        entityAttribute, entity)
                    && retained_solid::ReadUUID(memberOwners[0],
                        definitionAttribute, definition)) {
                    field = retained_solid::UUIDText(entity);
                    TDataStd_AsciiString::Set(memberOwners[1],
                        entityAttribute, TCollection_AsciiString(
                            retained_solid::UUIDText(entity).c_str()));
                    TDataStd_AsciiString::Set(memberOwners[1],
                        definitionAttribute, TCollection_AsciiString(
                            retained_solid::UUIDText(definition).c_str()));
                    applied = true;
                }
                cause = "duplicate-member-identity";
                break;
            }
            case DebugPrivateExportDecalFault::
                SavedAtlasCaptureForeignRawSlot: {
                const Handle(XCAFDoc_VisMaterialTool) materials =
                    XCAFDoc_DocumentTool::VisMaterialTool(document->Main());
                const Handle(XCAFDoc_VisMaterial) material = materials.IsNull()
                    ? Handle(XCAFDoc_VisMaterial)()
                    : XCAFDoc_VisMaterialTool::GetShapeMaterial(
                        memberOwners.front());
                if (!material.IsNull() && material->HasPbrMaterial()) {
                    Handle(XCAFDoc_VisMaterial) modified =
                        new XCAFDoc_VisMaterial();
                    XCAFDoc_VisMaterialPBR pbr = material->PbrMaterial();
                    // Capture must classify the descriptor from FilePath and
                    // refuse before attempting to open it. The path need not
                    // and must not exist.
                    pbr.BaseColorTexture = new Image_Texture(
                        TCollection_AsciiString(
                            "/nonexistent/shapeyard-xcaf-foreign.png"));
                    modified->SetPbrMaterial(pbr);
                    modified->SetCommonMaterial(material->CommonMaterial());
                    const TDF_Label materialLabel = materials->AddMaterial(
                        modified, TCollection_AsciiString(
                            "E4 saved capture foreign raw slot"));
                    if (!materialLabel.IsNull()) {
                        materials->SetShapeMaterial(memberOwners.front(),
                            materialLabel);
                        applied = true;
                    }
                }
                cause = "foreign-raw-slot";
                field = "SYFI";
                break;
            }
            case DebugPrivateExportDecalFault::
                SavedAtlasCaptureMalformedResource: {
                const TDF_Label root = document->Main().FindChild(
                    face_image::persistence::resources::RootTag,
                    Standard_False);
                if (!root.IsNull()) {
                    for (TDF_ChildIterator child(root, Standard_False);
                         child.More(); child.Next()) {
                        if (!child.Value().IsAttribute(
                                face_image::persistence::resources::
                                    AttributeID())) continue;
                        TDataStd_Integer::Set(child.Value(),
                            Standard_GUID(
                                "E278C2B6-2F4A-4D3B-9C4E-7A1F0B5D8E40"), 1);
                        applied = true;
                        break;
                    }
                }
                cause = "malformed-resource";
                field = "SYFR";
                break;
            }
            default:
                break;
        }
        bool committed = false;
        if (applied) {
            committed = document->CommitCommand();
        } else {
            document->AbortCommand();
            field = std::string("adapter-") + stage;
        }
        if (undoLimitRaised) document->SetUndoLimit(savedUndoLimit);
        if (!applied) return false;
        if (!committed) {
            field = "adapter-commit";
            return false;
        }
        if (fault
            == DebugPrivateExportDecalFault::SavedAtlasCaptureStaleBinding) {
            // Strict post-commit readback: the committed record must still
            // decode to exactly the staged stale definition.
            painted_atlas_bake::persistence::Record readback;
            painted_atlas_bake::Definition decoded;
            painted_atlas_bake::Refusal readbackRefusal;
            if (painted_atlas_bake::persistence::Read(document, key, readback)
                    != painted_atlas_bake::persistence::ReadState::Present
                || !painted_atlas_bake::Decode(readback.bytes, decoded,
                        readbackRefusal)
                || !(decoded == stagedStale)) {
                field = "adapter-readback";
                return false;
            }
        }
        return true;
    } catch (...) {
        if (!document.IsNull()) {
            if (document->HasOpenCommand()) document->AbortCommand();
            if (undoLimitRaised) document->SetUndoLimit(savedUndoLimit);
        }
        return false;
    }
}
#endif

bool OcctSceneSnapshotBuilder::CapturePrivateExportDecals(
    const Handle(OcctDocument)& privateDocument,
    const SceneSnapshot& wholeCommittedScene,
    bool selectedObjectsOnly,
    const std::function<bool()>& cancelled,
    PrivateDecalCapturePointer& capture
#ifdef DEBUG
    , const DebugPrivateExportDecalFault debugFault
    , DebugPrivateExportDecalObservation* const debugObservation
#endif
    ) noexcept {
    capture.reset();
    if (privateDocument.IsNull() || !cancelled || cancelled()
        || !IsValidSceneSnapshot(wholeCommittedScene)) return false;
    try {
        const Handle(TDocStd_Document)& document = privateDocument->Document();
        if (document.IsNull() || document->HasOpenCommand()) return false;
        OperationLedger captureAdmission;
        const std::size_t captureControlBytes =
            sizeof(PrivateDecalCapture) + sizeof(PrivateDecalCapture::Impl);
        if (!captureAdmission.reserve(
                decal_layer::bake::accounting::StorageDimension::PrivateStorage,
                captureControlBytes,
                decal_layer::bake::accounting::Retention::Retained,
                decal_layer::bake::accounting::FailureSite::ProtectedCaptureControl)
            || !captureAdmission.enterAllocation(
                decal_layer::bake::accounting::FailureSite::ProtectedCaptureControl)
            || !captureAdmission.enterAllocation(
                decal_layer::bake::accounting::FailureSite::ProtectedCaptureControl))
            return false;
        auto candidate = std::make_unique<PrivateDecalCapture>();
        if (!candidate || !candidate->impl_) return false;
        auto& impl = *candidate->impl_;
        impl.operationLedger = captureAdmission;
        impl.controlStorageTicket.view = impl.operationLedger.view();
        impl.controlStorageTicket.dimension =
            decal_layer::bake::accounting::StorageDimension::PrivateStorage;
        impl.controlStorageTicket.bytes = captureControlBytes;
        impl.controlStorageTicket.retention =
            decal_layer::bake::accounting::Retention::Retained;
        int debugProtectedCaptureMode = 0;
#ifdef DEBUG
        debugProtectedCaptureMode = gDebugProtectedCaptureMode.exchange(
            0, std::memory_order_acq_rel);
#endif
        if (!impl.operationLedger.recheck(
                decal_layer::bake::accounting::FailureSite::ContextControl))
            return false;
        impl.privateDocument = privateDocument;
        SceneCopyStorage wholeSceneBytes;
        if (!DeepSceneStorageBytes(wholeCommittedScene, wholeSceneBytes)
            || !impl.wholeSceneNumericTicket.acquire(impl.operationLedger.view(),
                decal_layer::bake::accounting::StorageDimension::SnapshotNumeric,
                wholeSceneBytes.numeric,
                decal_layer::bake::accounting::Retention::Retained,
                decal_layer::bake::accounting::FailureSite::ProtectedSceneCopy)
            || !impl.wholeSceneEncodedTicket.acquire(impl.operationLedger.view(),
                decal_layer::bake::accounting::StorageDimension::EncodedTexture,
                wholeSceneBytes.encoded,
                decal_layer::bake::accounting::Retention::Retained,
                decal_layer::bake::accounting::FailureSite::ProtectedSceneCopy)
            || !impl.wholeScenePrivateTicket.acquire(impl.operationLedger.view(),
                decal_layer::bake::accounting::StorageDimension::PrivateStorage,
                wholeSceneBytes.privateBytes,
                decal_layer::bake::accounting::Retention::Retained,
                decal_layer::bake::accounting::FailureSite::ProtectedSceneCopy)
            || !impl.operationLedger.enterAllocation(
                decal_layer::bake::accounting::FailureSite::ProtectedSceneCopy))
            return false;
        impl.wholeCommittedScene = wholeCommittedScene;
        impl.selectedObjectsOnly = selectedObjectsOnly;
        if (!AcquireProtectedStorage(impl.documentIdentifierTicket,
                impl.operationLedger.view(),
                decal_layer::bake::accounting::StorageDimension::PrivateStorage,
                64U, decal_layer::bake::accounting::Retention::Retained,
                decal_layer::bake::accounting::FailureSite::ProtectedCaptureControl))
            return false;
        impl.documentIdentifier = privateDocument->DocumentIdentifier();
        if (impl.documentIdentifier.capacity() + 1U
                > impl.documentIdentifierTicket.bytes) {
            impl.operationLedger.allocationFailure(
                decal_layer::bake::accounting::FailureSite::ProtectedCaptureControl);
            return false;
        }
        XCAFDoc_DocumentTool::GetLengthUnit(document, impl.metersPerUnit);
        if (impl.metersPerUnit != wholeCommittedScene.metersPerUnit)
            return false;
        if (!impl.operationLedger.bindTopology(
                impl.budget,
                decal_layer::bake::accounting::FailureSite::ContextControl))
            return false;

        // Materialize the strict atlas census once, under this operation. Each
        // nonempty record is then captured through the inherited all-member
        // producer; no member or source authority is reconstructed here.
        std::vector<asset_atlas::persistence::Record> savedAtlases;
        painted_atlas_bake::owner::AtlasReadAdmission atlasRead;
#ifdef DEBUG
        if (debugProtectedCaptureMode == 2) {
            impl.operationLedger.refuse(
                decal_layer::bake::accounting::FailureSite::ProtectedAtlasRead);
            DebugProtectedCaptureObservation observation;
            observation.observed = true;
            observation.refused = true;
            observation.firstFailure = std::size_t(
                impl.operationLedger.firstFailureSite());
            observation.deniedAllocationEntries =
                impl.operationLedger.allocationEntries(
                    decal_layer::bake::accounting::FailureSite::ProtectedAtlasRead);
            observation.liveBytes = impl.operationLedger.totalLive();
            RecordDebugProtectedCapture(observation);
            return false;
        }
#endif
#ifdef DEBUG
        if (debugFault
                == DebugPrivateExportDecalFault::SavedAtlasCaptureDenyRead) {
            impl.operationLedger.refuse(
                decal_layer::bake::accounting::FailureSite::ProtectedAtlasRead);
            if (debugObservation) {
                debugObservation->failureStage =
                    "saved-atlas-capture-refused";
                debugObservation->captureRefusalCause = "over-budget";
                debugObservation->captureRefusalBoundary =
                    "preflight-atlas-read";
                debugObservation->captureRefusalField = "SYEA";
                debugObservation->savedAtlasReadEntries =
                    impl.operationLedger.allocationEntries(
                        decal_layer::bake::accounting::FailureSite::
                            ProtectedAtlasRead);
            }
            return false;
        }
#endif
        if (painted_atlas_bake::owner::PreflightAtlasRead(
                document, impl.operationLedger.view(), atlasRead,
                decal_layer::bake::accounting::FailureSite::ProtectedAtlasRead)
                != painted_atlas_bake::owner::Outcome::Prepared
            || !impl.operationLedger.enterAllocation(
                decal_layer::bake::accounting::FailureSite::ProtectedAtlasRead)) {
#ifdef DEBUG
            if (debugObservation) {
                const char* faultField =
                    DebugSavedAtlasCaptureFaultField(debugFault);
                debugObservation->failureStage = "saved-atlas-capture-refused";
                debugObservation->captureRefusalCause = "refused";
                debugObservation->captureRefusalBoundary =
                    "preflight-atlas-read";
                debugObservation->captureRefusalField =
                    faultField != nullptr ? faultField : "SYEA";
            }
#endif
            return false;
        }
        if (!asset_atlas::persistence::ReadAll(document, savedAtlases)) {
#ifdef DEBUG
            if (debugObservation) {
                debugObservation->failureStage = "saved-atlas-capture-refused";
                debugObservation->captureRefusalCause = "malformed";
                debugObservation->captureRefusalBoundary = "atlas-read";
                debugObservation->captureRefusalField = "SYEA";
            }
#endif
            return false;
        }
        impl.savedAtlasReadAdmission = std::move(atlasRead);
        if (!ReserveProtectedVector(impl.savedGroups, impl.savedGroupsTicket,
                impl.operationLedger.view(), savedAtlases.size(),
                decal_layer::bake::accounting::Retention::Retained,
                decal_layer::bake::accounting::FailureSite::
                    ProtectedOwnerStorage)) return false;
        for (std::size_t index = 0; index < savedAtlases.size(); ++index) {
            if (!savedAtlases[index].value) {
#ifdef DEBUG
                if (debugObservation) {
                    debugObservation->captureRefusalCause = "malformed";
                    debugObservation->captureRefusalBoundary =
                        "saved-atlas-census";
                    debugObservation->captureRefusalField = "SYEA.record";
                }
#endif
                return false;
            }
            painted_atlas_bake::owner::ExportCapture savedCapture;
            const auto& key = savedAtlases[index].value->definition.key;
            const auto savedOutcome =
                painted_atlas_bake::owner::CaptureForExport(savedCapture,
                    document, key, impl.operationLedger.view());
            if (savedOutcome != painted_atlas_bake::owner::Outcome::Prepared) {
#ifdef DEBUG
                if (debugObservation) {
                    const char* faultField =
                        DebugSavedAtlasCaptureFaultField(debugFault);
                    debugObservation->failureStage =
                        "saved-atlas-capture-refused";
                    debugObservation->captureRefusalCause =
                        SavedAtlasCaptureOutcomeText(savedOutcome);
                    debugObservation->captureRefusalBoundary =
                        "capture-for-export";
                    debugObservation->captureRefusalField =
                        faultField != nullptr ? faultField
                            : retained_solid::UUIDText(key.atlas);
                }
#endif
                return false;
            }
            auto group = std::make_unique<SavedGroupOwner>();
            std::string diagnosis;
            if (!group || !PrepareSavedGroupOwner(impl.operationLedger,
                    impl.operationLedger.view(), std::move(savedCapture),
                    privateDocument, cancelled, *group, diagnosis,
                    &impl.budget)) {
#ifdef DEBUG
                if (debugObservation) {
                    debugObservation->captureRefusalCause = diagnosis;
                    debugObservation->captureRefusalBoundary =
                        "saved-group-preparation";
                    debugObservation->captureRefusalField =
                        retained_solid::UUIDText(key.atlas);
                }
#endif
                return false;
            }
            impl.savedGroups.push_back(std::move(group));
        }

        std::vector<const InstanceSnapshot*> occurrences;
        decal_layer::bake::accounting::Ticket occurrencesTicket;
        std::size_t modelOccurrences = 0;
        for (const auto& instance : wholeCommittedScene.instances)
            if (instance.role == RenderRole::Model) ++modelOccurrences;
        if (!ReserveProtectedVector(occurrences, occurrencesTicket,
                impl.operationLedger.view(), modelOccurrences,
                decal_layer::bake::accounting::Retention::Scratch,
                decal_layer::bake::accounting::FailureSite::ProtectedOccurrenceStorage))
            return false;
        for (const auto& instance : wholeCommittedScene.instances) {
            if (instance.role != RenderRole::Model) continue;
            if (std::any_of(occurrences.begin(), occurrences.end(),
                    [&](const InstanceSnapshot* prior) {
                        return prior->entityIdentifier
                            == instance.entityIdentifier;
                    })) return false;
            occurrences.push_back(&instance);
        }
        std::vector<decal_layer::UUID> capturedDefinitions;
        decal_layer::bake::accounting::Ticket capturedDefinitionsTicket;
        if (!ReserveProtectedVector(capturedDefinitions,
                capturedDefinitionsTicket, impl.operationLedger.view(),
                occurrences.size(),
                decal_layer::bake::accounting::Retention::Scratch,
                decal_layer::bake::accounting::FailureSite::ProtectedOccurrenceStorage)
            || !ReserveProtectedVector(impl.owners, impl.ownersTicket,
                impl.operationLedger.view(), occurrences.size(),
                decal_layer::bake::accounting::Retention::Retained,
                decal_layer::bake::accounting::FailureSite::ProtectedOwnerStorage))
            return false;
        // Match XCAFPrs_DocumentExplorer's OnlyLeafNodes/NoStyle walk without
        // its NCollection_Vector node blocks or TDF_LabelSequence roots.  The
        // shape-tool root label and each assembly definition are already
        // ordered label trees; fixed TDF iterators therefore preserve the
        // explorer's root/child occurrence order without owning a sequence.
        struct ProtectedTraversalFrame final {
            TDF_Label label;
            TDF_ChildIterator children;

            ProtectedTraversalFrame(const TDF_Label& occurrence,
                                      const TDF_Label& definition)
                : label(occurrence),
                  children(definition, Standard_False) {}
        };
        const Handle(XCAFDoc_ShapeTool) shapeTool =
            XCAFDoc_DocumentTool::ShapeTool(document->Main());
        if (shapeTool.IsNull()) return false;
        std::vector<ProtectedTraversalFrame> traversal;
        decal_layer::bake::accounting::Ticket traversalTicket;
        if (!ReserveProtectedVector(traversal, traversalTicket,
                impl.operationLedger.view(),
                std::size_t(kMaxOccurrenceDepth),
                decal_layer::bake::accounting::Retention::Scratch,
                decal_layer::bake::accounting::FailureSite::ProtectedTraversalStorage))
            return false;
        TDF_ChildIterator roots(shapeTool->BaseLabel(), Standard_False);
        while (roots.More() || !traversal.empty()) {
            TDF_Label nodeLabel;
            TDF_Label label;
            std::size_t currentDepth = 0;
            while (nodeLabel.IsNull()) {
                if (traversal.empty()) {
                    bool foundRoot = false;
                    while (roots.More()) {
                        const TDF_Label root = roots.Value();
                        roots.Next();
                        TopoDS_Shape rootShape;
                        if (!XCAFDoc_ShapeTool::GetShape(root, rootShape)
                            || !XCAFDoc_ShapeTool::IsFree(root))
                            continue;
                        foundRoot = true;
                        TDF_Label rootDefinition = root;
                        XCAFDoc_ShapeTool::GetReferredShape(
                            root, rootDefinition);
                        if (XCAFDoc_ShapeTool::IsAssembly(rootDefinition)) {
                            traversal.emplace_back(root, rootDefinition);
                        } else {
                            nodeLabel = root;
                            label = rootDefinition;
                        }
                        break;
                    }
                    if (!foundRoot) break;
                    if (!nodeLabel.IsNull()) break;
                }
                auto& frame = traversal.back();
                if (!frame.children.More()) {
                    traversal.pop_back();
                    continue;
                }
                const TDF_Label child = frame.children.Value();
                frame.children.Next();
                if (!child.HasAttribute()) continue;
                TDF_Label childDefinition = child;
                XCAFDoc_ShapeTool::GetReferredShape(
                    child, childDefinition);
                if (XCAFDoc_ShapeTool::IsAssembly(childDefinition)) {
                    if (traversal.size()
                            >= std::size_t(kMaxOccurrenceDepth))
                        return false;
                    traversal.emplace_back(child, childDefinition);
                    continue;
                }
                currentDepth = traversal.size();
                if (currentDepth >= std::size_t(kMaxOccurrenceDepth))
                    return false;
                nodeLabel = child;
                label = childDefinition;
            }
            if (nodeLabel.IsNull()) break;
            if (cancelled()) return false;
            std::vector<std::string> path;
            decal_layer::bake::accounting::Ticket pathTicket;
            std::size_t pathBytes = 0;
            if (!impl.operationLedger.checkedProduct(
                    currentDepth + 1U,
                    sizeof(std::string) + 64U, 1U, pathBytes,
                    decal_layer::bake::accounting::FailureSite::ProtectedPathStorage)
                || !AddProtectedBytes(pathBytes, 192U)
                || !AcquireProtectedStorage(pathTicket,
                    impl.operationLedger.view(),
                    decal_layer::bake::accounting::StorageDimension::PrivateStorage,
                    pathBytes, decal_layer::bake::accounting::Retention::Scratch,
                    decal_layer::bake::accounting::FailureSite::ProtectedPathStorage))
                return false;
            path.reserve(currentDepth + 1U);
            for (const auto& frame : traversal) {
                path.push_back(privateDocument->EntityIdentifierForLabel(
                    frame.label));
            }
            path.push_back(privateDocument->EntityIdentifierForLabel(
                nodeLabel));
            const std::string entity = DeriveOccurrenceIdentifier(
                impl.documentIdentifier, path);
            if (std::none_of(occurrences.begin(), occurrences.end(),
                    [&](const InstanceSnapshot* occurrence) {
                        return occurrence->entityIdentifier == entity;
                    })) continue;
            const std::string definitionIdentifier =
                privateDocument->DefinitionIdentifierForLabel(label);
            if (definitionIdentifier.empty()) return false;
            retained_recipe::OwnerKey owner;
            if (!receipt::ParseUUID(impl.documentIdentifier, owner.document)
                || !receipt::ParseUUID(
                    privateDocument->EntityIdentifierForLabel(label),
                    owner.entity)
                || !receipt::ParseUUID(definitionIdentifier,
                                       owner.definition)) return false;
            if (std::find(capturedDefinitions.begin(),
                    capturedDefinitions.end(), owner.definition)
                    != capturedDefinitions.end())
                continue;
            decal_layer::Definition definition;
            std::vector<std::uint8_t> canonicalBytes;
            ProtectedDefinitionAdmission definitionAdmission;
            if (!PreflightProtectedDefinitionRead(label,
                    impl.operationLedger.view(), definitionAdmission)
                || !impl.operationLedger.enterAllocation(
                    decal_layer::bake::accounting::FailureSite::ProtectedDefinitionStorage))
                return false;
            const auto state = decal_layer::persistence::Read(
                document, label, definition, &canonicalBytes, nullptr);
            if (state == decal_layer::persistence::ReadState::Malformed)
                return false;
            if (state == decal_layer::persistence::ReadState::Absent)
                continue;
            if (definition.layers.size() != definitionAdmission.layerCount
                || definition.layers.capacity() * sizeof(decal_layer::Layer)
                    > definitionAdmission.layers.bytes
                || canonicalBytes.capacity() > definitionAdmission.canonical.bytes
                || !(definition.owner == owner)) return false;
            capturedDefinitions.push_back(owner.definition);
            definitionAdmission.readScratch.reset();
            decal_layer::bake::accounting::Ticket proofTicket;
            std::size_t proofBytes =
                definition.layers.capacity() * sizeof(decal_layer::Layer);
            if (!AddProtectedBytes(proofBytes, canonicalBytes.capacity())
                || !AcquireProtectedStorage(proofTicket,
                    impl.operationLedger.view(),
                    decal_layer::bake::accounting::StorageDimension::PrivateStorage,
                    proofBytes,
                    decal_layer::bake::accounting::Retention::Scratch,
                    decal_layer::bake::accounting::FailureSite::ProtectedDefinitionStorage))
                return false;
            decal_layer::Definition proof = definition;
            const auto savedProof = proof.layerProof;
            decal_layer::source::Witness source;
            if (!decal_layer::BindLayerProof(proof)
                || proof.layerProof != savedProof
                || !decal_layer::source::CaptureSource(
                    privateDocument, owner, impl.budget,
                    cancelled, source)
                || !decal_layer::source::ExactMatch(definition, source))
                return false;
            const TopoDS_Shape shape = XCAFDoc_ShapeTool::GetShape(label);
            if (shape.IsNull()) return false;
            PrivateDecalCapture::Impl::Owner value;
            value.definitionLayersTicket =
                std::move(definitionAdmission.layers);
            value.canonicalBytesTicket =
                std::move(definitionAdmission.canonical);
            value.owner = owner;
            int debugCensusMode = 0;
#ifdef DEBUG
            debugCensusMode = gDebugBRepCensusMode.exchange(
                0, std::memory_order_acq_rel);
#endif
            // A saved-atlas member borrows the group's one admitted measured
            // copy (detached shape, copier and face maps) instead of paying a
            // second measured copy of the same native definition. The match
            // is the exact owner identity, never a count or a first-face
            // fallback; ambiguity or owner mismatch fails closed.
            const SavedGroupMeasuredMember* borrowedMember = nullptr;
            for (const auto& groupPointer : impl.savedGroups) {
                if (!groupPointer) return false;
                const auto& group = *groupPointer;
                for (std::size_t memberIndex = 0;
                     memberIndex < group.measured.size(); ++memberIndex) {
                    const auto& candidate = group.measured[memberIndex];
                    if (candidate.definitionIdentifier != definitionIdentifier)
                        continue;
                    if (borrowedMember != nullptr
                        || memberIndex
                            >= group.capture.savedAtlas.members.size()
                        || !(group.capture.savedAtlas.members[memberIndex].owner
                            == owner)) return false;
                    borrowedMember = &candidate;
                }
            }
            TopTools_IndexedMapOfShape ownedOriginalFaces, ownedDisposableFaces;
            if (borrowedMember != nullptr) {
                value.borrowedMeasured = borrowedMember;
                value.detachedAuthorityShape = borrowedMember->detached;
            } else {
                BRepRepresentationCensus preCopyCensus;
                BRepRepresentationCensus copyPrediction;
                decal_layer::bake::accounting::Ticket censusScratch;
                if (!MeasureBRepRepresentation(shape, impl.budget,
                        impl.operationLedger.view(), preCopyCensus,
                        censusScratch, &copyPrediction)) return false;
                censusScratch.reset();
                std::size_t retainedMeasuredBytes = 0;
                if (!CopyMeasuredBRep(shape, impl.budget,
                        impl.operationLedger, preCopyCensus, copyPrediction,
                        debugCensusMode, value.brepCensusTicket, value.copier,
                        value.detachedAuthorityShape, ownedOriginalFaces,
                        ownedDisposableFaces, retainedMeasuredBytes))
                    return false;
#ifdef DEBUG
                for (const auto& groupPointer : impl.savedGroups) {
                    if (!groupPointer) return false;
                    for (const auto& measured : groupPointer->measured)
                        if (measured.definitionIdentifier
                            == definitionIdentifier)
                            ++impl.debugSavedMemberReceiverCopies;
                }
#endif
            }
            const TopTools_IndexedMapOfShape& originalFaces =
                borrowedMember != nullptr ? borrowedMember->originalFaces
                    : ownedOriginalFaces;
            const TopTools_IndexedMapOfShape& disposableFaces =
                borrowedMember != nullptr ? borrowedMember->detachedFaces
                    : ownedDisposableFaces;
            const BRepBuilderAPI_Copy* const activeCopier =
                borrowedMember != nullptr ? borrowedMember->copier.get()
                    : value.copier.get();
            if (activeCopier == nullptr
                || value.detachedAuthorityShape.IsNull()) return false;

            Bnd_Box stageBox;
            BRepBndLib::AddOptimal(
                shape, stageBox, Standard_False, Standard_False);
            if (stageBox.IsVoid() || stageBox.IsWhole()
                || stageBox.IsOpen()) return false;
            using ReceiverKey = std::pair<decal_layer::UUID,
                                          decal_layer::Digest>;
            std::vector<ReceiverKey> seenReceivers;
            decal_layer::bake::accounting::Ticket seenReceiversTicket;
            decal_layer::bake::accounting::Ticket receiptProofTicket;
            if (!ReserveProtectedVector(seenReceivers, seenReceiversTicket,
                    impl.operationLedger.view(), definition.layers.size(),
                    decal_layer::bake::accounting::Retention::Scratch,
                    decal_layer::bake::accounting::FailureSite::ProtectedReceiverStorage)
                || !ReserveProtectedVector(value.receivers,
                    value.receiverVectorTicket, impl.operationLedger.view(),
                    definition.layers.size(),
                    decal_layer::bake::accounting::Retention::Retained,
                    decal_layer::bake::accounting::FailureSite::ProtectedReceiverStorage)
                || !AcquireProtectedStorage(receiptProofTicket,
                    impl.operationLedger.view(),
                    decal_layer::bake::accounting::StorageDimension::PrivateStorage,
                    4096U, decal_layer::bake::accounting::Retention::Scratch,
                    decal_layer::bake::accounting::FailureSite::ProtectedReceiverStorage))
                return false;
            for (const auto& layer : definition.layers) {
                const auto receipt = decal_layer::bake::IntentReceipt(layer);
                const ReceiverKey key{receipt.face, receipt.selectorProof};
                if (std::find(seenReceivers.begin(), seenReceivers.end(), key)
                        != seenReceivers.end())
                    continue;
                seenReceivers.push_back(key);
                int match = 0;
                dependent_replay::FaceImageGeometricReceipt matchedReceipt;
                TopoDS_Face originalFace;
                for (Standard_Integer index = 1;
                     index <= originalFaces.Extent(); ++index) {
                    dependent_replay::FaceImageGeometricReceipt derived;
                    const auto status = dependent_replay::detail::
                        DeriveFaceImageReceipt(stageBox,
                            TopoDS::Face(originalFaces.FindKey(index)),
                            impl.metersPerUnit, impl.budget, derived);
                    if (status == dependent_replay::detail::
                            FaceImageDeriveStatus::Budget)
                        return false;
                    if (status != dependent_replay::detail::
                            FaceImageDeriveStatus::Derived)
                        continue;
                    decal_layer::Digest derivedProof{};
                    if (!impl.operationLedger.enterAllocation(
                            decal_layer::bake::accounting::FailureSite::
                                ProtectedReceiverStorage)
                        || !dependent_replay::FaceImageReceiptProof(
                            derived, derivedProof)) return false;
                    if (derivedProof != receipt.selectorProof) continue;
                    ++match;
                    matchedReceipt = std::move(derived);
                    originalFace = TopoDS::Face(
                        originalFaces.FindKey(index));
                }
                if (match != 1 || originalFace.IsNull()) return false;
                dependent_replay::FaceImageGeometricReceipt resolved;
                TopoDS_Face resolvedFace;
                if (dependent_replay::detail::ResolveFaceImageReceipt(
                        shape, matchedReceipt.intent, impl.metersPerUnit,
                        impl.budget, resolved, resolvedFace)
                        != retained_face_selector::Refusal::None
                    || !(resolved == matchedReceipt)
                    || !resolvedFace.IsSame(originalFace)) return false;
                const TopoDS_Shape copied =
                    activeCopier->ModifiedShape(originalFace);
                const Standard_Integer originalIndex =
                    originalFaces.FindIndex(originalFace);
                const Standard_Integer disposableIndex =
                    disposableFaces.FindIndex(copied);
                if (copied.IsNull() || copied.ShapeType() != TopAbs_FACE
                    || originalIndex <= 0 || disposableIndex <= 0
                    || originalIndex > INT32_MAX
                    || disposableIndex > INT32_MAX) return false;
                value.receivers.push_back({receipt, matchedReceipt,
                    originalFace,
                    TopoDS::Face(copied),
                    std::uint32_t(originalIndex - 1),
                    std::uint32_t(disposableIndex - 1)});
            }
            if (value.receivers.empty())
                return false;

            decal_layer::bake::accounting::Ticket finishingScratchTicket;
            retained_finishing::producer::Capture finishing;
            if (!AcquireProtectedStorage(finishingScratchTicket,
                    impl.operationLedger.view(),
                    decal_layer::bake::accounting::StorageDimension::PrivateStorage,
                    sizeof(retained_finishing::MaterialResource) + 48U,
                    decal_layer::bake::accounting::Retention::Scratch,
                    decal_layer::bake::accounting::FailureSite::ProtectedFinishingStorage)
                || !AcquireProtectedStorage(value.finishingStorageTicket,
                    impl.operationLedger.view(),
                    decal_layer::bake::accounting::StorageDimension::PrivateStorage,
                    sizeof(retained_finishing::MaterialResource),
                    decal_layer::bake::accounting::Retention::Retained,
                    decal_layer::bake::accounting::FailureSite::ProtectedFinishingStorage))
                return false;
            if (!retained_finishing::producer::CaptureSource(
                    document, owner, finishing))
                return false;
            value.ownerLabel = label;
            value.savedMember.savedMember.owner = owner;
            value.savedMember.savedMember.source = finishing.source;
            value.savedMember.authority = finishing;
            std::vector<retained_finishing::MaterialResource>().swap(
                finishing.resources);
            finishingScratchTicket.reset();
            value.transientAtlas.document = owner.document;
            if (!ReserveProtectedVector(value.paintedSources,
                    value.paintedSourcesTicket, impl.operationLedger.view(),
                    definition.layers.size(),
                    decal_layer::bake::accounting::Retention::Retained,
                    decal_layer::bake::accounting::FailureSite::ProtectedSourceStorage))
                return false;
            for (std::size_t layerIndex = 0;
                 layerIndex < definition.layers.size(); ++layerIndex) {
                const auto& layer = definition.layers[layerIndex];
                face_image::ResourceEnvelope envelope;
                painted_atlas_bake::owner::ResourceReadAdmission resourceRead;
                if (painted_atlas_bake::owner::PreflightResourceRead(
                        document, layer.image.resource,
                        impl.operationLedger.view(), resourceRead)
                        != painted_atlas_bake::owner::Outcome::Prepared
                    || !impl.operationLedger.enterAllocation(
                        decal_layer::bake::accounting::FailureSite::ResourceReadMaterialize))
                    return false;
                if (!face_image::owner::ReadResource(
                        document, layer.image.resource, envelope))
                    return false;
                painted_atlas_bake::owner::CapturedSource captured;
                captured.fence.owner = owner;
                captured.fence.binding = layer.identifier;
                captured.fence.resource = layer.image.resource;
                captured.fence.selectorProof =
                    decal_layer::bake::IntentReceipt(layer).selectorProof;
                captured.fence.bindingProof = definition.layerProof;
                captured.fence.originalContent =
                    layer.image.originalContent;
                captured.fence.workingContent =
                    layer.image.normalizedContent;
                captured.fence.role = layer.image.role;
                captured.fence.colorSpace = layer.image.colorSpace;
                captured.origin =
                    painted_atlas_bake::kernel::SourceOrigin::OrderedLayer;
                captured.envelope = std::move(envelope);
                captured.memberIndex = 0;
                captured.order = layerIndex;
                captured.boundedLayer = layer.placement.kind
                    == decal_layer::PlacementKind::Face;
                if (captured.boundedLayer) {
                    captured.centerU =
                        layer.placement.face.anchorMeters[0]
                            / impl.metersPerUnit;
                    captured.centerV =
                        layer.placement.face.anchorMeters[1]
                            / impl.metersPerUnit;
                    captured.width = layer.widthMeters / impl.metersPerUnit;
                    captured.height = layer.heightMeters / impl.metersPerUnit;
                    captured.angle = layer.placement.face.angleRadians;
                }
                captured.opacity = layer.opacity;
                captured.maskPresent = layer.mask.present;
                if (captured.maskPresent) {
                    painted_atlas_bake::owner::ResourceReadAdmission maskRead;
                    if (painted_atlas_bake::owner::PreflightResourceRead(
                            document, layer.mask.image.resource,
                            impl.operationLedger.view(), maskRead)
                            != painted_atlas_bake::owner::Outcome::Prepared
                        || !impl.operationLedger.enterAllocation(
                            decal_layer::bake::accounting::FailureSite::
                                ResourceReadMaterialize)
                        || !face_image::owner::ReadResource(document,
                            layer.mask.image.resource,
                            captured.maskEnvelope)
                        || !maskRead.selected
                        || captured.maskEnvelope.originalBytes.capacity()
                            > maskRead.originalBytes.bytes
                        || captured.maskEnvelope.workingBytes.capacity()
                            > maskRead.workingBytes.bytes)
                        return false;
                    maskRead.serialization.reset();
                    maskRead.table.reset();
                    captured.maskOriginalBytesTicket =
                        std::move(maskRead.originalBytes);
                    captured.maskWorkingBytesTicket =
                        std::move(maskRead.workingBytes);
                    captured.maskUsesLuminance = layer.mask.channel
                        == decal_layer::MaskChannel::LinearLuminance;
                    captured.maskInverted = layer.mask.inverted;
                    captured.maskTransform = layer.mask.transform;
                }
                if (!resourceRead.selected
                    || captured.envelope.originalBytes.capacity()
                        > resourceRead.originalBytes.bytes
                    || captured.envelope.workingBytes.capacity()
                        > resourceRead.workingBytes.bytes) {
                    impl.operationLedger.allocationFailure(
                        decal_layer::bake::accounting::FailureSite::ResourceReadMaterialize);
                    return false;
                }
                resourceRead.serialization.reset();
                resourceRead.table.reset();
                captured.originalBytesTicket =
                    std::move(resourceRead.originalBytes);
                captured.workingBytesTicket =
                    std::move(resourceRead.workingBytes);
                if (!painted_atlas_bake::Valid(captured.fence))
                    return false;
                value.paintedSources.push_back(
                    std::move(captured));
            }
            if (value.paintedSources.empty()) return false;
            value.definition = std::move(definition);
            value.canonicalBytes = std::move(canonicalBytes);
            value.source = std::move(source);
            if (!AcquireProtectedStorage(value.definitionIdentifierTicket,
                    impl.operationLedger.view(),
                    decal_layer::bake::accounting::StorageDimension::PrivateStorage,
                    definitionIdentifier.capacity() + 1U,
                    decal_layer::bake::accounting::Retention::Retained,
                    decal_layer::bake::accounting::FailureSite::ProtectedOwnerStorage))
                return false;
            value.definitionIdentifier = definitionIdentifier;
            impl.owners.push_back(std::move(value));
        }
        std::vector<decal_math::DecalWorldTriangle> protectedOccluders;
        decal_layer::bake::accounting::Ticket protectedOccluderTicket;
        Bounds3d protectedOccluderBounds;
        if (!decal_math::CaptureDecalOccluders(impl.wholeCommittedScene,
                protectedOccluders, protectedOccluderBounds,
                impl.occluderProof, impl.operationLedger.view(),
                protectedOccluderTicket)) return false;
        // Passive capture-stage value: the complete saved group is retained
        // here, before the unchanged protected currentness refusal below.
        // Its private aggregate is never executed and never feeds the
        // transient {256,4} producer.
        impl.savedGroupLayoutReason = PrepareSavedGroupLayoutRecord(
            impl.savedGroups, impl.privateDocument, impl.wholeCommittedScene,
            selectedObjectsOnly, cancelled, impl.savedGroupLayoutControlTicket,
            impl.savedGroupLayout);
#ifdef DEBUG
        if (debugObservation) {
            auto& observed = *debugObservation;
            using Reason = SavedGroupAllMemberLayoutReason;
            switch (impl.savedGroupLayoutReason) {
                case Reason::Present:
                    observed.savedGroupLayoutRecordReason = "present"; break;
                case Reason::Unavailable:
                    observed.savedGroupLayoutRecordReason = "unavailable"; break;
                case Reason::Overflow:
                    observed.savedGroupLayoutRecordReason = "overflow"; break;
                case Reason::Malformed:
                    observed.savedGroupLayoutRecordReason = "malformed"; break;
                case Reason::StaleSource:
                    observed.savedGroupLayoutRecordReason = "stale-source"; break;
                case Reason::StaleBinding:
                    observed.savedGroupLayoutRecordReason = "stale-binding"; break;
                case Reason::UnsupportedSurface:
                    observed.savedGroupLayoutRecordReason = "unsupported-surface";
                    break;
                case Reason::Refused:
                    observed.savedGroupLayoutRecordReason = "refused"; break;
            }
            // The existing fault checkpoint owns its detailed census; avoid
            // double-counting it while making the natural refusal observable.
            if (debugFault != DebugPrivateExportDecalFault::
                    SavedAtlasCaptureCheckpoint) {
                observed.savedGroupCount = impl.savedGroups.size();
                for (const auto& group : impl.savedGroups)
                    if (group) observed.savedMemberCount += group->measured.size();
            }
            if (impl.savedGroupLayout) {
                observed.savedGroupLayoutRecordState = "present";
                const auto& record = *impl.savedGroupLayout;
                observed.savedGroupLayoutNanoseconds = record.layoutNanoseconds;
                observed.savedGroupLayoutPreparationNanoseconds =
                    record.preparationNanoseconds;
                observed.savedGroupLayoutRetainedBytes = record.retainedBytes;
                observed.savedGroupLayoutOperationBytes =
                    impl.operationLedger.totalLive();
                using Dimension = decal_layer::bake::accounting::StorageDimension;
                using Job = decal_layer::bake::accounting::Job;
                for (const auto dimension : {Dimension::SnapshotNumeric,
                        Dimension::EncodedTexture, Dimension::PrivateStorage}) {
                    const auto storage =
                        impl.operationLedger.debugStorageState(dimension);
                    observed.savedGroupLayoutStoragePeakBytes.push_back(storage[3]);
                    observed.savedGroupLayoutStorageLimitBytes.push_back(storage[4]);
                }
                observed.savedGroupLayoutBakeJobsUnsealed = true;
                for (const auto job : {Job::AtlasRoles, Job::SourcePixels,
                        Job::MaskPixels, Job::Gutter, Job::Encoder})
                    observed.savedGroupLayoutBakeJobsUnsealed =
                        observed.savedGroupLayoutBakeJobsUnsealed
                        && impl.operationLedger.debugJobState(job)[2] == 0;

                // Resolution and gutter describe the single-group fixture;
                // counts and ordered streams cover every retained group.
                if (record.groups.size() == 1) {
                    observed.savedGroupLayoutResolution =
                        record.groups.front().atlas.resolutionTexels;
                    observed.savedGroupLayoutGutter =
                        record.groups.front().atlas.gutterTexels;
                }
                for (const auto& group : record.groups) {
                    observed.savedGroupLayoutMemberCount +=
                        group.memberDefinitions.size();
                    observed.savedGroupLayoutAssignmentCount +=
                        group.assignments.size();
                    observed.savedGroupLayoutChartCount += group.layout.charts.size();
                    observed.savedGroupLayoutMemberDefinitions.insert(
                        observed.savedGroupLayoutMemberDefinitions.end(),
                        group.memberDefinitions.begin(),
                        group.memberDefinitions.end());
                    for (const auto& assignment : group.assignments)
                        observed.savedGroupLayoutAssignmentCornerCounts.push_back(
                            assignment.corners.size());
                }
            }
        }
#endif
#ifdef DEBUG
        if (debugFault
                == DebugPrivateExportDecalFault::SavedAtlasCaptureCheckpoint) {
            if (!debugObservation || impl.savedGroups.empty()) return false;
            auto& observed = *debugObservation;
            observed.failureStage = "saved-atlas-capture-checkpoint";
            observed.captureReached = true;
            observed.savedGroupCount = impl.savedGroups.size();
            observed.ownerCount = impl.owners.size();
            observed.savedAtlasReadEntries =
                impl.operationLedger.allocationEntries(
                    decal_layer::bake::accounting::FailureSite::
                        ProtectedAtlasRead);
            observed.occluderDigest = DecalDigestText(impl.occluderProof);
            observed.savedDetachedIdentitiesDistinct = true;
            std::set<std::string> measuredDefinitions;
            std::set<std::string> sourcedDefinitions;
            std::set<std::string> selectedDefinitions;
            for (const auto& instance : impl.wholeCommittedScene.instances) {
                if (instance.role != RenderRole::Model || !instance.selected
                    || instance.meshIndex >= impl.wholeCommittedScene.meshes.size())
                    continue;
                const auto& mesh =
                    impl.wholeCommittedScene.meshes[instance.meshIndex];
                selectedDefinitions.insert(
                    mesh.paintedAtlasMasterDefinitionIdentifier.empty()
                    ? mesh.definitionIdentifier
                    : mesh.paintedAtlasMasterDefinitionIdentifier);
            }
            for (const auto& groupPointer : impl.savedGroups) {
                if (!groupPointer) return false;
                const auto& group = *groupPointer;
                observed.savedCanonicalLengths.push_back(
                    group.capture.canonicalAtlasBytes.size());
                observed.savedCanonicalLengths.push_back(
                    group.capture.canonicalBakeBytes.size());
                observed.savedRawSlotCount +=
                    group.capture.sources.rawSlots.size();
                observed.savedMemberCount += group.measured.size();
                observed.savedMeasuredCopyCount += group.measured.size();
                for (std::size_t memberIndex = 0;
                     memberIndex < group.measured.size(); ++memberIndex) {
                    const auto& measured = group.measured[memberIndex];
                    const auto& member =
                        group.capture.members.members[memberIndex].slot.owner;
                    observed.savedMemberDefinitions.push_back(
                        measured.definitionIdentifier);
                    observed.savedMemberOwners.push_back(
                        retained_solid::UUIDText(member.document) + "/"
                        + retained_solid::UUIDText(member.entity) + "/"
                        + retained_solid::UUIDText(member.definition));
                    measuredDefinitions.insert(measured.definitionIdentifier);
                    if (selectedDefinitions.count(measured.definitionIdentifier))
                        ++observed.savedSelectedMemberCount;
                    for (std::size_t prior = 0; prior < memberIndex; ++prior)
                        if (measured.detached.IsSame(
                                group.measured[prior].detached))
                            observed.savedDetachedIdentitiesDistinct = false;
                }
                observed.savedSourceCount += group.productionSources.size();
                for (const auto& source : group.productionSources) {
                    observed.savedSourceOwners.push_back(
                        retained_solid::UUIDText(source.fence.owner.document)
                        + "/"
                        + retained_solid::UUIDText(source.fence.owner.entity)
                        + "/"
                        + retained_solid::UUIDText(source.fence.owner.definition));
                    observed.savedSourceResources.push_back(
                        retained_solid::UUIDText(source.fence.resource));
                    observed.savedSourceMemberIndices.push_back(
                        source.memberIndex);
                    observed.savedSourceFaceIndices.push_back(source.faceIndex);
                    observed.savedSourceOrigins.push_back(
                        std::uint8_t(source.origin));
                    if (source.memberIndex < group.measured.size()) {
                        if (source.origin
                                != painted_atlas_bake::kernel::SourceOrigin::
                                    OwnerMaterialSlot)
                        sourcedDefinitions.insert(
                            group.measured[source.memberIndex]
                                .definitionIdentifier);
                        if (source.faceIndex
                                != std::numeric_limits<std::size_t>::max())
                            ++observed.savedCorrespondenceCount;
                    }
                }
            }
            for (const auto& definition : measuredDefinitions)
                if (sourcedDefinitions.count(definition) == 0)
                    ++observed.savedOriginalOnlyCount;
            observed.savedReceiverMeasuredCopyCount =
                impl.debugSavedMemberReceiverCopies;
            for (const auto& owner : impl.owners) {
                const SavedGroupMeasuredMember* const borrowed =
                    owner.borrowedMeasured;
                if (borrowed == nullptr) continue;
                ++observed.savedBorrowedOwnerCount;
                if (!owner.detachedAuthorityShape.IsSame(borrowed->detached))
                    return false;
                for (const auto& receiver : owner.receivers) {
                    ++observed.savedBorrowedReceiverCount;
                    const Standard_Integer detachedIndex =
                        borrowed->detachedFaces.FindIndex(
                            receiver.disposableFace);
                    if (detachedIndex > 0
                        && std::uint32_t(detachedIndex - 1)
                            == receiver.disposableFaceIndex
                        && receiver.disposableFace.IsSame(
                            borrowed->detachedFaces.FindKey(detachedIndex)))
                        ++observed.savedBorrowedReceiverCopyMatches;
                }
            }
            const Handle(XCAFDoc_ShapeTool) checkpointShapeTool =
                XCAFDoc_DocumentTool::ShapeTool(document->Main());
            TDF_LabelSequence checkpointRoots;
            if (checkpointShapeTool.IsNull()) return false;
            checkpointShapeTool->GetFreeShapes(checkpointRoots);
            if (checkpointRoots.Length()
                    < Standard_Integer(observed.savedMemberCount)) return false;
            observed.savedNonMemberCount = std::size_t(
                checkpointRoots.Length()) - observed.savedMemberCount;
            // Independently re-derive the committed document's export closure
            // before treating a zero borrowed owner/receiver census as the
            // expected case: only a genuinely record-free document (the
            // explicit no-SYDL fixture) relaxes the nonzero receiver-bearing
            // requirement. An unproven or cancelled closure fails closed.
            if (observed.savedBorrowedOwnerCount == 0
                && observed.savedBorrowedReceiverCount == 0) {
                const auto closure =
                    decal_layer::persistence::ReadExportClosure(
                        document, checkpointRoots, cancelled);
                if (closure == decal_layer::persistence::ExportClosureState::
                        Unproven
                    || closure == decal_layer::persistence::
                        ExportClosureState::Cancelled) return false;
                observed.savedReceiverExpectationEmpty = closure
                    == decal_layer::persistence::ExportClosureState::Absent;
            }
            observed.savedMeasuredStageComplete =
                observed.savedMeasuredCopyCount == observed.savedMemberCount
                && observed.savedReceiverMeasuredCopyCount == 0
                && (observed.savedReceiverExpectationEmpty
                    ? observed.savedBorrowedOwnerCount == 0
                    : observed.savedBorrowedOwnerCount != 0)
                && (observed.savedReceiverExpectationEmpty
                    ? observed.savedBorrowedReceiverCount == 0
                    : observed.savedBorrowedReceiverCount != 0)
                && observed.savedBorrowedReceiverCopyMatches
                    == observed.savedBorrowedReceiverCount
                && observed.savedSourceCount != 0
                && observed.savedCanonicalLengths.size()
                    == 2U * observed.savedGroupCount
                && observed.savedDetachedIdentitiesDistinct;
            observed.savedArtifactPresent = false;
            return false;
        }
#endif
        if (!impl.recheckProtected(cancelled,
                decal_layer::bake::accounting::FailureSite::
                    ProtectedRecheckStorage))
            return false;
#ifdef DEBUG
        if (debugProtectedCaptureMode == 1) {
            DebugProtectedCaptureObservation observation;
            observation.observed = true;
            observation.completed = true;
            observation.firstFailure = std::size_t(
                impl.operationLedger.firstFailureSite());
            observation.ownerCount = impl.owners.size();
            for (const auto& owner : impl.owners) {
                observation.receiverCount += owner.receivers.size();
                observation.sourceCount += owner.paintedSources.size();
                observation.canonicalBytes += owner.canonicalBytes.size();
                for (const auto& source : owner.paintedSources) {
                    observation.resourceBytes +=
                        source.envelope.originalBytes.size();
                    observation.resourceBytes +=
                        source.envelope.workingBytes.size();
                }
            }
            observation.liveBytes = impl.operationLedger.totalLive();
            RecordDebugProtectedCapture(observation);
        }
#endif
        capture = std::move(candidate);
        return true;
    } catch (...) {
        capture.reset();
        return false;
    }
}

bool OcctSceneSnapshotBuilder::FinalizePrivateExportDecals(
    PrivateDecalCapture& capture,
    const SceneSnapshot& finalScene,
    const std::vector<PrivateExportFaceCorrespondence>& correspondence,
    const std::vector<PrivateExportFinalMesh>& emittedMeshes,
    const std::function<bool()>& cancelled,
    PrivateExportDecalArtifact& artifact) noexcept {
    artifact = {};
    if (!capture.impl_ || !cancelled || !IsValidSceneSnapshot(finalScene))
        return false;
    try {
        auto& impl = *capture.impl_;
        using Dimension = decal_layer::bake::accounting::StorageDimension;
        using FailureSite = decal_layer::bake::accounting::FailureSite;
        using Retention = decal_layer::bake::accounting::Retention;
        struct ClearOnFailure final {
            PrivateDecalCapture::Impl& impl;
            PrivateExportDecalArtifact& artifact;
            bool completed = false;
            ~ClearOnFailure() {
                if (completed) return;
                artifact = {};
                impl.destination.clear();
            }
        } clearOnFailure{impl, artifact};
        if (!impl.recheckProtected(cancelled,
                FailureSite::ProtectedRecheckStorage)) return false;
        if (finalScene.metersPerUnit != impl.metersPerUnit
            || correspondence.size() > kMaxPrimitiveBindingsPerSnapshot
            || emittedMeshes.size() > kMaxLabelInstanceMappings)
            return false;
        if (impl.owners.empty() || emittedMeshes.empty()
            || impl.destination.values.size() != emittedMeshes.size()
            || impl.privateDocument.IsNull()) return false;
        std::size_t correspondenceBytes = 0;
        if (!impl.operationLedger.checkedProduct(correspondence.size(),
                sizeof(PrivateExportFaceCorrespondence), 1U,
                correspondenceBytes,
                FailureSite::ProtectedCorrespondenceStorage)) return false;
        for (const auto& value : correspondence)
            if (!AddProtectedBytes(correspondenceBytes,
                    value.ownerDefinitionIdentifier.capacity() + 1U))
                return false;
        if (!AcquireProtectedStorage(impl.finalCorrespondenceTicket,
                impl.operationLedger.view(), Dimension::PrivateStorage,
                correspondenceBytes, Retention::Retained,
                FailureSite::ProtectedCorrespondenceStorage))
            return false;

        std::size_t evidenceBytes = 0;
        if (!impl.operationLedger.checkedProduct(
                impl.destination.values.size(),
                2U * sizeof(std::string) + 130U, 1U, evidenceBytes,
                FailureSite::ProtectedEvidenceStorage)
            || !AcquireProtectedStorage(impl.finalEvidenceTicket,
                impl.operationLedger.view(), Dimension::PrivateStorage,
                evidenceBytes, Retention::Retained,
                FailureSite::ProtectedEvidenceStorage))
            return false;
        artifact.inputKeys.reserve(impl.destination.values.size());
        artifact.bakeSeals.reserve(impl.destination.values.size());
        artifact.correspondence.reserve(correspondence.size());

        std::size_t matchedReceivers = 0;
        for (const auto& owner : impl.owners) {
            for (const auto& receiver : owner.receivers) {
                const auto count = std::count_if(correspondence.begin(),
                    correspondence.end(), [&](const auto& value) {
                        return value.ownerDefinitionIdentifier
                                == owner.definitionIdentifier
                            && value.originalFaceIndex
                                == receiver.originalFaceIndex;
                    });
                if (count != 1) return false;
                ++matchedReceivers;
            }
        }
        if (matchedReceivers != correspondence.size()) return false;
        for (const auto& emitted : emittedMeshes) {
            if (emitted.ownerDefinitionIdentifier.empty()
                || emitted.mesh.definitionIdentifier.empty()
                || emitted.instance.entityIdentifier.empty()
                || emitted.instance.decalDerivedAppearances.empty())
                return false;
            const auto owner = std::find_if(impl.owners.begin(),
                impl.owners.end(), [&](const auto& value) {
                    return value.definitionIdentifier
                        == emitted.ownerDefinitionIdentifier;
                });
            if (owner == impl.owners.end()
                || emitted.mesh.paintedAtlasMasterDefinitionIdentifier
                    != owner->definitionIdentifier)
                return false;
            const auto finalInstance = std::find_if(finalScene.instances.begin(),
                finalScene.instances.end(), [&](const auto& value) {
                    return value.entityIdentifier
                        == emitted.instance.entityIdentifier;
                });
            if (finalInstance == finalScene.instances.end()
                || finalInstance->meshIndex >= finalScene.meshes.size()
                || finalInstance->meshIndex != emitted.instance.meshIndex)
                return false;
            const auto& finalMesh = finalScene.meshes[finalInstance->meshIndex];
            if (finalMesh.definitionIdentifier
                    != emitted.mesh.definitionIdentifier
                || finalMesh.paintedAtlasMasterDefinitionIdentifier
                    != emitted.mesh.paintedAtlasMasterDefinitionIdentifier
                || finalMesh.paintedAtlasBakeProof
                    != emitted.mesh.paintedAtlasBakeProof
                || finalMesh.vertices.size() != emitted.mesh.vertices.size()
                || finalMesh.indices != emitted.mesh.indices
                || !SamePrimitives(
                    finalMesh.primitives, emitted.mesh.primitives)
                || finalMesh.cornerTangents.size()
                    != emitted.mesh.cornerTangents.size()
                || (finalMesh.vertices.size() != 0
                    && std::memcmp(finalMesh.vertices.data(),
                        emitted.mesh.vertices.data(),
                        finalMesh.vertices.size() * sizeof(Vertex)) != 0)
                || (finalMesh.cornerTangents.size() != 0
                    && std::memcmp(finalMesh.cornerTangents.data(),
                        emitted.mesh.cornerTangents.data(),
                        finalMesh.cornerTangents.size() * sizeof(Float4)) != 0))
                return false;
            for (const auto& appearance :
                    emitted.instance.decalDerivedAppearances)
                if (appearance.ownerDefinitionIdentifier
                        != owner->definitionIdentifier)
                    return false;
        }
        for (const auto& value : impl.destination.values) {
            decal_layer::bake::PublishedDerivative reopened;
            if (!decal_layer::bake::publication::Valid(value)
                || !decal_layer::bake::publication::Lookup(
                    impl.destination, value.owner, value.inputKey, reopened)
                || reopened.bakeKey != value.bakeKey) return false;
            artifact.inputKeys.push_back(DecalDigestText(value.inputKey));
            artifact.bakeSeals.push_back(DecalDigestText(value.bakeKey));
        }
        if (!impl.recheckProtected(cancelled,
                FailureSite::ProtectedRecheckStorage)) return false;
        SceneCopyStorage sceneBytes;
        constexpr std::size_t maximumControlBytes = 4096U;
        if (!DeepSceneStorageBytes(finalScene, sceneBytes)
            || !AcquireProtectedStorage(impl.terminalSceneObjectTicket,
                impl.operationLedger.view(), Dimension::PrivateStorage,
                sizeof(SceneSnapshot), Retention::Retained,
                FailureSite::ProtectedTerminalScene)
            || !AcquireProtectedStorage(impl.terminalSceneNumericTicket,
                impl.operationLedger.view(), Dimension::SnapshotNumeric,
                sceneBytes.numeric, Retention::Retained,
                FailureSite::ProtectedTerminalScene)
            || !AcquireProtectedStorage(impl.terminalSceneEncodedTicket,
                impl.operationLedger.view(), Dimension::EncodedTexture,
                sceneBytes.encoded, Retention::Retained,
                FailureSite::ProtectedTerminalScene)
            || !AcquireProtectedStorage(impl.terminalScenePrivateTicket,
                impl.operationLedger.view(), Dimension::PrivateStorage,
                sceneBytes.privateBytes, Retention::Retained,
                FailureSite::ProtectedTerminalScene)
            || !impl.terminalSceneControlTicket.acquire(
                impl.operationLedger.view(), Dimension::PrivateStorage,
                maximumControlBytes, Retention::Retained,
                FailureSite::ProtectedTerminalControl))
            return false;
        SceneSnapshot* returned = nullptr;
        try { returned = new SceneSnapshot(finalScene); }
        catch (const std::bad_alloc&) {
            impl.operationLedger.allocationFailure(
                FailureSite::ProtectedTerminalScene);
            return false;
        }
        try {
            artifact.scene = std::shared_ptr<const SceneSnapshot>(returned,
                std::default_delete<const SceneSnapshot>(),
                ProtectedControlAllocator<SceneSnapshot>(
                    impl.operationLedger.view(),
                    impl.terminalSceneControlTicket,
                    FailureSite::ProtectedTerminalControl));
        } catch (...) {
            artifact = {};
            return false;
        }
        artifact.correspondence = correspondence;
        SceneCopyStorage copiedSceneBytes;
        std::size_t copiedCorrespondenceBytes = 0;
        if (!artifact.scene || !DeepSceneStorageBytes(
                *artifact.scene, copiedSceneBytes)
            || copiedSceneBytes.numeric > impl.terminalSceneNumericTicket.bytes
            || copiedSceneBytes.encoded > impl.terminalSceneEncodedTicket.bytes
            || copiedSceneBytes.privateBytes
                > impl.terminalScenePrivateTicket.bytes
            || !impl.operationLedger.checkedProduct(
                artifact.correspondence.capacity(),
                sizeof(PrivateExportFaceCorrespondence), 1U,
                copiedCorrespondenceBytes,
                FailureSite::ProtectedCorrespondenceStorage)) {
            artifact = {};
            return false;
        }
        for (const auto& value : artifact.correspondence)
            if (!AddProtectedBytes(copiedCorrespondenceBytes,
                    value.ownerDefinitionIdentifier.capacity() + 1U)) {
                artifact = {};
                return false;
            }
        if (copiedCorrespondenceBytes > impl.finalCorrespondenceTicket.bytes
            || !IsValidSceneSnapshot(*artifact.scene)
            || !impl.recheckProtected(cancelled,
                FailureSite::ProtectedRecheckStorage)) {
            artifact = {};
            return false;
        }
        clearOnFailure.completed = true;
        return true;
    } catch (const std::bad_alloc&) {
        capture.impl_->operationLedger.allocationFailure(
            decal_layer::bake::accounting::FailureSite::
                ProtectedTerminalScene);
        artifact = {};
        return false;
    } catch (...) {
        capture.impl_->operationLedger.refuse(
            decal_layer::bake::accounting::FailureSite::
                ProtectedRecheckStorage);
        artifact = {};
        return false;
    }
}

#ifdef DEBUG
std::array<std::size_t, 4> DebugExerciseE4ResolveDecalImageReadPreflight(
    const Handle(OcctDocument)& document,
    const decal_layer::ImageRef& reference) noexcept
{
    using FailureSite = decal_layer::bake::accounting::FailureSite;
    std::array<std::size_t, 4> result{};
    try {
        OperationLedger denied(0, 0, 0);
        decal_layer::bake::ResolvedImage resolved;
        gDebugResolveReadResourceEntries = 0;
        result[0] = !ResolveDecalImage(
            document, reference, resolved, denied.view());
        result[1] = gDebugResolveReadResourceEntries;
        result[2] = resolved.envelope.originalBytes.empty()
            && resolved.envelope.workingBytes.empty()
            && resolved.pixels.width == 0
            && resolved.pixels.height == 0
            && resolved.pixels.rgba.empty()
            && resolved.originalBytesTicket.bytes == 0
            && resolved.workingBytesTicket.bytes == 0
            && resolved.pixelTicket.bytes == 0
            && !resolved.originalMeasured
            && !resolved.workingMeasured;
        result[3] = denied.firstFailureSite()
            == FailureSite::ResourceTableScratch;
        gDebugResolveReadResourceEntries = 0;
        return result;
    } catch (...) {
        gDebugResolveReadResourceEntries = 0;
        return {};
    }
}

std::array<std::size_t, 10> DebugExerciseE4FaceImageValidation(
    const std::vector<std::uint8_t>& bytes) noexcept
{
    std::array<std::size_t, 10> result{};
    @autoreleasepool {
        try {
            if (bytes.size() < 33
                || std::memcmp(bytes.data(), "\x89PNG\r\n\x1a\n", 8) != 0)
                return result;
            std::vector<std::uint8_t> oversized = bytes;
            const std::uint32_t width =
                std::uint32_t(face_image::kMaximumImageDimension) + 1U;
            oversized[16] = std::uint8_t(width >> 24);
            oversized[17] = std::uint8_t(width >> 16);
            oversized[18] = std::uint8_t(width >> 8);
            oversized[19] = std::uint8_t(width);
            std::uint32_t crc = 0xFFFFFFFFU;
            for (std::size_t index = 12; index < 29; ++index) {
                crc ^= oversized[index];
                for (unsigned bit = 0; bit < 8; ++bit)
                    crc = (crc >> 1)
                        ^ (0xEDB88320U & (0U - (crc & 1U)));
            }
            crc ^= 0xFFFFFFFFU;
            oversized[29] = std::uint8_t(crc >> 24);
            oversized[30] = std::uint8_t(crc >> 16);
            oversized[31] = std::uint8_t(crc >> 8);
            oversized[32] = std::uint8_t(crc);

            OperationLedger rejected(96U * 1024U * 1024U,
                96U * 1024U * 1024U, 128U * 1024U * 1024U);
            FaceImageValidationAdmission rejectedAdmission;
            rejectedAdmission.operation = rejected.view();
            const face_image::validation::FaceImageRasterOptions rejectedOptions{
                &rejectedAdmission, &AdmitFaceImageValidationSource,
                &AdmitFaceImageValidationDecoded,
                &EnterFaceImageValidationDecode};
            NSData *oversizedData = [NSData dataWithBytes:oversized.data()
                length:oversized.size()];
            face_image::validation::FaceImageRasterInfo rejectedInfo;
            result[0] = !face_image::validation::MeasureFaceImageRaster(
                oversizedData, rejectedInfo, rejectedOptions);
            result[1] = rejected.allocationEntries(
                decal_layer::bake::accounting::FailureSite::
                    FaceImageValidationDecode);
            result[2] = rejected.peak(
                decal_layer::bake::accounting::StorageDimension::PrivateStorage);

            OperationLedger admitted(96U * 1024U * 1024U,
                96U * 1024U * 1024U, 128U * 1024U * 1024U);
            FaceImageValidationAdmission admittedTickets;
            admittedTickets.operation = admitted.view();
            const face_image::validation::FaceImageRasterOptions admittedOptions{
                &admittedTickets, &AdmitFaceImageValidationSource,
                &AdmitFaceImageValidationDecoded,
                &EnterFaceImageValidationDecode};
            NSData *validData = [NSData dataWithBytes:bytes.data()
                length:bytes.size()];
            face_image::validation::FaceImageRasterInfo inheritedInfo;
            face_image::validation::FaceImageRasterInfo controlInfo;
            result[3] = face_image::validation::MeasureFaceImageRaster(
                validData, inheritedInfo, admittedOptions);
            result[4] = face_image::validation::MeasureFaceImageRaster(
                validData, controlInfo);
            result[5] = inheritedInfo.width;
            result[6] = inheritedInfo.height;
            result[7] = inheritedInfo.hasAlpha ? 1U : 0U;
            result[8] = result[3] && result[4]
                && inheritedInfo.format == controlInfo.format
                && inheritedInfo.width == controlInfo.width
                && inheritedInfo.height == controlInfo.height
                && inheritedInfo.hasAlpha == controlInfo.hasAlpha;
            result[9] = admitted.allocationEntries(
                decal_layer::bake::accounting::FailureSite::
                    FaceImageValidationDecode);
            return result;
        } catch (...) {
            return {};
        }
    }
}

std::array<std::size_t, 18> DebugExerciseE4OperationLedger() noexcept
{
    using FailureSite = decal_layer::bake::accounting::FailureSite;
    using Job = decal_layer::bake::accounting::Job;
    using Retention = decal_layer::bake::accounting::Retention;
    using StorageDimension =
        decal_layer::bake::accounting::StorageDimension;
    using Ticket = decal_layer::bake::accounting::Ticket;
    std::array<std::size_t, 18> result{};

    OperationLedger exact(16, 16, 16);
    result[0] = exact.reserve(StorageDimension::PrivateStorage, 16,
            Retention::Scratch, FailureSite::DebugExactLimit)
        && exact.live(StorageDimension::PrivateStorage) == 16;
    result[2] = !exact.reserve(StorageDimension::PrivateStorage, 1,
        Retention::Scratch, FailureSite::DebugOneUnit);
    const auto sticky = exact.view();
    result[3] = !sticky.Recheck(FailureSite::ProtectedSceneCopy);
    result[4] = !sticky.Recheck(FailureSite::JobConsume);
    result[5] = !sticky.Recheck(FailureSite::StorageReserve);
    result[6] = !sticky.Recheck(FailureSite::JobSeal);
    result[7] = !sticky.Recheck(FailureSite::ContextControl);

    OperationLedger overflow(16, 16, 16);
    result[1] = !overflow.reserve(StorageDimension::PrivateStorage,
        std::numeric_limits<std::size_t>::max(), Retention::Scratch,
        FailureSite::DebugOneUnit);

    OperationLedger multiplied(64, 64, 64);
    std::size_t product = 0;
    result[13] = !multiplied.view().CheckedProduct(
        std::numeric_limits<std::size_t>::max(), 2, 1, product,
        FailureSite::DebugCheckedProduct)
        && product == 0
        && multiplied.firstFailureSite()
            == FailureSite::DebugCheckedProduct;

    OperationLedger copies(64, 64, 64);
    const auto copyView = copies.view();
    result[8] = copyView.Reserve(StorageDimension::PrivateStorage, 8,
            Retention::Retained, FailureSite::DebugCopyOne)
        && copyView.Reserve(StorageDimension::PrivateStorage, 8,
            Retention::Retained, FailureSite::DebugCopyTwo)
        && copies.live(StorageDimension::PrivateStorage) == 16
        && copies.retained(StorageDimension::PrivateStorage) == 16;

    OperationLedger shared(64, 64, 64);
    result[9] = shared.view().Reserve(StorageDimension::PrivateStorage, 8,
            Retention::Retained, FailureSite::DebugShared)
        && shared.live(StorageDimension::PrivateStorage) == 8
        && shared.retained(StorageDimension::PrivateStorage) == 8;

    OperationLedger moved(64, 64, 64);
    {
        Ticket first;
        result[10] = first.acquire(moved.view(),
            StorageDimension::PrivateStorage, 8, Retention::Scratch,
            FailureSite::DebugMove);
        Ticket second(std::move(first));
        result[10] = result[10]
            && moved.live(StorageDimension::PrivateStorage) == 8;
    }
    result[10] = result[10]
        && moved.live(StorageDimension::PrivateStorage) == 0;

    OperationLedger scratch(64, 64, 64);
    {
        Ticket ticket;
        result[11] = ticket.acquire(scratch.view(),
            StorageDimension::PrivateStorage, 8, Retention::Scratch,
            FailureSite::DebugScratch);
    }
    result[11] = result[11]
        && scratch.live(StorageDimension::PrivateStorage) == 0
        && scratch.peak(StorageDimension::PrivateStorage) == 8;
    result[12] = scratch.sealJob(
            Job::Debug, 5, FailureSite::DebugWork)
        && scratch.consumeJob(Job::Debug, 5, FailureSite::DebugWork)
        && scratch.cumulativeWork() == 5
        && scratch.reserve(StorageDimension::PrivateStorage, 4,
            Retention::Scratch, FailureSite::DebugWork);
    scratch.release(StorageDimension::PrivateStorage, 4,
        Retention::Scratch);
    result[12] = result[12] && scratch.cumulativeWork() == 5;

    OperationLedger duplicate(64, 64, 64);
    result[14] = duplicate.sealJob(
            Job::Debug, 5, FailureSite::DebugDuplicateJob)
        && !duplicate.sealJob(
            Job::Debug, 5, FailureSite::DebugDuplicateJob)
        && duplicate.firstFailureSite()
            == FailureSite::DebugDuplicateJob;

    OperationLedger jobLimit(64, 64, 64);
    result[15] = jobLimit.sealJob(
            Job::Debug, 5, FailureSite::DebugJobLimit)
        && jobLimit.consumeJob(
            Job::Debug, 5, FailureSite::DebugJobLimit)
        && !jobLimit.consumeJob(
            Job::Debug, 1, FailureSite::DebugJobLimit)
        && jobLimit.firstFailureSite() == FailureSite::DebugJobLimit;

    result[16] = std::max({exact.peak(StorageDimension::PrivateStorage),
        copies.peak(StorageDimension::PrivateStorage),
        shared.peak(StorageDimension::PrivateStorage),
        moved.peak(StorageDimension::PrivateStorage),
        scratch.peak(StorageDimension::PrivateStorage)});
    result[17] = scratch.cumulativeWork();
    return result;
}

std::array<std::size_t, 6> DebugExerciseE4MikkAllocationFailure() noexcept
{
    using Dimension = decal_layer::bake::accounting::StorageDimension;
    using Retention = decal_layer::bake::accounting::Retention;
    using Site = decal_layer::bake::accounting::FailureSite;
    std::array<std::size_t, 6> result{};
    OperationLedger ledger(1024 * 1024, 1024 * 1024, 1024 * 1024);
    std::vector<Vertex> vertices(3);
    vertices[0].positionX = 0; vertices[0].positionY = 0;
    vertices[1].positionX = 1; vertices[1].positionY = 0;
    vertices[2].positionX = 0; vertices[2].positionY = 1;
    vertices[0].normalZ = vertices[1].normalZ = vertices[2].normalZ = 1;
    vertices[0].textureU = 0; vertices[0].textureV = 0;
    vertices[1].textureU = 1; vertices[1].textureV = 0;
    vertices[2].textureU = 0; vertices[2].textureV = 1;
    const std::vector<std::uint32_t> indices{0, 1, 2};
    decal_layer::bake::accounting::Ticket outputTicket;
    std::vector<Float4> output;
    mikkDebugFailNextAllocationAtSite(1);
    const auto status = GenerateAccountedMikkCornerTangents(
        vertices, indices, true, ledger.view(), outputTicket, output);
    mikkDebugFailNextAllocationAtSite(0);
    result[0] = status == TangentSpaceError::GenerationFailed;
    result[1] = output.empty() && outputTicket.bytes == 0;
    result[2] = ledger.firstFailureSite() == Site::TangentWorkspace;
    decal_layer::bake::accounting::Ticket installTicket;
    result[3] = !installTicket.acquire(ledger.view(),
        Dimension::PrivateStorage, 1, Retention::Retained,
        Site::InstallTextureCopy);
    result[4] = ledger.allocationEntries(Site::InstallTextureCopy);
    result[5] = !ledger.recheck(Site::InstallTextureCopy)
        && result[4] == 0
        && ledger.firstFailureSite() == Site::TangentWorkspace;
    return result;
}

std::array<std::size_t, 16> DebugExerciseE4SourceDecodeAdmission(
    const std::vector<std::uint8_t>& bytes) noexcept
{
    using FailureSite = decal_layer::bake::accounting::FailureSite;
    constexpr std::size_t encodedLimit = 64U * 1024U * 1024U;
    constexpr std::size_t privateLimit = 128U * 1024U * 1024U;
    std::array<std::size_t, 16> result{};

    OperationLedger denied(96U * 1024U * 1024U, encodedLimit, 0);
    painted_atlas_bake::kernel::Image refused;
    result[0] = !painted_atlas_bake::kernel::DecodeImage(
        bytes, refused, denied.view());
    result[1] = denied.firstFailureSite()
        == FailureSite::ImageDecodedBacking;
    result[2] = denied.allocationEntries(FailureSite::ImageCreate);
    result[3] = denied.allocationEntries(FailureSite::ImageRGBA);

    OperationLedger normal(96U * 1024U * 1024U, encodedLimit, privateLimit);
    painted_atlas_bake::kernel::Image first;
    painted_atlas_bake::kernel::Image second;
    result[4] = painted_atlas_bake::kernel::DecodeImage(
        bytes, first, normal.view());
    result[5] = first.width;
    result[6] = first.height;
    result[7] = first.rgba.size();
    result[8] = result[4]
        && painted_atlas_bake::kernel::DecodeImage(
            bytes, second, normal.view())
        && first.width == second.width && first.height == second.height
        && first.rgba == second.rgba;
    result[9] = normal.allocationEntries(FailureSite::ImageCreate);
    const std::size_t liveBeforeReplacement = normal.live(
        decal_layer::bake::accounting::StorageDimension::PrivateStorage);
    result[10] = painted_atlas_bake::kernel::DecodeImage(
        bytes, first, normal.view());
    result[11] = result[10]
        && normal.live(decal_layer::bake::accounting::StorageDimension::PrivateStorage)
            == liveBeforeReplacement;

    painted_atlas_bake::kernel::Image standalone;
    result[12] = painted_atlas_bake::kernel::DecodeImage(bytes, standalone)
        && painted_atlas_bake::kernel::DecodeImage(bytes, standalone)
        && !standalone.rgba.empty() && standalone.operationOwner.valid();

    OperationLedger inputLedger(96U * 1024U * 1024U,
        encodedLimit, privateLimit);
    decal_layer::bake::Input input;
    input.operationLedger = inputLedger.view();
    decal_layer::bake::ResolvedLayer layer;
    result[13] = layer.image.pixelTicket.acquire(inputLedger.view(),
        decal_layer::bake::accounting::StorageDimension::PrivateStorage,
        16, decal_layer::bake::accounting::Retention::Retained,
        FailureSite::ImageRGBA)
        && inputLedger.enterAllocation(FailureSite::ImageRGBA);
    if (result[13]) {
        layer.image.pixels.width = 2;
        layer.image.pixels.height = 2;
        layer.image.pixels.rgba.resize(16);
        input.layers.push_back(std::move(layer));
        input = decal_layer::bake::Input{};
        result[13] = inputLedger.live(
                decal_layer::bake::accounting::StorageDimension::PrivateStorage) == 0
            && inputLedger.recheck(FailureSite::ImageRGBA);
    }

    SceneSnapshot scene;
    scene.publicationSourceIdentifier = "debug-scene-copy";
    scene.meshes.reserve(1);
    SceneCopyStorage sceneStorage;
    OperationLedger sceneDenied(0, 0, 0);
    decal_layer::bake::accounting::Ticket sceneTicket;
    result[14] = DeepSceneStorageBytes(scene, sceneStorage)
        && !sceneTicket.acquire(sceneDenied.view(),
            decal_layer::bake::accounting::StorageDimension::SnapshotNumeric,
            sceneStorage.numeric,
            decal_layer::bake::accounting::Retention::Retained,
            FailureSite::ProtectedSceneCopy)
        && sceneDenied.allocationEntries(FailureSite::ProtectedSceneCopy) == 0
        && scene.meshes.empty();

    auto owned = decal_layer::bake::accounting::MakeOperationOwner();
    result[15] = owned.valid()
        && owned.view.Recheck(FailureSite::ContextControl);
    return result;
}

